KB.add({"board":"10","title":"世界古代文明、中世纪与丝路地理","note":"交大考过：封建采邑制（2021名解）、维京人（2026名解）、印度教三大主神（2021选择）、汗血宝马原产地（2026选择）；更早考过两河流域（2010选择、2016名解）、中世纪（2012选择、2017名解）、文艺复兴三杰（2012选择）、波斯（2013、2015名解）、狮身人面像与金字塔、爱琴海（2016名解）、尼罗河、伊朗高原、地中海（2017名解）、张骞通西域中的身毒和安息（2011选择）、河西走廊、帕米尔高原、塔克拉玛干、苏门答腊、马可·波罗（2010选择）。名解常把“文明—河流—帝国—地理”放在同一段材料里出成一组，复习时按组记。","clusters":[{"cid":"10a","name":"大河文明：两河、埃及、印度与美洲","line":"最早的文明都依托大河：两河流域有楔形文字、《汉谟拉比法典》，后经亚述、新巴比伦；尼罗河孕育古埃及的象形文字、金字塔与狮身人面像；印度河文明之后，雅利安人带来吠陀文化、婆罗门教和种姓制度，演变为印度教；加上黄河长江的中国，合称四大文明古国；美洲另有玛雅、阿兹特克、印加三大古文明。"},{"cid":"10b","name":"波斯、腓尼基与罗马：地中海世界","line":"伊朗高原上的波斯帝国横跨亚非欧，信琐罗亚斯德教，西进引发希波战争；腓尼基人航行地中海并创造字母，其殖民城市迦太基与罗马争霸；罗马由共和走向帝国，留下《十二铜表法》与罗马法，基督教在帝国内由受迫害变为国教，犹太人在此期间流散各地。"},{"cid":"10c","name":"丝绸之路与西域","line":"西汉张骞两次出使西域“凿空”，西域诸国（大宛、大月氏、乌孙、安息、身毒、大夏）与今地一一对应；陆路经河西走廊、越葱岭（帕米尔）、绕塔克拉玛干沙漠西行，东汉甘英远至波斯湾欲通大秦；海上丝绸之路经马六甲海峡通往印度洋；元代马可·波罗东来，游记激发欧洲对东方的向往。"},{"cid":"10d","name":"中世纪欧洲：从476年到1453年","line":"476年西罗马帝国灭亡开启中世纪：法兰克王国与查理曼帝国之后，西欧形成封建采邑制、庄园制和骑士制度，教会以经院哲学统领思想，中世纪大学兴起；维京人南下引出诺曼征服；十字军东征沟通东西，《大宪章》限制王权，黑死病与百年战争动摇旧秩序；东边拜占庭延续千年，1453年君士坦丁堡被奥斯曼攻陷，常作为中世纪结束的标志之一；阿拉伯帝国的百年翻译运动保存了希腊学术。"},{"cid":"10e","name":"近代开端：文艺复兴、宗教改革、地理大发现与科学革命","line":"14至16世纪，意大利文艺复兴以人文主义反对神权（文坛三杰、美术三杰）；1517年马丁·路德发起宗教改革，印刷术加速其传播；迪亚士、哥伦布、达·伽马、麦哲伦开辟新航路，西班牙、葡萄牙、荷兰相继称雄海上；哥白尼、伽利略到牛顿完成科学革命，为启蒙运动铺路。"},{"cid":"10f","name":"启蒙运动与资产阶级革命","line":"17至18世纪启蒙思想家（洛克、孟德斯鸠、伏尔泰、卢梭、狄德罗）提出天赋人权、三权分立、社会契约，并转化为三场革命的文献：英国光荣革命与《权利法案》确立君主立宪，美国《独立宣言》与1787年宪法建立共和，法国大革命与《人权宣言》《拿破仑法典》传播革命原则；19世纪各国以不同方式完成资本主义转型（美国内战、明治维新、德意统一）。"},{"cid":"10g","name":"三次工业革命与两次世界大战","line":"工业革命从英国棉纺织业起步，蒸汽机带来蒸汽时代，19世纪70年代电力开启电气时代，20世纪中叶原子能、电子计算机开启信息时代；列强争夺引发第一次世界大战，战后凡尔赛-华盛顿体系与十月革命改变格局，经济大危机与绥靖政策导致第二次世界大战，战后雅尔塔体系与联合国奠定秩序，随后进入冷战（冷战、马歇尔计划、北约见板块13），1991年苏联解体冷战结束。"},{"cid":"10h","name":"西方艺术史：美术、建筑、音乐","line":"建筑由古希腊柱式、罗马式到哥特式；美术由文艺复兴三杰，经巴洛克、洛可可、新古典主义、浪漫主义、现实主义，到印象派、后印象派与20世纪立体主义、超现实主义；音乐由巴洛克的巴赫，到维也纳古典乐派海顿、莫扎特、贝多芬，再到浪漫主义的舒伯特、肖邦、柴可夫斯基等。"},{"cid":"10i","name":"世界地理常识：之最、海峡运河与首都","line":"先记七大洲四大洋与大洲分界线，再按河、湖、山、原、漠、岛、海记“之最”，然后记沟通大洋的海峡与运河（马六甲、直布罗陀、霍尔木兹、苏伊士、巴拿马）以及易错首都和国家别称；名解常把“文明、河流、帝国、地理”放在同一段材料里出题。"}],"entries":[{"id":"b09-060","t":"罗塞塔石碑","cid":"10i","p":3,"kind":"常识","exam":[],"alias":[],"one":"1799年在埃及发现，刻有圣书体象形文字、世俗体文字和古希腊文三种文字，18","ans":"1799年在埃及发现，刻有圣书体象形文字、世俗体文字和古希腊文三种文字，1822年商博良据此释读古埃及象形文字；见板块10","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-001","t":"两河流域","cid":"10a","p":1,"kind":"地理","exam":["2010选择","2016名解"],"alias":["美索不达米亚","两河文明"],"one":"幼发拉底河与底格里斯河流域，今伊拉克一带，苏美尔、巴比伦文明所在。","ans":"两河流域指**西亚幼发拉底河与底格里斯河之间及周边地区**，希腊语称**“美索不达米亚”**（两河之间的地方），大体在今伊拉克境内，是**人类最早的文明发源地之一**。约前3500年起苏美尔人在南部建立城邦，创造**刻在泥板上的楔形文字**；约前18世纪古巴比伦国王**汉谟拉比统一两河流域，颁布《汉谟拉比法典》**，这是现存最早较完整的成文法典。此后亚述、新巴比伦相继兴起，**前539年为波斯所灭**。史诗《吉尔伽美什》、六十进制是其重要成就。","pts":["幼发拉底河、底格里斯河，今伊拉克","苏美尔城邦、楔形文字、汉谟拉比与法典","前539年亡于波斯；史诗、六十进制"],"mem":"河名口诀（自编）：“幼底两河”，即幼发拉底、底格里斯。朝代接力按“苏、巴、亚、新”：苏美尔、古巴比伦、亚述、新巴比伦，最后被波斯收走。画面：苏美尔人拿芦苇秆在湿泥板上压出楔子，泥板晒干就是书；汉谟拉比把法条刻进石柱立在城里。","mix":"“两河”指幼发拉底河与底格里斯河，选择题常用尼罗河、印度河、恒河做干扰项；两河流域在今伊拉克，印度河文明主体在今巴基斯坦。","mcq":[{"q":"古代两河流域文明所依托的两条河流是","o":["尼罗河与底格里斯河","印度河与恒河","幼发拉底河与底格里斯河","黄河与长江"],"a":2,"w":"两河指幼发拉底河与底格里斯河，希腊语“美索不达米亚”意为两河之间的地方。"},{"q":"约前539年灭亡新巴比伦、统一两河流域的是","o":["波斯","亚述","马其顿","罗马"],"a":0,"w":"居鲁士二世于前539年灭新巴比伦，两河流域并入波斯帝国。"}],"rel":[{"t":"楔形文字","n":"两河流域的文字"},{"t":"《汉谟拉比法典》","n":"古巴比伦成文法典"},{"t":"《吉尔伽美什》","n":"两河流域史诗"},{"t":"波斯帝国","n":"前539年统一两河"},{"t":"四大文明古国","n":"古巴比伦位列其中"}],"more":"希腊语“美索不达米亚”意为“两河之间的地方”。\n苏美尔人发明六十进制，今天1小时60分、1分60秒、圆周360度均与此有渊源。"},{"id":"b10-002","t":"古埃及文明","cid":"10a","p":1,"kind":"概念","exam":["2016名解","2017名解"],"alias":["古埃及","埃及文明"],"one":"尼罗河流域文明，法老统治，有金字塔、象形文字和太阳历。","ans":"古埃及文明是**非洲东北部尼罗河流域的古代文明**，希罗多德称**“埃及是尼罗河的赠礼”**。约前3100年**美尼斯统一上下埃及**，建立以**法老**为最高统治者的中央集权国家。古王国时期大规模修建**金字塔**，吉萨胡夫金字塔最大，**狮身人面像**据考建于哈夫拉法老时期。古埃及人创造**象形文字、纸莎草纸和太阳历**，掌握木乃伊制作与几何测量。此后先后被波斯（前525）、亚历山大（前332）征服，**前30年并入罗马**。","pts":["尼罗河流域文明，“尼罗河的赠礼”","约前3100年统一，法老，金字塔与狮身人面像","象形文字、太阳历；前30年并入罗马"],"mem":"三个年份串起兴衰：前3100统一，前525波斯，前30罗马。逻辑线：尼罗河定期泛滥，所以要观测星象，所以有太阳历；洪水退后要重新量地，所以有几何；余粮养出法老，法老给自己造金字塔，石壁上刻象形字。","mix":"古埃及的文字是象形文字（写在纸莎草纸上），两河流域的是楔形文字（压在泥板上）；释读象形文字靠1799年发现的罗塞塔石碑，1822年由商博良完成。","mcq":[{"q":"“埃及是尼罗河的赠礼”这一说法出自","o":["修昔底德","荷马","普鲁塔克","希罗多德"],"a":3,"w":"希罗多德《历史》中提出，强调尼罗河泛滥对埃及的决定作用。"},{"q":"古埃及于哪一年并入罗马版图","o":["前525年","前30年","前332年","476年"],"a":1,"w":"前30年克娄巴特拉七世死后，埃及成为罗马行省。"}],"rel":[{"t":"尼罗河","n":"文明的母亲河"},{"t":"金字塔","n":"法老陵墓"},{"t":"罗塞塔石碑","n":"释读象形文字的钥匙"},{"t":"象形文字","n":"古埃及文字"},{"t":"四大文明古国","n":"位列其中"}],"more":"1799年罗塞塔石碑发现，上刻圣书体象形文字、世俗体文字和古希腊文三种文字，1822年法国学者商博良据此释读象形文字。\n木乃伊与《亡灵书》体现古埃及人的来世观。"},{"id":"b10-003","t":"印度河文明","cid":"10a","p":1,"kind":"概念","alias":["印度河流域文明"],"one":"南亚印度河流域青铜城市文明，遗址在今巴基斯坦，文字未释读。","ans":"印度河文明是**南亚印度河流域的青铜时代城市文明**，约前2500年至前1750年繁盛，因最先发掘的**哈拉帕**遗址又称**哈拉帕文化**。主要遗址哈拉帕和**摩亨佐-达罗今属巴基斯坦**。它以**规划整齐的城市、完善的排水系统和大浴池**著称，使用**至今未能释读的印章文字**，与两河流域有贸易往来。20世纪20年代经考古发掘重见天日；约前18世纪后衰落，原因尚无定论，此后**雅利安人**进入南亚，开启吠陀时代。","pts":["印度河流域青铜城市文明，哈拉帕文化","城市规划、排水系统、印章文字未释读","20世纪20年代发掘；衰落后雅利安人入南亚"],"mem":"记两座城：哈拉帕（命名）和摩亨佐-达罗（意为“死亡之丘”）。画面：街道成棋盘格，家家有下水道，城中央有大浴池，印章上的字却没人读得懂。顺序记“先印度河，后恒河”：印度河文明→雅利安人进入→吠陀时代→恒河流域。","mix":"主体在今巴基斯坦，不在今印度；它的文字未释读，楔形文字和象形文字则已释读；雅利安人带来的吠陀文化与它是前后相继的两个阶段。","mcq":[{"q":"印度河文明的主要遗址哈拉帕和摩亨佐-达罗，今天位于","o":["印度","孟加拉国","尼泊尔","巴基斯坦"],"a":3,"w":"两处遗址都在今巴基斯坦境内。"},{"q":"下列关于印度河文明的说法，正确的是","o":["文字至今未被释读","使用楔形文字","由雅利安人创造","文明中心在恒河流域"],"a":0,"w":"印度河文明的印章文字至今未能释读；雅利安人是其衰落之后进入南亚的。"}],"rel":[{"t":"哈拉帕文化","n":"同一文明的另称"},{"t":"雅利安人","n":"衰落后进入南亚"},{"t":"种姓制度","n":"吠陀时代以后形成"},{"t":"四大文明古国","n":"古印度位列其中"}],"more":"约前18世纪后衰落，原因有气候变迁、河流改道、外族入侵等说，尚无定论。","exam":[]},{"id":"b10-004","t":"丝绸之路","cid":"10c","p":1,"kind":"概念","exam":["2011选择","2026选择"],"alias":["丝路","陆上丝绸之路"],"one":"古代连接中国与亚欧非的陆上商路，张骞凿空，长安为起点。","ans":"丝绸之路是**古代连接中国与亚欧非各地的陆上交通贸易路线**，因大量运输中国丝绸而得名。**西汉张骞两次出使西域（前138年、前119年）“凿空”**，正式开通以**长安为起点，经河西走廊、西域，越帕米尔高原到达中亚、西亚并延伸至地中海**的道路。中国的**丝绸、瓷器、冶铁技术西传，葡萄、苜蓿、汗血马和佛教东来**。**1877年德国地理学家李希霍芬**首次称其为“丝绸之路”。**2014年**中、哈、吉三国联合申报的“丝绸之路：长安-天山廊道的路网”列入《世界遗产名录》。","pts":["古代亚欧非陆上交通贸易路线","张骞凿空，长安、河西走廊、西域、中亚西亚","李希霍芬命名；2014年跨国申遗"],"mem":"一条线加四个人名：张骞（开通）、李希霍芬（命名，1877）、马可·波罗（元代东来）、玄奘法显（西行取经）。路线口诀（自编）：“长安出，河西走，越葱岭，到西亚”。物产对流：西传丝绸瓷器，东来葡萄苜蓿汗血马。申遗数字：2014年，三国（中、哈、吉）。","mix":"陆上丝路出长安，海上丝路从泉州、广州等港口经马六甲海峡通印度洋；2014年申遗的三国是中国、哈萨克斯坦、吉尔吉斯斯坦，不含乌兹别克斯坦；2021年泉州项目属于海上贸易遗产。","mcq":[{"q":"首次把古代东西方交通线命名为“丝绸之路”的是","o":["张骞","马可·波罗","斯文·赫定","李希霍芬"],"a":3,"w":"1877年德国地理学家李希霍芬首次使用这一名称。"},{"q":"2014年列入《世界遗产名录》的“丝绸之路：长安-天山廊道的路网”，申报国不包括","o":["中国","哈萨克斯坦","乌兹别克斯坦","吉尔吉斯斯坦"],"a":2,"w":"该项目由中国、哈萨克斯坦、吉尔吉斯斯坦联合申报。"}],"rel":[{"t":"张骞通西域","n":"丝路开通者"},{"t":"河西走廊","n":"丝路咽喉"},{"t":"海上丝绸之路","n":"陆路之外的海路"},{"t":"丝绸之路：长安-天山廊道路网","n":"2014年申遗项目"},{"t":"一带一路","n":"当代倡议"}],"more":"1877年李希霍芬在《中国》一书中提出“丝绸之路”一词。\n2021年“泉州：宋元中国的世界海洋商贸中心”列入世界遗产。"},{"id":"b10-005","t":"汗血宝马","cid":"10c","p":1,"kind":"常识","exam":["2026选择"],"alias":["天马","阿哈尔捷金马"],"one":"汉代西域大宛名马，今称阿哈尔捷金马，主产地土库曼斯坦。","ans":"汗血宝马是**古代西域大宛出产的良马**，传说奔跑时肩部渗出带血的汗珠，故名，汉武帝称之为**“天马”**。为得此马，武帝在太初年间派**李广利远征大宛**，最终取得良马数十匹、中等以下马三千余匹。现代认为它是**阿哈尔捷金马**，主要产地在**土库曼斯坦**，该国视为国宝，并绘入国徽。汗血宝马耐力强、速度快，随丝绸之路传入中原后，为汉朝引进了良种马，也成为中亚与中国交往的象征。","pts":["古代出自西域大宛，汉武帝称天马","李广利远征大宛得良马","今称阿哈尔捷金马，产于土库曼斯坦"],"mem":"三个“大”串起来：大宛出产，大将李广利远征，大名“天马”。古今对照一句话（自编）：“大宛是汉代出处，土库曼是今日产地”。画面：国徽正中一匹昂首的马。","mix":"古代出处是大宛（今中亚费尔干纳盆地一带），现代主要产地是土库曼斯坦，选择题常问其一；不要与乌孙马、蒙古马、伊犁马混淆。","mcq":[{"q":"汉武帝派李广利远征，目的是夺取哪个西域古国的汗血宝马","o":["乌孙","安息","大宛","大月氏"],"a":2,"w":"《史记·大宛列传》记载，武帝为取大宛良马而伐大宛。"},{"q":"现代汗血宝马（阿哈尔捷金马）的主要原产国是","o":["哈萨克斯坦","乌兹别克斯坦","伊朗","土库曼斯坦"],"a":3,"w":"土库曼斯坦把该马视为国宝，并绘入国徽。"}],"rel":[{"t":"大宛","n":"汉代出处"},{"t":"西域","n":"产地所在大区"},{"t":"丝绸之路","n":"传入中原的通道"},{"t":"汉武帝","n":"求马的皇帝"}],"more":"《史记·大宛列传》记李广利伐大宛，得善马数十匹，中等以下马三千余匹。"},{"id":"b10-006","t":"河西走廊","cid":"10c","p":1,"kind":"地理","exam":["2010选择"],"alias":["河西四郡"],"one":"甘肃祁连山以北的狭长通道，汉设武威、张掖、酒泉、敦煌四郡。","ans":"河西走廊位于**甘肃省西北部、祁连山以北、黄河以西**，因在黄河以西得名，是一条狭长的东西向通道，东起乌鞘岭，西至甘肃与新疆交界处。**汉武帝**在霍去病击败匈奴后，在此设置**武威、张掖、酒泉、敦煌“河西四郡”**，并修筑长城，设立玉门关与阳关。它是**丝绸之路的咽喉要道**，连接中原与西域，张骞出使西域也取道于此，沿线留有敦煌莫高窟、嘉峪关等遗产。","pts":["甘肃祁连山以北，黄河以西","汉武帝设武威、张掖、酒泉、敦煌四郡","丝绸之路咽喉要道"],"mem":"四郡按东到西排：武威、张掖、酒泉、敦煌。地名各有来历：武威取“武功军威”，张掖取“张国臂掖”，酒泉传说是霍去病倒酒入泉与将士同饮，敦煌取“盛大辉煌”。首字串联“武张酒敦”。","mix":"河西走廊在甘肃，不在新疆；“河西”指黄河以西。河西四郡不含金城、陇西等郡。","mcq":[{"q":"汉武帝设置的“河西四郡”不包括","o":["武威","张掖","金城","敦煌"],"a":2,"w":"河西四郡为武威、张掖、酒泉、敦煌。"},{"q":"河西走廊位于哪座山脉以北","o":["天山","祁连山","昆仑山","秦岭"],"a":1,"w":"走廊南靠祁连山，北邻合黎山、龙首山。"}],"rel":[{"t":"丝绸之路","n":"必经通道"},{"t":"汉武帝","n":"设四郡"},{"t":"敦煌壁画","n":"走廊西端的艺术"},{"t":"西域与西域都护府","n":"走廊以西的区域"}],"more":"河西走廊东起乌鞘岭，西至玉门关一带，长约一千公里。"},{"id":"b10-007","t":"马可·波罗","cid":"10c","p":1,"kind":"人物","exam":["2010选择"],"alias":["马可波罗","《马可·波罗游记》","《东方见闻录》"],"one":"意大利威尼斯商人，元代来华，口述《马可·波罗游记》。","ans":"马可·波罗（1254—1324）是**意大利威尼斯商人、旅行家**。他随父亲和叔父于1271年东行，经中亚、河西走廊，约1275年抵达元朝上都，**受到元世祖忽必烈接见**，在中国留居十余年，约1292年自泉州出海护送公主赴波斯，**1295年回到威尼斯**。后在热那亚狱中**口述，由比萨作家鲁斯蒂谦笔录，写成《马可·波罗游记》**（又名《东方见闻录》）。书中描绘了元代中国的繁华，**激发了欧洲人对东方的向往**，对新航路的开辟有一定推动。","pts":["意大利威尼斯商人，元代来华","受忽必烈接见，约1295年回国","口述《马可·波罗游记》，激发欧洲向往东方"],"mem":"时间线三个数字：1271出发，1275见忽必烈，1295回威尼斯。一本书是口述的，鲁斯蒂谦代笔，地点在热那亚监狱。影响链：游记→欧洲向往东方→哥伦布、达·伽马寻找通往东方的海路。","mix":"马可·波罗是意大利人，元代来华；法显、玄奘是中国人西行；伊本·白图泰是摩洛哥人，14世纪中叶也到过元代中国。","mcq":[{"q":"《马可·波罗游记》中，马可·波罗来华时在位的中国皇帝是","o":["元太祖成吉思汗","元世祖忽必烈","元太宗窝阔台","宋理宗"],"a":1,"w":"马可·波罗受到元世祖忽必烈的接见。"},{"q":"马可·波罗来华的朝代是","o":["唐","宋","明","元"],"a":3,"w":"他13世纪后期来到元朝。"}],"rel":[{"t":"成吉思汗与忽必烈","n":"元朝统治者"},{"t":"丝绸之路","n":"东来的通道"},{"t":"郑和下西洋","n":"中国的海上远航"},{"t":"地理大发现","n":"游记的间接影响"}],"more":"哥伦布的藏书中有《马可·波罗游记》，书页上留有批注。"},{"id":"b10-008","t":"波斯帝国","cid":"10b","p":1,"kind":"概念","exam":["2013名解","2015名解"],"alias":["阿契美尼德王朝","波斯"],"one":"伊朗高原上的阿契美尼德王朝，横跨亚非欧，因希波战争著名，亡于亚历山大。","ans":"波斯帝国通常指**伊朗高原上的阿契美尼德王朝（前550至前330年）**。**居鲁士二世建立帝国**，征服米底、吕底亚，**前539年灭新巴比伦**；**大流士一世**设行省、统一货币和税制、修建“御道”，帝国鼎盛时**横跨亚非欧三洲**。前5世纪发动**希波战争**，败于希腊城邦；**前330年为亚历山大所灭**。国教为**琐罗亚斯德教（拜火教）**，都城遗址波斯波利斯列入世界遗产。**1935年波斯改称伊朗**。","pts":["阿契美尼德王朝，居鲁士建国，灭新巴比伦","大流士改革，横跨亚非欧","希波战争失败，前330年亡于亚历山大"],"mem":"三个人物三件事：居鲁士建国（灭新巴比伦，允许犹太人返回故土），大流士改革（行省、御道、统一货币），亚历山大灭国（前330年）。画面：一条“御道”从苏萨通到小亚细亚的萨迪斯，全长约2700千米，驿使接力送信。","mix":"阿契美尼德之后伊朗高原还有安息（帕提亚）和萨珊波斯，三个王朝常被混淆；希波战争的对手是波斯，灭亡波斯的是马其顿的亚历山大。","mcq":[{"q":"前539年灭亡新巴比伦的是","o":["亚述","波斯","马其顿","埃及"],"a":1,"w":"居鲁士二世灭新巴比伦，两河流域并入波斯。"},{"q":"波斯帝国的国教是","o":["婆罗门教","佛教","犹太教","琐罗亚斯德教"],"a":3,"w":"琐罗亚斯德教又称拜火教，是阿契美尼德王朝的主要信仰。"}],"rel":[{"t":"居鲁士与大流士","n":"建国者与改革者"},{"t":"希波战争","n":"与希腊城邦的战争"},{"t":"琐罗亚斯德教","n":"波斯国教"},{"t":"伊朗高原","n":"发源地"},{"t":"亚历山大大帝","n":"前330年灭波斯"}],"more":"大流士一世修建的“御道”从苏萨通到萨迪斯，长约2700千米。\n1935年国际上正式使用国名“伊朗”。"},{"id":"b10-009","t":"欧洲中世纪","cid":"10d","p":1,"kind":"概念","exam":["2012选择","2017名解"],"alias":["中世纪","西欧中世纪"],"one":"476年西罗马灭亡至14至15世纪（或1453年）的约一千年。","ans":"欧洲中世纪一般指**从476年西罗马帝国灭亡到14—15世纪文艺复兴（或1453年东罗马帝国灭亡）**之间约一千年的时期，“中世纪”一词由**文艺复兴时期的人文主义者**提出，意为古典时代与古典复兴之间的“中间时代”。此期西欧形成**封君封臣制度和庄园经济**，**基督教会主导精神生活**，经院哲学盛行，常被称为**“黑暗时代”**。但中后期**城市兴起、大学出现**（博洛尼亚、巴黎、牛津），**议会制度萌芽**（1215年英国《大宪章》），为近代欧洲奠定基础。","pts":["476年至14—15世纪（或1453年）","封建制度、庄园、教会与经院哲学","“黑暗时代”之说与城市、大学、议会兴起"],"mem":"两端各一个年份：开端476（西罗马亡），结尾1453（君士坦丁堡陷落）。三大支柱记“地、教、剑”：土地（庄园）、教会（经院哲学）、剑（骑士）。末期三个冲击：十字军、黑死病、百年战争。","mix":"中世纪的结束有多种说法（1453年、1492年、文艺复兴等）；“黑暗时代”是人文主义者的评价，现代史学更重视其城市、大学与法律的发展。","mcq":[{"q":"通常以哪一事件作为欧洲中世纪的开端","o":["君士坦丁堡陷落","查理曼加冕","西罗马帝国灭亡","黑死病流行"],"a":2,"w":"476年西罗马帝国灭亡，是中世纪的通行起点。"},{"q":"“中世纪”这一概念最初由谁提出","o":["启蒙思想家","教会神学家","古罗马史学家","文艺复兴时期的人文主义者"],"a":3,"w":"人文主义者把古典时代与自己的时代之间称为“中间时代”。"}],"rel":[{"t":"476年西罗马帝国灭亡","n":"开端"},{"t":"1453年","n":"常见终点"},{"t":"封建采邑制","n":"政治制度"},{"t":"中世纪大学","n":"新兴因素"},{"t":"文艺复兴","n":"随后的时代"}],"more":"“黑暗时代”之说源自彼特拉克等人文主义者对中世纪的评价。"},{"id":"b10-010","t":"封建采邑制","cid":"10d","p":1,"kind":"制度","exam":["2021名解"],"alias":["采邑制","封君封臣制"],"one":"西欧中世纪以土地分封为基础的封君封臣等级制度，起于查理·马特改革。","ans":"封建采邑制是**西欧中世纪以土地占有为基础的封建等级制度**，起源于**8世纪前期法兰克王国宫相查理·马特的采邑改革**：国王把土地连同耕种的农民作为**“采邑”分封给贵族和骑士，受封者必须服兵役（主要是骑兵役）并效忠**；采邑起初仅限终身，后逐渐变为**世袭**。由此形成国王、大封建主、中小封建主、骑士的层层分封体系，以及封君与封臣的权利义务关系，即“**我的附庸的附庸不是我的附庸**”。它既巩固了封建统治，也造成**王权衰弱、地方割据**。","pts":["西欧中世纪以土地为基础的等级制","查理·马特改革，服兵役换采邑，由终身到世袭","层层分封，王权衰弱、地方割据"],"mem":"一个公式：土地换服役，效忠换保护。层级像金字塔：国王、公侯、伯爵、骑士。名言只背一句：附庸的附庸不是我的附庸，说明国王只管直接封臣，所以王权弱。对照：西周分封制靠血缘宗法，欧洲采邑靠契约。","mix":"采邑制是领主之间的政治军事关系，庄园制度是领主与农奴的经济关系；与中国西周分封制对照，前者以契约为纽带，后者以血缘宗法为纽带。","mcq":[{"q":"西欧封建采邑制的改革起源于哪位法兰克宫相","o":["丕平三世","克洛维","查理·马特","查理曼"],"a":2,"w":"8世纪前期查理·马特推行采邑改革，以服兵役为条件分封土地。"},{"q":"“我的附庸的附庸不是我的附庸”反映了西欧封建制度的什么特点","o":["王权强大","官僚制发达","中央集权","层层分封，王权衰弱"],"a":3,"w":"封建关系只存在于直接的封君封臣之间，国王难以直接控制中小封建主。"}],"rel":[{"t":"分封制","n":"中国西周的对照制度"},{"t":"庄园制度","n":"配套的经济形态"},{"t":"骑士制度","n":"受封的军事阶层"},{"t":"查理曼帝国","n":"采邑制盛行的时代"}],"more":"采邑改革起因：732年图尔战役前后，法兰克需要组建骑兵对抗阿拉伯人。"},{"id":"b10-011","t":"维京人","cid":"10d","p":1,"kind":"概念","exam":["2026名解"],"alias":["诺斯人","北欧海盗"],"one":"8至11世纪来自斯堪的纳维亚的北欧人，龙头长船劫掠与殖民。","ans":"维京人指**8世纪末至11世纪中叶（约793—1066年）来自斯堪的纳维亚的北欧人**，又称诺曼人。他们**驾驶龙头长船劫掠、经商并移民**，**793年袭击英格兰林迪斯法恩修道院**常被视为维京时代的开端。丹麦人一度控制英格兰东北部的“丹麦法区”，**911年在法国北部建立诺曼底公国**；瑞典人沿东欧河流南下，参与建立**基辅罗斯**；挪威人到达冰岛、格陵兰，**约1000年抵达北美**。维京人推动了北欧国家形成，留下北欧神话与萨迦文学。","pts":["8—11世纪斯堪的纳维亚北欧人","龙头长船劫掠、贸易、殖民，793年开端","诺曼底、基辅罗斯、抵达北美；神话与萨迦"],"mem":"路线记“西、南、东”：西到冰岛、格陵兰、北美（约1000年）；南到法国北部诺曼底（911年）；东沿河流到基辅罗斯。画面：龙头长船冲上海滩。星期词：Wednesday是沃登（奥丁）日，Thursday是托尔日。","mix":"维京人、诺曼人常混用：诺曼人特指定居诺曼底的维京后裔，1066年诺曼底公爵威廉征服英格兰；维京时代的结束常以1066年为标志。","mcq":[{"q":"911年维京人在法国北部建立的公国是","o":["勃艮第","阿基坦","诺曼底","布列塔尼"],"a":2,"w":"诺曼底公国由维京首领罗洛接受法王册封而成。"},{"q":"维京人约公元1000年到达的地区是","o":["北美","南美","澳大利亚","非洲南部"],"a":0,"w":"挪威人经冰岛、格陵兰抵达北美东北部。"}],"rel":[{"t":"诺曼征服","n":"诺曼人后续行动"},{"t":"基辅罗斯","n":"瑞典维京人参与建立"},{"t":"查理曼帝国","n":"帝国衰落时期遭其侵扰"},{"t":"中世纪欧洲英雄史诗","n":"北欧萨迦的文学对照"}],"more":"793年林迪斯法恩修道院遇袭，常被视为维京时代的开端；1066年哈罗德·哈德拉达在斯坦福桥战败，常被视为维京时代的终点。"},{"id":"b10-012","t":"十字军东征","cid":"10d","p":1,"kind":"事件","alias":["十字军"],"one":"1096至1291年西欧教会与封建主以收复圣地为名的远征，约八次。","ans":"十字军东征是**1096年至1291年，西欧基督教会和封建主以“从异教徒手中收复圣地耶路撒冷”为名，对地中海东岸伊斯兰国家发动的一系列宗教性军事远征**，先后约八次，参加者衣服上缝有十字标志。**1095年教皇乌尔班二世在克莱蒙会议上发出号召**；**第一次东征攻占耶路撒冷**，**第四次东征攻陷了同为基督教国家的拜占庭首都君士坦丁堡**；**1291年最后据点阿卡陷落**，东征失败。东征带来灾难，也客观上**促进了东西方贸易与文化交流**，推动了意大利城市兴起。","pts":["1096—1291，教会与封建主以收复圣地为名","乌尔班二世号召，一占耶路撒冷，四攻君士坦丁堡","灾难与东西方交流的双重影响"],"mem":"数字：1095号召，1096出发，1291结束，约八次。两个关键次序：第一次成功（占耶路撒冷，1099年），第四次跑偏（打下君士坦丁堡，1204年）。逻辑线：宗教口号加上土地、财富的欲望，所以商路开通、意大利城市受益。","mix":"十字军与古罗马无直接关系，发生在西罗马灭亡数百年之后；第四次东征的对象是拜占庭，而不是穆斯林；1187年萨拉丁收复耶路撒冷，引发第三次东征。","mcq":[{"q":"1095年在克莱蒙会议上号召十字军东征的教皇是","o":["格列高利七世","英诺森三世","乌尔班二世","利奥十世"],"a":2,"w":"乌尔班二世于1095年发出号召。"},{"q":"十字军第四次东征攻陷的城市是","o":["君士坦丁堡","耶路撒冷","大马士革","开罗"],"a":0,"w":"1204年十字军攻陷同为基督教国家的拜占庭首都。"}],"rel":[{"t":"耶路撒冷","n":"东征的目标"},{"t":"君士坦丁堡","n":"第四次东征攻陷"},{"t":"拜占庭帝国","n":"受害的基督教国家"},{"t":"阿拉伯帝国与百年翻译运动","n":"东西方学术交流"},{"t":"欧洲中世纪","n":"所属时代"}],"more":"1099年第一次东征攻占耶路撒冷；1187年萨拉丁收复；1204年第四次东征攻陷君士坦丁堡；1291年阿卡陷落。","exam":[]},{"id":"b10-013","t":"文艺复兴","cid":"10e","p":1,"kind":"事件","alias":["文艺复兴运动"],"one":"14至16世纪起于意大利的人文主义思想文化运动。","ans":"文艺复兴是**14至16世纪发生在欧洲的思想文化运动**，**发源于意大利佛罗伦萨，后扩展到西欧各国**。它以**复兴古希腊罗马古典文化为旗号**，实质是**新兴资产阶级的思想解放运动**，核心思想是**人文主义**：以人为中心，反对以神为中心，肯定人的价值和尊严。文学有**“文坛三杰”但丁、彼特拉克、薄伽丘**，以及莎士比亚、塞万提斯；美术有**“美术三杰”达·芬奇、米开朗琪罗、拉斐尔**；科学上**哥白尼提出日心说**。它**冲击了教会的精神统治，为宗教改革和启蒙运动开辟了道路**。","pts":["14—16世纪，起于意大利佛罗伦萨","复兴古典为名，人文主义为核心","文坛三杰、美术三杰、日心说"],"mem":"“三三一”记忆：文坛三杰（但丁、彼特拉克、薄伽丘）、美术三杰（达·芬奇、米开朗琪罗、拉斐尔）、一个核心（人文主义）。画面：佛罗伦萨的美第奇家族出钱，画家与诗人把古希腊罗马的人像重新请回画布和书页。","mix":"选择题常问“哪个不是文艺复兴三杰”：美术三杰是达·芬奇、米开朗琪罗、拉斐尔，不含提香、波提切利；文坛三杰是但丁、彼特拉克、薄伽丘，莎士比亚、塞万提斯属于文艺复兴后期。","mcq":[{"q":"下列人物中，不属于文艺复兴美术三杰的是","o":["达·芬奇","米开朗琪罗","拉斐尔","梵高"],"a":3,"w":"美术三杰为达·芬奇、米开朗琪罗、拉斐尔。"},{"q":"文艺复兴的核心思想是","o":["人文主义","理性主义","民族主义","经验论"],"a":0,"w":"人文主义以人为中心，反对神权。"}],"rel":[{"t":"人文主义","n":"核心思想"},{"t":"文坛三杰","n":"文学代表"},{"t":"美术三杰","n":"美术代表"},{"t":"宗教改革","n":"后续运动"},{"t":"《神曲》","n":"文艺复兴先声"}],"more":"美术三杰代表作：达·芬奇《蒙娜丽莎》《最后的晚餐》；米开朗琪罗《大卫》、西斯廷礼拜堂天顶画；拉斐尔《西斯廷圣母》《雅典学院》。","exam":[]},{"id":"b10-014","t":"楔形文字","cid":"10a","p":1,"kind":"常识","alias":["泥板文字"],"one":"苏美尔人约前3200年创造，用芦苇秆压刻在泥板上，笔画形如楔子。","ans":"楔形文字是**古代两河流域最早的文字**，由**苏美尔人约前3200年创造**。书写时用**削尖的芦苇秆或木棒在湿泥板上压刻**，笔画一端粗一端细，形如木楔，故名。它由图画符号演变而来，后被**阿卡德、巴比伦、亚述、赫梯、波斯**等多个民族借用，书写不同的语言，沿用约三千年。《汉谟拉比法典》和史诗《吉尔伽美什》都用它写成。公元1世纪前后逐渐消亡，19世纪经格罗特芬德、罗林森等学者释读，成为研究西亚古史的第一手材料。","pts":["苏美尔人约前3200年创造","芦苇秆压刻泥板，笔画如楔","被多民族借用，《汉谟拉比法典》用它写成"],"mem":"“楔”就是木楔，钉子头：芦苇秆斜压进泥里，留下一端宽的三角痕。三地书写材料一句话区分：两河压泥板，埃及写纸莎草，中国刻龟甲兽骨。","mix":"与古埃及象形文字（圣书体，纸莎草纸）相区分；释读象形文字靠罗塞塔石碑，释读楔形文字靠贝希斯敦铭文等多语对照材料。","mcq":[{"q":"楔形文字的创造者是","o":["苏美尔人","埃及人","腓尼基人","赫梯人"],"a":0,"w":"苏美尔人约前3200年创造，后被西亚多个民族借用。"},{"q":"古代两河流域楔形文字最常见的书写载体是","o":["纸莎草纸","羊皮纸","龟甲","泥板"],"a":3,"w":"用芦苇秆在湿泥板上压刻，晒干或烧制保存。"}],"rel":[{"t":"两河流域","n":"楔形文字的诞生地"},{"t":"《汉谟拉比法典》","n":"用楔形文字写成"},{"t":"象形文字","n":"埃及的对应文字"},{"t":"腓尼基字母","n":"字母文字的另一源头"}],"more":"最早的楔形文字泥板出土于苏美尔城市乌鲁克。","exam":[]},{"id":"b10-015","t":"《汉谟拉比法典》","cid":"10a","p":1,"kind":"作品","alias":["汉谟拉比法典"],"one":"古巴比伦汉谟拉比颁布，刻于石柱，现存最早较完整的成文法典。","ans":"《汉谟拉比法典》是**古巴比伦国王汉谟拉比（约前18世纪）颁布的法典**，刻在**黑色石柱**上，共282条，涉及诉讼、财产、债务、婚姻和奴隶等。其量刑原则之一是**“以眼还眼，以牙还牙”的同态复仇**，同时按自由民、平民和奴隶划分等级，同罪不同罚。它是**现存最早较完整的成文法典**，序言宣称王权神授。石柱1901年在**伊朗苏萨**出土，现藏**巴黎卢浮宫**。法典反映了两河流域奴隶制社会的面貌，是研究古代西亚的重要史料。","pts":["古巴比伦汉谟拉比颁布，刻于石柱","现存最早较完整的成文法典","以眼还眼，等级分明；藏卢浮宫"],"mem":"三个固定搭配：最早较完整的成文法典；“以眼还眼”；藏在卢浮宫。画面：国王站在太阳神沙马什面前领受权杖，石柱立在城里供人阅读，人人知道犯法怎么罚。","mix":"强调“较完整”，更早的《乌尔纳姆法典》残缺较多；罗马《十二铜表法》晚它一千多年，中国法典常追溯到李悝《法经》。","mcq":[{"q":"现存最早较完整的成文法典是","o":["《十二铜表法》","《汉谟拉比法典》","《法经》","《拿破仑法典》"],"a":1,"w":"《汉谟拉比法典》约成于前18世纪，早于《十二铜表法》（前450年）。"},{"q":"《汉谟拉比法典》石柱现藏于","o":["大英博物馆","卢浮宫","埃及博物馆","梵蒂冈博物馆"],"a":1,"w":"石柱1901年在苏萨出土，现藏巴黎卢浮宫。"}],"rel":[{"t":"两河流域","n":"诞生地"},{"t":"楔形文字","n":"法典所用文字"},{"t":"罗马法与《十二铜表法》","n":"后起的成文法"},{"t":"《法经》","n":"中国早期成文法"},{"t":"古巴比伦王国","n":"颁布者的国家"}],"more":"石柱上部浮雕为汉谟拉比从太阳神沙马什手中接受权杖。","exam":[]},{"id":"b10-016","t":"金字塔","cid":"10a","p":1,"kind":"常识","exam":["2016名解"],"alias":["胡夫金字塔","吉萨金字塔"],"one":"古埃及法老陵墓，吉萨胡夫金字塔最大，七大奇迹中唯一现存。","ans":"金字塔是**古埃及法老的陵墓**，因外形似汉字“金”而得名，主要建于**古王国时期**。最早的是第三王朝左塞尔的**阶梯金字塔**，由伊姆霍特普设计；**吉萨的胡夫金字塔最大**，原高约146米，用约230万块石料垒成。吉萨三大金字塔分属**胡夫、哈夫拉、孟卡拉**三代法老。金字塔反映了**法老崇拜与来世观念**，体现了古埃及的数学、天文与测量水平，位列**古代世界七大奇迹之首，也是其中唯一留存至今者**。","pts":["古埃及法老陵墓，古王国时期修建","吉萨胡夫金字塔最大","七大奇迹之首，唯一现存"],"mem":"吉萨三塔按祖、子、孙顺序：胡夫、哈夫拉、孟卡拉，由大到小（自编：“胡大哈中孟卡小”）。七大奇迹里只剩它：巴比伦空中花园、亚历山大灯塔等都已不存。","mix":"金字塔属古埃及古王国；狮身人面像守在哈夫拉金字塔旁；玛雅、阿兹特克也有阶梯形金字塔，属于美洲文明。","mcq":[{"q":"吉萨金字塔群中规模最大的是","o":["孟卡拉金字塔","哈夫拉金字塔","左塞尔金字塔","胡夫金字塔"],"a":3,"w":"胡夫金字塔原高约146米，为吉萨三塔之最。"},{"q":"古代世界七大奇迹中，唯一留存至今的是","o":["亚历山大灯塔","金字塔","巴比伦空中花园","罗德岛巨像"],"a":1,"w":"其余六处均已毁坏或消失。"}],"rel":[{"t":"狮身人面像","n":"同在吉萨"},{"t":"古埃及文明","n":"所属文明"},{"t":"法老","n":"陵墓主人"},{"t":"玛雅文明","n":"美洲的阶梯金字塔"}],"more":"最早的金字塔是第三王朝法老左塞尔的阶梯金字塔，位于萨卡拉。"},{"id":"b10-017","t":"狮身人面像","cid":"10a","p":1,"kind":"常识","exam":["2016名解"],"alias":["斯芬克斯像","人面狮身像"],"one":"吉萨金字塔群旁的巨型石像，一般认为建于哈夫拉法老时期。","ans":"狮身人面像是**古埃及的巨型石雕**，位于**吉萨金字塔群旁**，**狮身人面**，长约73米，高约20米，由整块山岩雕成。一般认为建于**古王国第四王朝哈夫拉法老时期**，面部被认为是法老的形象，象征**王权与太阳神的守护**。它面向东方，与哈夫拉金字塔相邻，是古埃及文明的标志性景观。希腊神话中的**斯芬克斯**是向路人出谜的怪物，形象相似而性质不同，谜被俄狄浦斯解开。","pts":["吉萨金字塔群旁，狮身人面","一般认为建于哈夫拉法老时期","象征王权；区别于希腊神话斯芬克斯"],"mem":"哈夫拉同时守着金字塔和像：塔在后，像在前，像脸就是法老的脸。埃及这只是守护神，希腊那只斯芬克斯是出谜怪物，谜面“早晨四条腿，中午两条腿，晚上三条腿”，谜底是人。","mix":"埃及的像象征王权守护，希腊神话的斯芬克斯是出谜害人的怪物，二者译名相同，性质不同。","mcq":[{"q":"一般认为狮身人面像建于哪位法老时期","o":["胡夫","孟卡拉","图坦卡蒙","哈夫拉"],"a":3,"w":"通行说法认为像的面部为哈夫拉。"},{"q":"狮身人面像位于","o":["吉萨金字塔群旁","卢克索神庙","亚历山大港","阿斯旺"],"a":0,"w":"位于开罗附近的吉萨高地。"}],"rel":[{"t":"金字塔","n":"同处吉萨"},{"t":"古埃及文明","n":"所属文明"},{"t":"《俄狄浦斯王》","n":"斯芬克斯之谜的出处"}],"more":"斯芬克斯之谜：什么动物早晨四条腿、中午两条腿、晚上三条腿？谜底是人。"},{"id":"b10-018","t":"尼罗河","cid":"10a","p":1,"kind":"地理","exam":["2017名解"],"one":"东北非大河，由南向北注入地中海，定期泛滥孕育古埃及。","ans":"尼罗河位于**东北非**，**由南向北注入地中海**，全长约6670千米，是**世界最长的河流之一**，有青尼罗河和白尼罗河两大源流。它每年7至10月**定期泛滥**，留下肥沃淤泥，使两岸成为**农业文明的摇篮**，希罗多德因此说“**埃及是尼罗河的赠礼**”。泛滥规律促使古埃及人观测天象，创制**太阳历**，土地重新丈量又推动了**几何学**的发展。古埃及的城市、金字塔和神庙都沿河分布，河流同时是交通干线。","pts":["东北非，由南向北注入地中海","定期泛滥带来淤泥，孕育农业文明","促进天文、历法和几何发展"],"mem":"“定期泛滥”串起三件事：淤泥带来农业，水位涨落带来历法，淹地后重新量地带来几何。尼罗河北流，所以上游在南（上埃及），下游在北（下埃及）。","mix":"尼罗河注入地中海；苏伊士运河连接的才是地中海与红海。尼罗河与亚马孙河常争世界最长，通行说法尼罗河最长。","mcq":[{"q":"“埃及是尼罗河的赠礼”强调尼罗河的哪一作用","o":["水力发电","连通红海","阻挡外敌","定期泛滥带来肥沃土壤"],"a":3,"w":"泛滥留下淤泥，使农业得以发展。"},{"q":"尼罗河最终注入","o":["红海","地中海","黑海","阿拉伯海"],"a":1,"w":"尼罗河由南向北，在埃及形成三角洲后注入地中海。"}],"rel":[{"t":"古埃及文明","n":"尼罗河的赠礼"},{"t":"世界河流之最","n":"长度之最"},{"t":"苏伊士运河","n":"埃及另一水道"},{"t":"两河流域","n":"同为大河文明"}],"more":"古埃及人把天狼星偕日升起的时间作为一年起点，与尼罗河涨水时间相合。"},{"id":"b10-019","t":"种姓制度","cid":"10a","p":2,"kind":"制度","exam":[],"alias":[],"one":"古印度雅利安人建立的等级制度（瓦尔纳）：婆罗门（祭司）、刹帝利（武士）、吠舍","ans":"古印度雅利安人建立的等级制度（瓦尔纳）：婆罗门（祭司）、刹帝利（武士）、吠舍（农工商）、首陀罗（被征服者），之外还有“不可接触者”","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-021","t":"地中海","cid":"10b","p":1,"kind":"地理","exam":["2017名解"],"one":"欧亚非三洲之间的陆间海，西接大西洋，古典文明的摇篮。","ans":"地中海是**位于欧、亚、非三洲之间的陆间海**，面积约250万平方千米，是**世界最大的陆间海**。西经**直布罗陀海峡**通大西洋，东北经**土耳其海峡**通黑海，东南经**苏伊士运河**通红海。沿岸孕育了**古埃及、腓尼基、古希腊、古罗马**等文明，是古代东西方贸易与文化交流的中心，罗马人称之为**“我们的海”**。地中海气候**夏季炎热干燥、冬季温和多雨**，适宜种植橄榄、葡萄和柑橘。","pts":["欧亚非三洲之间的陆间海","直布罗陀、土耳其海峡、苏伊士运河三通道","古典文明摇篮，罗马称“我们的海”"],"mem":"三个出口记“西直、东土、东南苏”：西面直布罗陀，东北土耳其海峡，东南苏伊士运河。气候口诀“夏干冬湿”，与东亚季风的“雨热同期”相反。","mix":"苏伊士运河（1869年）沟通地中海与红海，巴拿马运河（1914年）沟通太平洋与大西洋，选择题常把两者互换。","mcq":[{"q":"地中海通往大西洋的门户是","o":["马六甲海峡","博斯普鲁斯海峡","霍尔木兹海峡","直布罗陀海峡"],"a":3,"w":"直布罗陀海峡位于西班牙与摩洛哥之间。"},{"q":"地中海气候的特点是","o":["全年高温多雨","夏季炎热干燥，冬季温和多雨","雨热同期","冬季严寒干燥"],"a":1,"w":"地中海气候夏干冬湿。"}],"rel":[{"t":"直布罗陀海峡","n":"通大西洋的门户"},{"t":"苏伊士运河","n":"通红海"},{"t":"土耳其海峡（博斯普鲁斯与达达尼尔）","n":"通黑海"},{"t":"腓尼基字母","n":"地中海商人创造"},{"t":"七大洲四大洋","n":"世界海陆总览"}],"more":"罗马人称地中海为“我们的海”（Mare Nostrum）。"},{"id":"b10-022","t":"伊朗高原","cid":"10b","p":1,"kind":"地理","exam":["2017名解"],"one":"西亚高原，波斯帝国的发源地，丝绸之路必经之地。","ans":"伊朗高原是**西亚的高原**，海拔大多在1000米以上，范围包括**伊朗大部及阿富汗、巴基斯坦西部**，周围有扎格罗斯山脉、厄尔布尔士山脉等环绕，内部多沙漠与盐湖。它是**古代米底和波斯帝国的发源地**，此后安息（帕提亚）、萨珊波斯相继在此兴起。高原位于**欧亚交通要冲**，是**丝绸之路的必经之地**，东连中亚与中国，西通两河流域和地中海。琐罗亚斯德教和古代波斯文化都在此发展。","pts":["西亚高原，含伊朗大部及阿富汗等地","米底、波斯帝国、安息、萨珊的发源地","丝绸之路必经之地"],"mem":"“高原=波斯三代”：阿契美尼德波斯、安息、萨珊波斯，三个王朝都在这里。位置：伊朗高原夹在两河流域（西）与印度河流域（东）之间，丝路正好从中间穿过。","mix":"与青藏高原、帕米尔高原、安纳托利亚高原相区分；波斯帝国发源于高原西南部的法尔斯地区。","mcq":[{"q":"古代波斯帝国的发源地是","o":["伊朗高原","德干高原","安纳托利亚高原","青藏高原"],"a":0,"w":"米底与波斯帝国均兴起于伊朗高原。"},{"q":"下列政权中，兴起于伊朗高原的是","o":["迦太基","安息","埃及新王国","奥斯曼帝国"],"a":1,"w":"安息即帕提亚帝国，立国于伊朗高原。"}],"rel":[{"t":"波斯帝国","n":"高原上的帝国"},{"t":"安息","n":"高原上的帕提亚"},{"t":"丝绸之路","n":"途经高原"},{"t":"帕米尔高原（葱岭）","n":"丝路另一高原"}]},{"id":"b10-023","t":"拜占庭帝国","cid":"10d","p":1,"kind":"概念","alias":["东罗马帝国","拜占庭"],"one":"东罗马帝国（395至1453年），都君士坦丁堡，1453年亡于奥斯曼。","ans":"拜占庭帝国即**东罗马帝国（395—1453年）**，**395年罗马帝国分裂后由东部延续**，都城**君士坦丁堡**（原名拜占庭，今伊斯坦布尔）。**查士丁尼皇帝（527—565年在位）**主持编纂《罗马民法大全》，修建圣索菲亚大教堂。帝国信奉**东正教**，使用希腊语，保存了大量古希腊罗马典籍。1204年遭第四次十字军洗劫，**1453年被奥斯曼土耳其攻灭**，大批学者携典籍逃往意大利，**推动了文艺复兴**。","pts":["东罗马帝国，395—1453，都君士坦丁堡","查士丁尼编《罗马民法大全》，东正教","1453年亡于奥斯曼，学者西逃"],"mem":"两个年份：395分家，1453灭亡，前后一千零五十八年，比西罗马多活近千年。一个人：查士丁尼（法典+教堂）。一个因果：1453年灭亡→学者带着希腊典籍逃到意大利→文艺复兴。","mix":"拜占庭帝国与东罗马帝国是同一政权的两种称呼；西罗马476年亡，东罗马1453年亡；它信东正教，西欧信天主教（1054年东西教会大分裂）。","mcq":[{"q":"拜占庭帝国的都城是","o":["罗马","雅典","亚历山大里亚","君士坦丁堡"],"a":3,"w":"君士坦丁堡今为土耳其伊斯坦布尔。"},{"q":"主持编纂《罗马民法大全》的拜占庭皇帝是","o":["查士丁尼","君士坦丁","奥古斯都","狄奥多西"],"a":0,"w":"查士丁尼一世在位期间组织编纂。"}],"rel":[{"t":"君士坦丁堡","n":"都城"},{"t":"1453年","n":"灭亡之年"},{"t":"奥斯曼帝国","n":"灭亡它的政权"},{"t":"罗马法与《民法大全》","n":"查士丁尼编纂"},{"t":"十字军东征","n":"第四次东征攻陷其都城"}],"more":"拜占庭建筑代表为圣索菲亚大教堂，见“拜占庭建筑与圣索菲亚大教堂”。","exam":[]},{"id":"b10-025","t":"地理大发现","cid":"10e","p":1,"kind":"事件","alias":["新航路开辟","大航海时代"],"one":"15至16世纪欧洲开辟新航路，迪亚士、哥伦布、达·伽马、麦哲伦。","ans":"地理大发现是**15至16世纪欧洲航海家开辟新航路**的活动。**1488年迪亚士**到达非洲南端**好望角**，**1492年哥伦布**到达美洲，**1498年达·伽马**绕好望角抵达印度，**1519—1522年麦哲伦船队**完成首次环球航行。新航路由葡萄牙、西班牙王室支持，动因是寻找通往东方的商路和黄金。它**使世界逐渐连成一体**，引发商业革命，同时推动了**殖民扩张和资本原始积累**，美洲原住民因此遭受巨大灾难。","pts":["15—16世纪新航路：迪亚士、哥伦布、达·伽马、麦哲伦","1488、1492、1498、1519—1522年","世界连成一体，殖民扩张与资本积累"],"mem":"四位航海家四个年份，口诀（自编）：“八八好望角，九二到美洲，九八抵印度，一九环球走”。国别记：迪亚士、达·伽马是葡萄牙；哥伦布（意大利人）和麦哲伦（葡萄牙人）为西班牙效力。","mix":"哥伦布到达美洲却自以为到了印度，所以称当地人“印第安人”；首次环球航行由麦哲伦船队完成，麦哲伦本人死于菲律宾；达·伽马开辟的是通印度的航路。","mcq":[{"q":"1488年到达非洲好望角的航海家是","o":["达·伽马","哥伦布","麦哲伦","迪亚士"],"a":3,"w":"迪亚士1488年到达好望角。"},{"q":"1498年绕过好望角到达印度的是","o":["达·伽马","哥伦布","迪亚士","麦哲伦"],"a":0,"w":"达·伽马1498年抵达印度西南海岸的卡利卡特。"}],"rel":[{"t":"迪亚士","n":"到达好望角"},{"t":"哥伦布","n":"到达美洲"},{"t":"达·伽马","n":"抵达印度"},{"t":"麦哲伦环球航行","n":"首次环球"},{"t":"郑和下西洋","n":"东方的远航对照"}],"more":"郑和下西洋始于1405年，比哥伦布早近九十年。","exam":[]},{"id":"b10-026","t":"启蒙运动","cid":"10f","p":1,"kind":"流派","alias":["启蒙思想","启蒙思想家","百科全书派"],"one":"17至18世纪以法国为中心的思想解放运动，高举理性，批判专制与教会。","ans":"启蒙运动是**17—18世纪继文艺复兴之后的又一次思想解放运动**，以**法国为中心**，波及英、德、美等国。它高举**理性**旗帜，批判封建专制和教会权威，主张天赋人权、自由平等。代表人物有**伏尔泰**（宣扬自由和宗教宽容）、**孟德斯鸠**（《论法的精神》，三权分立）、**卢梭**（《社会契约论》，人民主权），以及主编**《百科全书》**的狄德罗，他们所在的群体被称为**百科全书派**，英国的洛克是其先驱。启蒙思想为**美国独立战争和法国大革命**提供了思想武器，主要理念写入了《独立宣言》和《人权宣言》。","pts":["17—18世纪，法国为中心，崇尚理性","伏尔泰、孟德斯鸠、卢梭、狄德罗","为美国独立、法国大革命提供思想武器"],"mem":"自编一句话“伏宽、孟分、卢约、狄编”：伏尔泰讲宽容，孟德斯鸠讲分权，卢梭讲契约，狄德罗编《百科全书》。逻辑线：理性批判专制，思想武器催生1776年美国和1789年法国两场革命。","mix":"文艺复兴是14—16世纪、意大利为中心、以人文主义反对神权；启蒙运动是17—18世纪、法国为中心、以理性批判专制。洛克是英国人，常列为先驱；卢梭出生于日内瓦。","mcq":[{"q":"提出三权分立学说的启蒙思想家是","o":["卢梭","伏尔泰","孟德斯鸠","狄德罗"],"a":2,"w":"孟德斯鸠在《论法的精神》中提出。"},{"q":"主编《百科全书》，被视为百科全书派核心人物的是","o":["狄德罗","伏尔泰","孟德斯鸠","洛克"],"a":0,"w":"狄德罗主编《百科全书》（1751—1772）。"}],"rel":[{"t":"文艺复兴","n":"上一次思想解放"},{"t":"孟德斯鸠","n":"三权分立"},{"t":"卢梭","n":"人民主权"},{"t":"百科全书","n":"启蒙运动的集体成果"},{"t":"五四新文化运动","n":"常被称为中国的启蒙运动"}],"more":"代表著作：孟德斯鸠《论法的精神》（1748）；卢梭《社会契约论》（1762）；狄德罗主编《百科全书》（1751—1772）。","exam":[]},{"id":"b10-027","t":"英国资产阶级革命","cid":"10f","p":2,"kind":"事件","exam":[],"alias":[],"one":"1640年至1688年英国资产阶级和新贵族推翻封建专制的革命。1649年国王","ans":"1640年至1688年英国资产阶级和新贵族推翻封建专制的革命。1649年国王查理一世被处死，成立共和国，奥利弗·克伦威尔掌权并于1653年任“护国公”实行独裁；1660年斯图亚特王朝复辟；1688年“光荣革命”，次年通过《权利法案》，确立君主立宪制。要点：1640—1688、克伦威尔护国公、光荣革命、君主立宪。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-028","t":"美国独立战争","cid":"10f","p":1,"kind":"事件","exam":["2010选择"],"alias":["北美独立战争","美国革命"],"one":"1775至1783年北美殖民地反抗英国，1776年7月4日发表《独立宣言》。","ans":"美国独立战争是**1775—1783年北美十三个英属殖民地反抗英国殖民统治的战争**，也是一场资产阶级革命。**1775年莱克星顿枪声**打响战争，**1776年7月4日**大陆会议通过**杰斐逊起草的《独立宣言》**，宣告美国诞生，华盛顿任大陆军总司令。1781年约克镇一战英军主力投降，**1783年英国承认美国独立**。战后于**1787年制定联邦宪法**，实行三权分立，**华盛顿任首任总统**。这场战争建立了近代第一个资产阶级共和国，对法国大革命和拉丁美洲独立运动起到示范作用。","pts":["1775莱克星顿，1776.7.4《独立宣言》","1783年英国承认独立","1787年宪法，华盛顿首任总统"],"mem":"尾数口诀（自编）：75开枪，76宣言，83承认，87立宪。7月4日是美国独立日，记“七七六”（7月、1776）。","mix":"1776年是宣布独立，1783年才获英国承认，1787年制宪，1789年华盛顿就任总统，四个年份不要混；2010届选择题考的是宣布独立的时间。1861—1865年的南北战争是另一场战争。","mcq":[{"q":"美国宣布独立的时间是","o":["1775年","1783年","1776年","1787年"],"a":2,"w":"1776年7月4日通过《独立宣言》。"},{"q":"美国独立战争爆发的标志是","o":["波士顿倾茶事件","莱克星顿枪声","签署《独立宣言》","约克镇战役"],"a":1,"w":"1775年莱克星顿枪声；倾茶事件（1773）是导火索，约克镇战役（1781）是决定性战役。"}],"rel":[{"t":"《独立宣言》","n":"1776年的建国文献"},{"t":"1787年美国宪法","n":"战后建立联邦制"},{"t":"华盛顿","n":"总司令和首任总统"},{"t":"法国大革命","n":"随后爆发，受其影响"}],"more":"1775年：莱克星顿枪声。\n1776年7月4日：《独立宣言》。\n1781年：约克镇战役。\n1783年：英国承认独立（《巴黎和约》）。\n1787年：联邦宪法。"},{"id":"b10-029","t":"法国大革命","cid":"10f","p":1,"kind":"事件","alias":["法国资产阶级革命","1789年革命"],"one":"1789年巴黎攻占巴士底狱爆发，通过《人权宣言》，建立共和国。","ans":"法国大革命是**1789年起法国的资产阶级革命**，推翻了波旁王朝的封建专制。**1789年7月14日巴黎人民攻占巴士底狱**，革命爆发，这一天后来成为法国国庆日；同年制宪议会通过**《人权宣言》**，提出“人生而自由，权利平等”。**1792年建立第一共和国**，**1793年处死路易十六**，雅各宾派实行专政。**1799年拿破仑发动雾月政变**，掌握政权。大革命沉重打击了欧洲封建制度，**自由、平等、博爱**的口号和《拿破仑法典》传遍欧洲，是近代民主政治的重要起点。","pts":["1789.7.14攻占巴士底狱","《人权宣言》，1792年建立共和国","1793处死路易十六；1799雾月政变"],"mem":"年份串线（自编）：89攻狱立宣言，92建共和，93杀国王，99拿破仑上台。画面：7月14日巴黎人冲进监狱，这一天成了法国国庆日。","mix":"按年代排列三份革命文献：英国《权利法案》（1689）、美国《独立宣言》（1776）、法国《人权宣言》（1789）。十月革命是1917年的俄国，巴黎公社是1871年。","mcq":[{"q":"法国大革命爆发的标志是","o":["攻占巴士底狱","拿破仑称帝","处死路易十六","建立第一共和国"],"a":0,"w":"1789年7月14日攻占巴士底狱。"},{"q":"下列事件按时间先后排列正确的是","o":["处死路易十六、《人权宣言》、雾月政变、拿破仑称帝","《人权宣言》、雾月政变、处死路易十六、拿破仑称帝","雾月政变、《人权宣言》、处死路易十六、拿破仑称帝","《人权宣言》、处死路易十六、雾月政变、拿破仑称帝"],"a":3,"w":"1789年《人权宣言》，1793年处死路易十六，1799年雾月政变，1804年称帝。"}],"rel":[{"t":"《人权宣言》","n":"大革命的纲领文献"},{"t":"拿破仑","n":"终结并继承革命"},{"t":"攻占巴士底狱","n":"革命爆发的标志"},{"t":"美国独立战争","n":"先于法国十余年"}],"more":"1789年7月14日：攻占巴士底狱。\n1789年8月：《人权宣言》。\n1792年：第一共和国。\n1793年：路易十六被处死。\n1799年：雾月政变。","exam":[]},{"id":"b10-030","t":"工业革命","cid":"10g","p":1,"kind":"事件","alias":["第一次工业革命","产业革命","蒸汽时代"],"one":"18世纪60年代起源于英国，由手工工场转向机器大工业的技术与社会变革。","ans":"工业革命是**18世纪60年代首先在英国开始的由手工工场向机器大工业转变的技术革命和社会变革**，又称第一次工业革命。它从棉纺织业起步，**哈格里夫斯发明珍妮纺纱机**（1765年前后），**瓦特改良蒸汽机**（1785年投入使用）使人类进入**“蒸汽时代”**，**史蒂芬孙**制造的蒸汽机车推动了铁路时代。工业革命使机器取代手工，**工厂制度确立**，工业资产阶级和无产阶级形成，英国成为“世界工厂”。19世纪后期，以电力广泛应用为标志的**第二次工业革命**进入“电气时代”。","pts":["英国，18世纪60年代，手工到机器","珍妮机、瓦特蒸汽机","两次工业革命：蒸汽时代、电气时代"],"mem":"“珍、瓦、史”三件套：珍妮机（纺织）、瓦特机（动力）、史蒂芬孙（铁路），从纺纱一路到火车。时代标签：一蒸汽，二电气，三信息。","mix":"第一次工业革命在英国，蒸汽时代；第二次以电力为标志，美、德领先；第三次是20世纪中叶的信息时代。不加序号的“工业革命”通常指第一次。","mcq":[{"q":"第一次工业革命首先发生在","o":["德国","英国","美国","法国"],"a":1,"w":"英国，从棉纺织业开始。"},{"q":"下列发明与发明者对应正确的是","o":["哈格里夫斯：珍妮纺纱机","瓦特：蒸汽机车","史蒂芬孙：电灯","爱迪生：飞机"],"a":0,"w":"蒸汽机车是史蒂芬孙，电灯是爱迪生，飞机是莱特兄弟。"}],"rel":[{"t":"瓦特改良蒸汽机","n":"动力革命的核心"},{"t":"史蒂芬孙与铁路","n":"交通革命"},{"t":"第二次工业革命","n":"随后的电气时代"},{"t":"第三次科技革命","n":"之后的信息时代"}],"more":"1765年前后：珍妮纺纱机。\n1785年：瓦特改良蒸汽机投入使用。\n19世纪初：蒸汽机车、汽船出现。\n19世纪70年代：进入电气时代。","exam":[]},{"id":"b10-031","t":"罗马共和国与帝国","cid":"10b","p":2,"kind":"概念","exam":[],"alias":[],"one":"前509年建立罗马共和国，前5世纪颁布《十二铜表法》；布匿战争（前264—前","ans":"前509年建立罗马共和国，前5世纪颁布《十二铜表法》；布匿战争（前264—前146）击败迦太基；前27年屋大维获“奥古斯都”称号，帝国开始；395年东西分裂，476年西罗马灭亡","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-032","t":"查理曼帝国","cid":"10d","p":2,"kind":"概念","exam":[],"alias":[],"one":"法兰克国王查理（查理大帝）800年被教皇加冕为“罗马人的皇帝”；843年《凡","ans":"法兰克国王查理（查理大帝）800年被教皇加冕为“罗马人的皇帝”；843年《凡尔登条约》三分帝国，奠定法、德、意雏形","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-033","t":"神圣罗马帝国","cid":"10d","p":2,"kind":"概念","exam":[],"alias":[],"one":"962年德意志国王奥托一世加冕建立，1806年被拿破仑解散；伏尔泰称其“既不","ans":"962年德意志国王奥托一世加冕建立，1806年被拿破仑解散；伏尔泰称其“既不神圣，也不罗马，更非帝国”","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-034","t":"《大宪章》","cid":"10d","p":1,"kind":"作品","alias":["大宪章","自由大宪章"],"one":"1215年英国贵族迫使约翰王签署，限制王权，英国宪政开端。","ans":"《大宪章》是**1215年英国贵族在兰尼米德迫使约翰王签署的文件**，共63条。约翰王对法战争失败，横征暴敛，与教会、贵族矛盾激化，贵族以武力迫使其让步。宪章规定**国王未经“大会议”同意不得征税，不经合法审判不得逮捕、监禁自由人**，使王权受到法律约束。后来的议会制度、人身保护和“法律之上无国王”的原则，都以它为源头，因此被视为**英国宪政的开端**，对近代《权利法案》等文件有深远影响。","pts":["1215年贵族迫使约翰王签署","未经同意不得征税，不得任意逮捕","限制王权，英国宪政开端"],"mem":"三个关键词：1215、约翰王、贵族。一句话内容：国王也要守法。画面：贵族们带着武器围着国王，在兰尼米德草地上逼他盖印。后续链条：《大宪章》1215→议会萌芽→1689年《权利法案》。","mix":"《大宪章》约束的是国王，签署者是约翰王，不是理查一世（狮心王）；它最初主要保护贵族利益，普通人受益是后来逐步演变的结果；《权利法案》是1689年光荣革命后的文件。","mcq":[{"q":"1215年被英国贵族迫使签署《大宪章》的国王是","o":["亨利八世","约翰王","查理一世","爱德华一世"],"a":1,"w":"约翰王在兰尼米德签署。"},{"q":"《大宪章》被视为英国哪方面的开端","o":["殖民扩张","宗教改革","工业革命","宪政"],"a":3,"w":"其核心原则是国王也受法律约束。"}],"rel":[{"t":"《权利法案》（英国）","n":"后来的宪政文件"},{"t":"欧洲中世纪","n":"所属时代"},{"t":"《独立宣言》","n":"同样诉诸权利的文献"},{"t":"封建采邑制","n":"贵族权利的背景"}],"more":"宪章第39条：任何自由人，如未经同侪依法判决，不得被逮捕、监禁、剥夺权利。","exam":[]},{"id":"b10-035","t":"黑死病","cid":"10d","p":1,"kind":"事件","alias":["鼠疫大流行","黑死病大瘟疫"],"one":"14世纪中叶席卷欧洲的鼠疫，约三分之一人口死亡。","ans":"黑死病是**14世纪中叶席卷欧洲的鼠疫大流行**，由鼠疫杆菌引起，**1347年经热那亚商船传入意大利西西里**，随后迅速蔓延至全欧，约1351年前后趋缓，**欧洲约三分之一人口死亡**。疫病使劳动力锐减，工价上涨，**农奴地位提高，庄园制度瓦解**；教会无力救治，**权威受到动摇**，也冲击了人们的中世纪信仰。黑死病与十字军、百年战争一起，削弱了旧秩序，为文艺复兴和近代社会转型创造了条件。","pts":["14世纪中叶欧洲鼠疫，约三分之一人口死亡","劳动力短缺，农奴地位提高","动摇教会权威，旧秩序瓦解"],"mem":"逻辑线：人口锐减→劳动力稀缺→工钱上涨、农奴谈条件→庄园制瓦解；教会祈祷无效→权威下降→人文主义抬头。数字记“1347传入，三分之一死亡”。","mix":"黑死病指14世纪的鼠疫，与6世纪查士丁尼瘟疫、19世纪鼠疫大流行相区分；死亡比例有多种估计，通行说法为三分之一左右。","mcq":[{"q":"黑死病主要流行于欧洲的时间是","o":["8世纪","14世纪中叶","16世纪","18世纪"],"a":1,"w":"1347年起传入欧洲，14世纪中叶达到高峰。"},{"q":"黑死病对中世纪欧洲的影响不包括","o":["劳动力短缺，农奴地位提高","教会权威受到动摇","庄园制度瓦解","封建制度因此强化"],"a":3,"w":"黑死病加速了庄园制与农奴制的瓦解。"}],"rel":[{"t":"欧洲中世纪","n":"所属时代"},{"t":"庄园制度","n":"受冲击的制度"},{"t":"百年战争","n":"同期的动荡"},{"t":"文艺复兴","n":"后续的思想转变"}],"exam":[]},{"id":"b10-036","t":"百年战争","cid":"10d","p":2,"kind":"事件","exam":[],"alias":[],"one":"1337—1453年英法之间的战争，法国民族英雄贞德，法国最终获胜","ans":"1337—1453年英法之间的战争，法国民族英雄贞德，法国最终获胜","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-037","t":"阿拉伯帝国与百年翻译运动","cid":"10d","p":2,"kind":"事件","exam":[],"alias":[],"one":"632年后阿拉伯人建立横跨亚非欧的帝国；8—10世纪阿拔斯王朝在巴格达设“智","ans":"632年后阿拉伯人建立横跨亚非欧的帝国；8—10世纪阿拔斯王朝在巴格达设“智慧宫”，大规模把古希腊、波斯、印度典籍译成阿拉伯文，后经西班牙传回欧洲；翻译史考点","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-038","t":"奥斯曼帝国","cid":"10d","p":2,"kind":"概念","exam":[],"alias":[],"one":"1299年建立，1453年攻灭拜占庭，定都伊斯坦布尔，横跨三洲；一战后解体，","ans":"1299年建立，1453年攻灭拜占庭，定都伊斯坦布尔，横跨三洲；一战后解体，1923年建立土耳其共和国","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-039","t":"经院哲学","cid":"10d","p":2,"kind":"流派","exam":[],"alias":[],"one":"中世纪教会学校中为神学服务的哲学，代表托马斯·阿奎那《神学大全》","ans":"中世纪教会学校中为神学服务的哲学，代表托马斯·阿奎那《神学大全》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-040","t":"庄园制度","cid":"10d","p":2,"kind":"制度","exam":[],"alias":[],"one":"中世纪西欧封建主的经济单位，农奴依附于领主，自给自足","ans":"中世纪西欧封建主的经济单位，农奴依附于领主，自给自足","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-041","t":"骑士制度","cid":"10d","p":2,"kind":"制度","exam":[],"alias":[],"one":"中世纪西欧最低一级封建主，信奉忠君、护教、行侠的骑士精神；塞万提斯《堂吉诃德","ans":"中世纪西欧最低一级封建主，信奉忠君、护教、行侠的骑士精神；塞万提斯《堂吉诃德》讽刺骑士小说","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-042","t":"中世纪大学","cid":"10d","p":3,"kind":"制度","exam":[],"alias":[],"one":"博洛尼亚大学（1088）被视为欧洲最古老大学，另有巴黎大学、牛津大学、剑桥大","ans":"博洛尼亚大学（1088）被视为欧洲最古老大学，另有巴黎大学、牛津大学、剑桥大学（1209）","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-043","t":"1453年","cid":"10d","p":2,"kind":"事件","exam":[],"alias":[],"one":"拜占庭灭亡；常作为中世纪结束、近代开端的标志之一；与1492年哥伦布到达美洲","ans":"拜占庭灭亡；常作为中世纪结束、近代开端的标志之一；与1492年哥伦布到达美洲同为分期标志","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-044","t":"百科全书","cid":"10f","p":1,"kind":"作品","exam":["2013名解","2015名解"],"alias":["《百科全书》","《不列颠百科全书》","《中国大百科全书》"],"one":"按条目汇集各门知识的大型工具书；西方以狄德罗主编的法国《百科全书》最著名。","ans":"百科全书是**系统汇集各门类知识、按条目编排的大型工具书**。西方最著名的是**18世纪法国狄德罗主编的《百科全书》**（1751—1772年陆续出版），伏尔泰、孟德斯鸠、卢梭等人参与撰稿，宣传理性与科学，形成**“百科全书派”**，为启蒙运动和法国大革命作了思想准备。1768年起在爱丁堡出版的**《不列颠百科全书》**是英语世界的权威。中国古代的类书如明代**《永乐大典》**常被称为古代规模最大的百科全书，当代则有1978年起编纂的**《中国大百科全书》**。","pts":["定义：按条目汇集各门知识的工具书","狄德罗主编，1751—1772，百科全书派","中国：《永乐大典》类书；《中国大百科全书》"],"mem":"三国三部（自编）：法国狄德罗《百科全书》1751，英国《不列颠百科全书》1768，中国《中国大百科全书》1978起。逻辑线：知识按条目编，理性当标尺，所以成了启蒙运动的旗帜。","mix":"《永乐大典》是明代类书，《古今图书集成》是清代类书，《四库全书》是丛书，都属于中国古代的知识汇编，与现代意义的百科全书有别；狄德罗是主编，撰稿人有数百位。","mcq":[{"q":"18世纪法国《百科全书》的主编是","o":["伏尔泰","孟德斯鸠","狄德罗","卢梭"],"a":2,"w":"狄德罗主编，1751—1772年出版。"},{"q":"下列关于百科全书的表述，正确的是","o":["狄德罗主编的《百科全书》18世纪出版于法国","《永乐大典》是清代编纂的类书","《不列颠百科全书》最早由法国人编纂","《中国大百科全书》自1949年起编纂"],"a":0,"w":"《永乐大典》是明代；《不列颠百科全书》1768年起出版于爱丁堡；《中国大百科全书》1978年起编纂。"}],"rel":[{"t":"启蒙运动","n":"百科全书派的思想背景"},{"t":"《永乐大典》","n":"中国古代最大类书"},{"t":"《古今图书集成》","n":"清代大型类书"},{"t":"《四库全书》","n":"清代大型丛书"}],"more":"法国《百科全书》全称《百科全书，或科学、艺术和工艺详解词典》，共28卷（正文17卷，图版11卷）。\n2013、2015年名解均考过。"},{"id":"b10-045","t":"西班牙","cid":"10e","p":2,"kind":"地理","exam":["2016名解"],"alias":[],"one":"位于伊比利亚半岛，首都马德里。8世纪起被阿拉伯人统治，1492年完成“收复失","ans":"位于伊比利亚半岛，首都马德里。8世纪起被阿拉伯人统治，1492年完成“收复失地运动”并资助哥伦布航行美洲，16世纪成为殖民大国，1588年“无敌舰队”被英国击败；文学有塞万提斯《堂吉诃德》，现代有毕加索、高迪（圣家族大教堂）；1939—1975年佛朗哥独裁，1978年起实行君主立宪。要点：伊比利亚半岛、1492年、无敌舰队、塞万提斯。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-046","t":"美洲三大古文明","cid":"10a","p":3,"kind":"合称","exam":[],"alias":[],"one":"玛雅文明（中美洲尤卡坦半岛，象形文字、精确历法、“零”的概念）、阿兹特克文明","ans":"玛雅文明（中美洲尤卡坦半岛，象形文字、精确历法、“零”的概念）、阿兹特克文明（今墨西哥城一带）、印加文明（南美安第斯山区，马丘比丘）","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-047","t":"腓尼基字母","cid":"10b","p":2,"kind":"常识","exam":[],"alias":[],"one":"地中海东岸腓尼基人创造的22个辅音字母，是希腊字母、拉丁字母的源头","ans":"地中海东岸腓尼基人创造的22个辅音字母，是希腊字母、拉丁字母的源头","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-048","t":"古代世界七大奇迹","cid":"10b","p":3,"kind":"合称","exam":[],"alias":[],"one":"吉萨金字塔、巴比伦空中花园、阿尔忒弥斯神庙、奥林匹亚宙斯像、摩索拉斯陵墓、罗","ans":"吉萨金字塔、巴比伦空中花园、阿尔忒弥斯神庙、奥林匹亚宙斯像、摩索拉斯陵墓、罗得岛巨像、亚历山大灯塔；仅金字塔现存","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-049","t":"新巴比伦","cid":"10a","p":3,"kind":"概念","exam":[],"alias":[],"one":"迦勒底人建立，尼布甲尼撒二世修建“空中花园”，前539年被波斯所灭","ans":"迦勒底人建立，尼布甲尼撒二世修建“空中花园”，前539年被波斯所灭","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-050","t":"亚述","cid":"10a","p":3,"kind":"概念","exam":[],"alias":[],"one":"两河流域北部的军事帝国，都城尼尼微，亚述巴尼拔图书馆藏有大量泥板文献","ans":"两河流域北部的军事帝国，都城尼尼微，亚述巴尼拔图书馆藏有大量泥板文献","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-051","t":"琐罗亚斯德教","cid":"10b","p":3,"kind":"概念","exam":[],"alias":[],"one":"古波斯宗教，崇拜光明之神阿胡拉·马兹达，以火为光明象征，传入中国称祆教、拜火","ans":"古波斯宗教，崇拜光明之神阿胡拉·马兹达，以火为光明象征，传入中国称祆教、拜火教","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-052","t":"吠陀","cid":"10a","p":3,"kind":"作品","exam":[],"alias":[],"one":"古印度最古老的宗教文献，以《梨俱吠陀》最古，婆罗门教的经典","ans":"古印度最古老的宗教文献，以《梨俱吠陀》最古，婆罗门教的经典","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-053","t":"好望角","cid":"10e","p":3,"kind":"地理","exam":[],"alias":[],"one":"非洲西南端（南非），1488年迪亚士到达，原称“风暴角”","ans":"非洲西南端（南非），1488年迪亚士到达，原称“风暴角”","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-054","t":"君士坦丁堡","cid":"10d","p":3,"kind":"地理","exam":[],"alias":[],"one":"330年君士坦丁大帝迁都于此，拜占庭帝国首都，今土耳其伊斯坦布尔","ans":"330年君士坦丁大帝迁都于此，拜占庭帝国首都，今土耳其伊斯坦布尔","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-055","t":"诺曼征服","cid":"10d","p":2,"kind":"事件","exam":[],"alias":[],"one":"1066年诺曼底公爵威廉在黑斯廷斯战役获胜，成为英格兰国王，法语词汇大量进入","ans":"1066年诺曼底公爵威廉在黑斯廷斯战役获胜，成为英格兰国王，法语词汇大量进入英语；英语史考点","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b10-056","t":"赫拉克勒斯之柱","cid":"10i","p":3,"kind":"地理","exam":[],"alias":[],"one":"古代对直布罗陀海峡两岸岬角的称呼，象征已知世界的尽头","ans":"古代对直布罗陀海峡两岸岬角的称呼，象征已知世界的尽头","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"c-056","t":"四大文明古国","cid":"10a","p":1,"kind":"合称","alias":["四大文明古国","四大古文明"],"one":"古巴比伦、古埃及、古印度、中国，四个大河流域的早期文明。","ans":"四大文明古国指**古巴比伦、古埃及、古印度和中国**，是人类早期**发源于大河流域的四个文明**。古巴比伦位于**两河流域**，有楔形文字和《汉谟拉比法典》；古埃及位于**尼罗河**流域，有象形文字和金字塔；古印度位于**印度河**流域，有哈拉帕、摩亨佐-达罗城市遗址；中国位于**黄河、长江**流域，有甲骨文和青铜器。这一合称流行于近代，四者中**中国文明延续至今**，其余三者或中断，或被后来的文明取代。","pts":["古巴比伦、古埃及、古印度、中国","各依托两河、尼罗河、印度河、黄河长江","只有中国文明延续至今"],"members":[["古巴比伦","两河流域；楔形文字、《汉谟拉比法典》"],["古埃及","尼罗河；象形文字、金字塔"],["古印度","印度河；哈拉帕、摩亨佐-达罗"],["中国","黄河、长江；甲骨文、青铜器"]],"mem":"“巴埃印中”按河流记：两河、尼罗、印度河、黄河长江。每个文明配一个标志物：泥板、金字塔、大浴池、甲骨。美洲三大（玛雅、阿兹特克、印加）另算，不在四大之内。","mix":"古希腊、古罗马、波斯以及美洲玛雅、阿兹特克、印加都不属于四大文明古国；“古巴比伦”有时写作“两河流域”。","mcq":[{"q":"下列不属于四大文明古国的是","o":["古希腊","古印度","古埃及","古巴比伦"],"a":0,"w":"四大文明古国是古巴比伦、古埃及、古印度和中国。"},{"q":"古印度文明发源于","o":["恒河流域","幼发拉底河流域","尼罗河流域","印度河流域"],"a":3,"w":"印度河文明是古印度最早的文明。"}],"rel":[{"t":"两河流域","n":"古巴比伦所在"},{"t":"古埃及文明","n":"尼罗河文明"},{"t":"印度河文明","n":"古印度文明"},{"t":"美洲三大古文明","n":"美洲的对应说法"},{"t":"中华文明探源工程","n":"中国文明起源研究"}],"more":"四大文明古国的说法并非学界严格分类，是通行的教科书说法。","exam":[]},{"id":"c-057","t":"文坛三杰","cid":"10e","p":1,"kind":"合称","alias":["文艺复兴文坛三杰"],"one":"但丁、彼特拉克、薄伽丘，意大利文艺复兴文学三位先驱。","ans":"文坛三杰指**意大利文艺复兴时期的三位文学巨匠但丁、彼特拉克、薄伽丘**，均生于佛罗伦萨一带。**但丁（1265—1321）**著长诗《神曲》，被称为**中世纪最后一位诗人、新时代最初一位诗人**；**彼特拉克（1304—1374）**著抒情诗集《歌集》，被称为**“人文主义之父”**，获桂冠诗人称号；**薄伽丘（1313—1375）**著短篇小说集《十日谈》，批判教会禁欲主义。三人以意大利语创作，**开启了欧洲近代文学**。","pts":["但丁、彼特拉克、薄伽丘","《神曲》《歌集》《十日谈》","人文主义文学先驱，用意大利语创作"],"members":[["但丁","《神曲》；中世纪最后一位诗人"],["彼特拉克","《歌集》；人文主义之父，桂冠诗人"],["薄伽丘","《十日谈》；批判禁欲主义"]],"mem":"“但神、彼歌、薄十”：但丁《神曲》、彼特拉克《歌集》、薄伽丘《十日谈》。按年龄也是但丁、彼特拉克、薄伽丘依次年轻。三人都用意大利语（俗语）而不是拉丁语写作。","mix":"文坛三杰是文学家，达·芬奇等是美术三杰；莎士比亚、塞万提斯属文艺复兴后期，不在三杰之列。","mcq":[{"q":"《十日谈》的作者是","o":["但丁","彼特拉克","薄伽丘","塞万提斯"],"a":2,"w":"《十日谈》是薄伽丘的短篇小说集。"},{"q":"被称为“人文主义之父”的诗人是","o":["彼特拉克","但丁","薄伽丘","莎士比亚"],"a":0,"w":"彼特拉克倡导人文主义，被称为人文主义之父。"}],"rel":[{"t":"但丁","n":"《神曲》作者"},{"t":"彼特拉克","n":"人文主义之父"},{"t":"薄伽丘","n":"《十日谈》作者"},{"t":"美术三杰","n":"美术上的对举"},{"t":"文艺复兴","n":"所属运动"}],"exam":[]},{"id":"c-058","t":"美术三杰","cid":"10h","p":1,"kind":"合称","exam":["2012选择"],"alias":["文艺复兴美术三杰","文艺复兴三杰"],"one":"达·芬奇、米开朗基罗、拉斐尔，意大利文艺复兴盛期的三位艺术大师。","ans":"美术三杰指**意大利文艺复兴盛期的三位艺术大师达·芬奇、米开朗基罗、拉斐尔**，与文学上的但丁、彼特拉克、薄伽丘“文坛三杰”相对。达·芬奇（1452—1519）作**《蒙娜丽莎》《最后的晚餐》**；米开朗基罗（1475—1564）作**雕像《大卫》**和西斯廷教堂天顶画；拉斐尔（1483—1520）作**《雅典学院》**，以圣母像著称。三人把**人文主义和写实精神**带入艺术，奠定了西方绘画透视和解剖的基础，代表了**文艺复兴艺术的最高成就**。","pts":["达·芬奇、米开朗基罗、拉斐尔","蒙娜丽莎；大卫；雅典学院","文艺复兴盛期，人文主义"],"members":[["达·芬奇","《蒙娜丽莎》《最后的晚餐》"],["米开朗基罗","雕像《大卫》，西斯廷教堂天顶画"],["拉斐尔","《雅典学院》，圣母像"]],"mem":"“达米拉”三字：达（芬奇）、米（开朗基罗）、拉（斐尔），按年龄从长到幼。作品对应：达画笑（蒙娜丽莎），米刻人（大卫），拉绘群贤（雅典学院）。","mix":"美术三杰与“文坛三杰”（但丁、彼特拉克、薄伽丘）都属文艺复兴，不要交叉；后印象派三大家（塞尚、梵高、高更）是19世纪后期；《西斯廷圣母》是拉斐尔，天顶画是米开朗基罗。","mcq":[{"q":"下列画家中，不属于文艺复兴“美术三杰”的是","o":["达·芬奇","拉斐尔","米开朗基罗","伦勃朗"],"a":3,"w":"伦勃朗是17世纪荷兰画家。"},{"q":"《雅典学院》的作者是","o":["达·芬奇","米开朗基罗","拉斐尔","提香"],"a":2,"w":"拉斐尔作于梵蒂冈。"}],"rel":[{"t":"达·芬奇","n":"三杰之首"},{"t":"米开朗基罗","n":"雕刻与天顶画"},{"t":"拉斐尔","n":"《雅典学院》作者"},{"t":"文坛三杰","n":"文学上的对照"}],"more":"也称“文艺复兴三杰”。\n2012届选择题考查过。"},{"id":"a10-001","t":"象形文字","cid":"10a","p":2,"kind":"常识","exam":[],"alias":[],"one":"古埃及文字，多刻于神庙或写在纸莎草上；商博良借罗塞塔石碑释读成功。","ans":"古埃及文字，多刻于神庙或写在纸莎草上；商博良借罗塞塔石碑释读成功。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-002","t":"法老","cid":"10a","p":3,"kind":"常识","exam":[],"alias":[],"one":"古埃及国王称号，原意“大房子”，被视为太阳神之子；胡夫金字塔是第四王朝法老胡","ans":"古埃及国王称号，原意“大房子”，被视为太阳神之子；胡夫金字塔是第四王朝法老胡夫的陵墓。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-003","t":"木乃伊与《亡灵书》","cid":"10a","p":3,"kind":"常识","exam":[],"alias":[],"one":"古埃及人相信灵魂不灭，用香料防腐保存遗体；《亡灵书》放入墓中，指引亡灵通往来","ans":"古埃及人相信灵魂不灭，用香料防腐保存遗体；《亡灵书》放入墓中，指引亡灵通往来世。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-004","t":"古巴比伦王国","cid":"10a","p":2,"kind":"概念","exam":[],"alias":[],"one":"约前19至前16世纪，第六代国王汉谟拉比统一两河流域并颁布法典；前7至前6世","ans":"约前19至前16世纪，第六代国王汉谟拉比统一两河流域并颁布法典；前7至前6世纪的新巴比伦王国是另一政权（空中花园、尼布甲尼撒二世）。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-005","t":"哈拉帕文化","cid":"10a","p":3,"kind":"概念","exam":[],"alias":[],"one":"印度河文明的别称（约前2500至前1750年），代表遗址哈拉帕与摩亨佐-达罗","ans":"印度河文明的别称（约前2500至前1750年），代表遗址哈拉帕与摩亨佐-达罗（今巴基斯坦），城市规划整齐，有排水系统，印章文字未释读。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-006","t":"雅利安人","cid":"10a","p":2,"kind":"概念","exam":[],"alias":[],"one":"约前1500年前后由中亚进入印度西北，创造吠陀文化，形成婆罗门、刹帝利、吠舍","ans":"约前1500年前后由中亚进入印度西北，创造吠陀文化，形成婆罗门、刹帝利、吠舍、首陀罗四个等级的瓦尔那制度。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-008","t":"玛雅文明","cid":"10a","p":2,"kind":"概念","exam":[],"alias":[],"one":"中美洲尤卡坦半岛一带，有象形文字、精确历法、“零”的概念和金字塔式神庙。","ans":"中美洲尤卡坦半岛一带，有象形文字、精确历法、“零”的概念和金字塔式神庙。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-009","t":"阿兹特克与印加","cid":"10a","p":3,"kind":"概念","exam":[],"alias":[],"one":"阿兹特克在墨西哥，都城特诺奇蒂特兰（今墨西哥城），1521年被西班牙人科尔特","ans":"阿兹特克在墨西哥，都城特诺奇蒂特兰（今墨西哥城），1521年被西班牙人科尔特斯征服；印加在南美安第斯山区，都城库斯科，有马丘比丘遗址，1533年被皮萨罗征服。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-010","t":"犹太人","cid":"10b","p":2,"kind":"概念","exam":[],"alias":[],"one":"源于古希伯来人，信奉犹太教；公元70年罗马攻陷耶路撒冷后大规模流散世界；19","ans":"源于古希伯来人，信奉犹太教；公元70年罗马攻陷耶路撒冷后大规模流散世界；1948年以色列建国。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-012","t":"居鲁士与大流士","cid":"10b","p":3,"kind":"人物","exam":[],"alias":[],"one":"居鲁士二世约前550年建立阿契美尼德王朝；大流士一世设行省、修“御道”，发动","ans":"居鲁士二世约前550年建立阿契美尼德王朝；大流士一世设行省、修“御道”，发动希波战争；前330年帝国亡于亚历山大。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-013","t":"迦太基与布匿战争","cid":"10b","p":3,"kind":"事件","exam":[],"alias":[],"one":"腓尼基人在北非建立迦太基，与罗马三次布匿战争（前264至前146年），汉尼拔","ans":"腓尼基人在北非建立迦太基，与罗马三次布匿战争（前264至前146年），汉尼拔翻越阿尔卑斯山，迦太基最终被毁。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-014","t":"《十二铜表法》","cid":"10b","p":2,"kind":"作品","exam":[],"alias":[],"one":"约前450年罗马共和国制定的第一部成文法，刻在12块铜牌上。","ans":"约前450年罗马共和国制定的第一部成文法，刻在12块铜牌上。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-015","t":"罗马法与《民法大全》","cid":"10b","p":2,"kind":"制度","exam":[],"alias":[],"one":"包括市民法与万民法；6世纪东罗马皇帝查士丁尼主持编纂《民法大全》（《国法大全","ans":"包括市民法与万民法；6世纪东罗马皇帝查士丁尼主持编纂《民法大全》（《国法大全》），影响《拿破仑法典》与大陆法系。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-016","t":"恺撒","cid":"10b","p":2,"kind":"人物","exam":[],"alias":[],"one":"罗马共和末期统帅，前49年渡卢比孔河（“骰子已经掷下”），“我来，我见，我征","ans":"罗马共和末期统帅，前49年渡卢比孔河（“骰子已经掷下”），“我来，我见，我征服”，著《高卢战记》，前44年遇刺；儒略历以其命名。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-017","t":"屋大维","cid":"10b","p":3,"kind":"人物","exam":[],"alias":[],"one":"恺撒养子，前27年获“奥古斯都”称号，开创元首制；八月August得名于他。","ans":"恺撒养子，前27年获“奥古斯都”称号，开创元首制；八月August得名于他。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-018","t":"斯巴达克起义","cid":"10b","p":3,"kind":"事件","exam":[],"alias":[],"one":"前73至前71年，古罗马规模最大的奴隶起义。","ans":"前73至前71年，古罗马规模最大的奴隶起义。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-019","t":"基督教成为罗马国教","cid":"10b","p":3,"kind":"事件","exam":[],"alias":[],"one":"313年君士坦丁颁布《米兰敕令》承认基督教合法；4世纪末狄奥多西一世时成为国","ans":"313年君士坦丁颁布《米兰敕令》承认基督教合法；4世纪末狄奥多西一世时成为国教。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-020","t":"庞贝古城","cid":"10b","p":3,"kind":"常识","exam":[],"alias":[],"one":"79年维苏威火山爆发被掩埋，18世纪起发掘。","ans":"79年维苏威火山爆发被掩埋，18世纪起发掘。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-021","t":"古罗马斗兽场","cid":"10b","p":3,"kind":"常识","exam":[],"alias":[],"one":"弗拉维王朝时期建成（80年），又称科洛西姆，可容纳约5万观众。","ans":"弗拉维王朝时期建成（80年），又称科洛西姆，可容纳约5万观众。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-022","t":"西域","cid":"10c","p":1,"kind":"地理","alias":["西域诸国"],"one":"汉代以后对玉门关、阳关以西地区的总称，前60年设西域都护府。","ans":"西域是**汉代以后对玉门关、阳关以西地区的总称**。狭义指**今新疆一带**，广义包括中亚、西亚、南亚乃至欧洲东部。**张骞出使后**西域与中原正式交通，前60年**西汉设西域都护府**，由郑吉任首任都护，管辖天山南北，标志**西域正式纳入中国版图**。汉代西域本有三十六国，后分为五十余国，著名的有大宛、大月氏、乌孙、楼兰等。此地是**丝绸之路的必经之地**，也是佛教等多种文化的交汇处。","pts":["玉门关、阳关以西地区的总称","张骞出使后交通，前60年设都护府","丝绸之路必经，三十六国"],"mem":"“西域”看参照物：玉门关、阳关以西。三步记：①张骞凿空（前138、前119），②设西域都护府（前60），③三十六国分为五十余国。范围口诀：狭义新疆，广义到中亚、西亚、南亚。","mix":"西域都护府设于前60年（西汉），唐代另设安西都护府和北庭都护府；“西域”是古代地理概念，范围随时代变化。","mcq":[{"q":"西汉前60年在西域设置的机构是","o":["安西都护府","西域都护府","北庭都护府","河西四郡"],"a":1,"w":"郑吉为首任西域都护，标志西域正式归属中央政权。"},{"q":"汉代所说“西域”的狭义范围主要是今天的","o":["青藏高原","内蒙古","新疆一带","河西走廊"],"a":2,"w":"狭义西域指玉门关、阳关以西，今新疆一带。"}],"rel":[{"t":"西域与西域都护府","n":"同一主题的制度面"},{"t":"张骞通西域","n":"开通西域"},{"t":"丝绸之路","n":"西域是必经之地"},{"t":"《大唐西域记》","n":"玄奘西域见闻"}],"more":"《汉书·西域传》：西域以孝武时始通，本三十六国，其后稍分至五十余。","exam":[]},{"id":"a10-023","t":"张骞通西域","cid":"10c","p":1,"kind":"事件","alias":["张骞出使西域","张骞凿空"],"one":"西汉张骞两次出使西域，司马迁称“凿空”，开通丝绸之路。","ans":"张骞通西域是**西汉武帝时张骞两次出使西域**的事件。**前138年（一说前139年）**他奉命出使，目的是联合**大月氏夹击匈奴**，途中被匈奴扣留十余年，抵达大月氏、大夏后，**前126年**返汉，虽未达成军事同盟，却带回西域的地理与物产信息。**前119年**他第二次出使**乌孙**，并派副使前往大宛、康居、大月氏、大夏、安息、身毒等国。司马迁称之为**“凿空”**，意为开通道路。此行**开辟了丝绸之路**，加强了汉与西域的联系，张骞被封为博望侯。","pts":["前138年联合大月氏，前119年出使乌孙","被匈奴扣留十余年，带回西域信息","司马迁称“凿空”，开辟丝绸之路"],"mem":"两次出使记目的地：一次大月氏（联合抗匈奴），二次乌孙。自编口诀：“一月氏，二乌孙”。年份相差19年（前138、前119）。成果一个词：凿空。","mix":"第一次因大月氏安于新地、无意复仇而未成军事同盟；甘英出使大秦、班超经营西域都在东汉；张骞出使在西汉武帝时。","mcq":[{"q":"张骞第一次出使西域的目的地是","o":["乌孙","大宛","安息","大月氏"],"a":3,"w":"目的是联合大月氏夹击匈奴。"},{"q":"司马迁称张骞通西域为","o":["开边","凿空","拓土","通使"],"a":1,"w":"《史记·大宛列传》称“张骞凿空”。"}],"rel":[{"t":"西域","n":"出使的区域"},{"t":"大月氏","n":"第一次的目的地"},{"t":"乌孙","n":"第二次的目的地"},{"t":"大秦与甘英","n":"东汉的继续"},{"t":"汉武帝","n":"派遣者"}],"more":"张骞被封博望侯。\n《史记·大宛列传》：然张骞凿空，其后使者相望于道。","exam":[]},{"id":"a10-024","t":"大宛","cid":"10c","p":2,"kind":"地理","exam":[],"alias":[],"one":"中亚费尔干纳盆地，产汗血马；汉武帝遣李广利伐大宛得马。","ans":"中亚费尔干纳盆地，产汗血马；汉武帝遣李广利伐大宛得马。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-025","t":"大月氏","cid":"10c","p":2,"kind":"地理","exam":[],"alias":[],"one":"阿姆河流域，张骞第一次出使的目的地。","ans":"阿姆河流域，张骞第一次出使的目的地。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-026","t":"乌孙","cid":"10c","p":3,"kind":"地理","exam":[],"alias":[],"one":"伊犁河流域，张骞第二次出使的目的地；细君公主、解忧公主和亲。","ans":"伊犁河流域，张骞第二次出使的目的地；细君公主、解忧公主和亲。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-027","t":"安息","cid":"10c","p":1,"kind":"地理","alias":["帕提亚","帕提亚帝国"],"one":"汉代对伊朗高原帕提亚帝国的称呼，控制丝路中段。","ans":"安息是汉代对**伊朗高原上帕提亚帝国**的称呼，约**前247年建立，224年被萨珊王朝取代**，“安息”得名于创建者阿尔沙克名字的音译。它位居**丝绸之路中段**，垄断汉与罗马之间的丝绸贸易并从中获利。**张骞出使时派副使到达安息**，汉武帝也遣使前往，安息使者随后回访。东汉甘英出使大秦，途经安息，行至波斯湾而还。此后伊朗高原由萨珊波斯继承，安息与阿契美尼德波斯、萨珊波斯并称伊朗高原三大古代王朝。","pts":["伊朗高原的帕提亚帝国","约前247年立国，224年亡于萨珊","居丝路中段，汉与之互派使者"],"mem":"对应表一行记忆：安息=帕提亚=伊朗高原；身毒=印度；大夏=阿富汗北部；大月氏=阿姆河；乌孙=伊犁河；大宛=费尔干纳。顺序记波斯三代：阿契美尼德→安息→萨珊。","mix":"安息不等于阿契美尼德波斯，也不等于罗马（罗马是大秦）；安息之后是萨珊波斯。","mcq":[{"q":"汉代文献中的“安息”指","o":["罗马帝国","帕提亚帝国","贵霜帝国","埃及"],"a":1,"w":"安息即帕提亚帝国，在伊朗高原。"},{"q":"下列古国与今地对应正确的是","o":["安息：埃及","大秦：伊朗","身毒：印度","大夏：罗马"],"a":2,"w":"身毒即印度；大秦指罗马，安息在伊朗高原，大夏在阿富汗北部。"}],"rel":[{"t":"伊朗高原","n":"安息所在"},{"t":"身毒","n":"并列的西域对应"},{"t":"大秦与甘英","n":"甘英途经安息"},{"t":"波斯帝国","n":"伊朗高原更早的帝国"}],"exam":[]},{"id":"a10-028","t":"身毒","cid":"10c","p":1,"kind":"地理","alias":["天竺","贤豆"],"one":"古代对印度的称呼，后又译作天竺，玄奘定名“印度”。","ans":"身毒是**中国古代对印度的称呼**，也写作“天竺”“贤豆”，《史记·大宛列传》作**“身毒”**。张骞在大夏见到**蜀布、邛竹杖**，得知它们由身毒转运而来，推断从四川经云南、缅甸可通身毒，汉武帝为此派人探路，虽受阻于昆明夷，却促使汉朝经营西南。东汉《后汉书》称**天竺**，唐代玄奘在《大唐西域记》中定名为**“印度”**，沿用至今。佛教经天竺传入中国，两地往来由此加深。","pts":["古代中国对印度的称呼","张骞在大夏见蜀布、邛竹杖","名称演变：身毒、天竺、印度"],"mem":"名称演变三步：身毒（汉）→天竺（东汉到唐）→印度（玄奘定名）。证据链：大夏有蜀布、邛竹杖，说明有一条“蜀到身毒”的通道。","mix":"身毒在今印度，安息在今伊朗，大秦是罗马，大夏在阿富汗北部，选择题常把四者互换。","mcq":[{"q":"汉代典籍中的“身毒”指今天的","o":["伊朗","印度","埃及","土耳其"],"a":1,"w":"身毒即印度，后称天竺。"},{"q":"张骞在大夏见到、得知经身毒转运而来的物品是","o":["葡萄、苜蓿","琉璃、香料","蜀布、邛竹杖","丝绸、瓷器"],"a":2,"w":"蜀布、邛竹杖产自四川，说明蜀地与身毒有商路。"}],"rel":[{"t":"张骞通西域","n":"得知身毒"},{"t":"大夏","n":"见到蜀布的地方"},{"t":"玄奘","n":"定名“印度”"},{"t":"印度河文明","n":"古印度文明"}],"more":"玄奘《大唐西域记》：详夫天竺之称，异议纠纷，旧云身毒，或曰贤豆，今从正音，宜云印度。","exam":[]},{"id":"a10-029","t":"大夏","cid":"10c","p":3,"kind":"地理","exam":[],"alias":[],"one":"阿富汗北部（巴克特里亚），张骞在此见到邛竹杖、蜀布。","ans":"阿富汗北部（巴克特里亚），张骞在此见到邛竹杖、蜀布。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-030","t":"大秦与甘英","cid":"10c","p":2,"kind":"地理","exam":[],"alias":[],"one":"大秦指罗马帝国；97年东汉班超遣甘英出使大秦，到达波斯湾而还。","ans":"大秦指罗马帝国；97年东汉班超遣甘英出使大秦，到达波斯湾而还。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-031","t":"帕米尔高原（葱岭）","cid":"10c","p":1,"kind":"地理","alias":["帕米尔高原","葱岭","帕米尔"],"one":"新疆西南的高原，古称葱岭，“世界屋脊”，丝路必越之地。","ans":"帕米尔高原位于**中国新疆西南部**，跨**塔吉克斯坦、阿富汗、巴基斯坦**等国，古称**葱岭**，相传因山中多野葱而得名。它是**昆仑山、天山、喀喇昆仑山、兴都库什山的交会处**，平均海拔四千米以上，有**“世界屋脊”**之称，境内有慕士塔格峰、公格尔峰。高原是**丝绸之路必经的天险**，张骞、法显、玄奘等人都曾翻越，越过此地便进入中亚。","pts":["新疆西南，邻塔吉克斯坦、阿富汗、巴基斯坦","古称葱岭，世界屋脊","丝路必经天险"],"mem":"“葱”对应“岭”：古称葱岭，今称帕米尔。位置口诀（自编）：“东中国，西塔阿，南巴基”，高原夹在新疆、塔吉克斯坦、阿富汗、巴基斯坦之间。","mix":"帕米尔高原在新疆西南，与青藏高原、伊朗高原不同；塔克拉玛干沙漠在高原以东，丝路南北两道绕沙漠西行，在喀什一带会合后翻越葱岭。","mcq":[{"q":"古称“葱岭”的是","o":["天山","祁连山","帕米尔高原","昆仑山"],"a":2,"w":"帕米尔高原古称葱岭。"},{"q":"下列国家中，与帕米尔高原不相邻的是","o":["塔吉克斯坦","阿富汗","土库曼斯坦","巴基斯坦"],"a":2,"w":"帕米尔高原邻塔吉克斯坦、阿富汗、巴基斯坦，土库曼斯坦不接壤。"}],"rel":[{"t":"丝绸之路","n":"必经之地"},{"t":"塔克拉玛干沙漠","n":"丝路绕行的沙漠"},{"t":"法显《佛国记》","n":"法显越葱岭"},{"t":"玄奘","n":"玄奘越葱岭"},{"t":"帕米尔高原","n":"同一地理实体"}],"exam":[]},{"id":"a10-032","t":"塔克拉玛干沙漠","cid":"10c","p":2,"kind":"地理","exam":[],"alias":[],"one":"位于新疆塔里木盆地中部，中国最大沙漠，世界第二大流动沙漠。","ans":"位于新疆塔里木盆地中部，中国最大沙漠，世界第二大流动沙漠。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-033","t":"苏门答腊岛","cid":"10c","p":2,"kind":"地理","exam":[],"alias":[],"one":"属印度尼西亚，隔马六甲海峡与马来半岛相望。","ans":"属印度尼西亚，隔马六甲海峡与马来半岛相望。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-034","t":"海上丝绸之路","cid":"10c","p":2,"kind":"概念","exam":[],"alias":[],"one":"以泉州、广州、宁波等港口为起点，经南海、印度洋至西亚、东非；“泉州：宋元中国","ans":"以泉州、广州、宁波等港口为起点，经南海、印度洋至西亚、东非；“泉州：宋元中国的世界海洋商贸中心”2021年列入世界遗产。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-035","t":"伊本·白图泰","cid":"10c","p":3,"kind":"人物","exam":[],"alias":[],"one":"14世纪摩洛哥旅行家，到过中国泉州等地，口述《伊本·白图泰游记》。","ans":"14世纪摩洛哥旅行家，到过中国泉州等地，口述《伊本·白图泰游记》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-036","t":"撒马尔罕","cid":"10c","p":3,"kind":"地理","exam":[],"alias":[],"one":"今乌兹别克斯坦，丝路商贸中心，帖木儿帝国都城。","ans":"今乌兹别克斯坦，丝路商贸中心，帖木儿帝国都城。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-037","t":"楼兰","cid":"10c","p":3,"kind":"地理","exam":[],"alias":[],"one":"罗布泊西北的西域古国；王昌龄《从军行》“不破楼兰终不还”。","ans":"罗布泊西北的西域古国；王昌龄《从军行》“不破楼兰终不还”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-038","t":"476年西罗马帝国灭亡","cid":"10d","p":1,"kind":"事件","alias":["西罗马帝国灭亡","西罗马灭亡"],"one":"476年日耳曼将领奥多亚克废黜末代皇帝，通常作为中世纪开端。","ans":"476年西罗马帝国灭亡是**欧洲古代史与中世纪的分界事件**。**395年罗马帝国分为东西两部**，西部长期受日耳曼人迁入和内乱困扰。**476年日耳曼雇佣军首领奥多亚克废黜西罗马末代皇帝罗慕路斯·奥古斯都**，西罗马帝国灭亡，意大利先后落入东哥特等日耳曼王国之手。东罗马帝国（拜占庭）继续存在到1453年。这一事件通常被视为**奴隶制时代的结束与欧洲中世纪的开端**。","pts":["395年罗马帝国分为东西两部","476年奥多亚克废黜末代皇帝","中世纪开端，东罗马延续到1453年"],"mem":"“395分家，476亡西，1453亡东”，三个年份连成一条线。人物：奥多亚克（日耳曼雇佣军首领）与末代小皇帝罗慕路斯·奥古斯都，名字合起来像开国者罗慕路斯加奥古斯都，却成了末代。","mix":"西罗马476年亡，东罗马1453年亡；中世纪起点有476年之说，也有以其他事件为界的说法。","mcq":[{"q":"西罗马帝国末代皇帝被谁废黜","o":["阿拉里克","奥多亚克","阿提拉","查理曼"],"a":1,"w":"476年日耳曼雇佣军首领奥多亚克废黜罗慕路斯·奥古斯都。"},{"q":"东罗马帝国灭亡的年份是","o":["395年","476年","1204年","1453年"],"a":3,"w":"1453年君士坦丁堡被奥斯曼攻陷。"}],"rel":[{"t":"欧洲中世纪","n":"以此为开端"},{"t":"拜占庭帝国","n":"东部延续"},{"t":"罗马共和国与帝国","n":"此前的罗马"},{"t":"1453年","n":"东罗马灭亡之年"}],"exam":[]},{"id":"a10-039","t":"法兰克王国与《凡尔登条约》","cid":"10d","p":3,"kind":"事件","exam":[],"alias":[],"one":"481年克洛维建法兰克王国；756年“丕平献土”形成教皇国；843年《凡尔登","ans":"481年克洛维建法兰克王国；756年“丕平献土”形成教皇国；843年《凡尔登条约》三分查理曼帝国，奠定法、德、意雏形。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-040","t":"贞德","cid":"10d","p":2,"kind":"人物","exam":[],"alias":[],"one":"带领法军解奥尔良之围的农家少女，1431年被英国控制的宗教法庭以异端罪烧死，","ans":"带领法军解奥尔良之围的农家少女，1431年被英国控制的宗教法庭以异端罪烧死，1920年被封为圣徒。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-041","t":"英国议会的起源","cid":"10d","p":3,"kind":"制度","exam":[],"alias":[],"one":"1265年西蒙·德·孟福尔召集有市民代表参加的会议，1295年“模范议会”，","ans":"1265年西蒙·德·孟福尔召集有市民代表参加的会议，1295年“模范议会”，14世纪分为上下两院。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-042","t":"玫瑰战争","cid":"10d","p":3,"kind":"事件","exam":[],"alias":[],"one":"1455至1485年兰开斯特家族（红玫瑰）与约克家族（白玫瑰）争夺王位，以都","ans":"1455至1485年兰开斯特家族（红玫瑰）与约克家族（白玫瑰）争夺王位，以都铎王朝建立告终。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-043","t":"汉萨同盟","cid":"10d","p":3,"kind":"制度","exam":[],"alias":[],"one":"13至17世纪以吕贝克为首的北德意志城市商业同盟，控制波罗的海与北海贸易。","ans":"13至17世纪以吕贝克为首的北德意志城市商业同盟，控制波罗的海与北海贸易。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-044","t":"阿拉伯数字","cid":"10d","p":2,"kind":"常识","exam":[],"alias":[],"one":"起源于印度，经阿拉伯人传入欧洲，故称阿拉伯数字；零的符号也源于印度。","ans":"起源于印度，经阿拉伯人传入欧洲，故称阿拉伯数字；零的符号也源于印度。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-045","t":"大化改新","cid":"10d","p":2,"kind":"事件","exam":[],"alias":[],"one":"646年日本孝德天皇仿唐制改革，废除贵族私有土地和部民，建立中央集权的天皇制","ans":"646年日本孝德天皇仿唐制改革，废除贵族私有土地和部民，建立中央集权的天皇制国家。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-046","t":"基辅罗斯","cid":"10d","p":3,"kind":"概念","exam":[],"alias":[],"one":"9世纪建立，988年弗拉基米尔大公接受东正教，是俄罗斯、乌克兰、白俄罗斯的共","ans":"9世纪建立，988年弗拉基米尔大公接受东正教，是俄罗斯、乌克兰、白俄罗斯的共同源头。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-047","t":"卡诺莎之行","cid":"10d","p":3,"kind":"事件","exam":[],"alias":[],"one":"1077年神圣罗马帝国皇帝亨利四世在卡诺莎城堡雪中向教皇格里高利七世悔罪，喻","ans":"1077年神圣罗马帝国皇帝亨利四世在卡诺莎城堡雪中向教皇格里高利七世悔罪，喻屈辱求和。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-048","t":"宗教裁判所","cid":"10d","p":3,"kind":"制度","exam":[],"alias":[],"one":"13世纪起天主教审判“异端”的机构；布鲁诺1600年被烧死，伽利略1633年","ans":"13世纪起天主教审判“异端”的机构；布鲁诺1600年被烧死，伽利略1633年受审。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-049","t":"美第奇家族与佛罗伦萨","cid":"10e","p":2,"kind":"常识","exam":[],"alias":[],"one":"佛罗伦萨银行家族，资助达·芬奇、米开朗基罗等艺术家；佛罗伦萨是文艺复兴的发源","ans":"佛罗伦萨银行家族，资助达·芬奇、米开朗基罗等艺术家；佛罗伦萨是文艺复兴的发源地。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-050","t":"马基雅维利《君主论》","cid":"10e","p":2,"kind":"作品","exam":[],"alias":[],"one":"1513年写成，主张君主为达目的可以不择手段，使政治与道德分离，“马基雅维利","ans":"1513年写成，主张君主为达目的可以不择手段，使政治与道德分离，“马基雅维利主义”由此而来。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-051","t":"托马斯·莫尔《乌托邦》","cid":"10e","p":2,"kind":"作品","exam":[],"alias":[],"one":"1516年出版，描绘财产公有的理想社会；“乌托邦”这一音义兼顾的译名一般认为","ans":"1516年出版，描绘财产公有的理想社会；“乌托邦”这一音义兼顾的译名一般认为出自严复《天演论》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-052","t":"马丁·路德与《九十五条论纲》","cid":"10e","p":1,"kind":"人物","alias":["马丁·路德","九十五条论纲","路德"],"one":"1517年路德张贴《九十五条论纲》，反对赎罪券，宗教改革开端。","ans":"马丁·路德（1483—1546）是**德国神学家，宗教改革的发起者**。**1517年10月31日**他在**维滕堡**教堂门前张贴《九十五条论纲》，抨击教廷**出售赎罪券**，宗教改革由此开端。他主张**“因信称义”**，认为人凭信仰得救，《圣经》是信仰的最高权威。他把《圣经》**译成德文**，对**统一和规范现代德语书面语**影响深远。路德创立的新教称路德宗，印刷术使他的主张迅速传播，推动欧洲出现新教与天主教并立的局面。","pts":["1517年维滕堡张贴《九十五条论纲》","反对赎罪券，主张因信称义","译《圣经》为德文，创立路德宗"],"mem":"数字：1517，九十五条。记忆画面：一个人拿着锤子，把长长一页纸钉在维滕堡教堂门上。三件事：反赎罪券，因信称义，德文《圣经》。印刷术是放大器。","mix":"路德是德国人，加尔文是法国人在瑞士改革；亨利八世的英国国教改革是另一条线；路德反对的是赎罪券，不是否定基督教。","mcq":[{"q":"1517年发表《九十五条论纲》的是","o":["加尔文","马丁·路德","伊拉斯谟","茨温利"],"a":1,"w":"路德于1517年在维滕堡发表论纲，宗教改革开始。"},{"q":"路德《九十五条论纲》主要抨击的是","o":["教会出售赎罪券","君主专制","农奴制","圣经翻译"],"a":0,"w":"他反对教廷出售赎罪券。"}],"rel":[{"t":"宗教改革","n":"所属运动"},{"t":"加尔文","n":"另一位改革家"},{"t":"马丁·路德与德语《圣经》","n":"翻译成就"},{"t":"古登堡印刷术","n":"传播工具"},{"t":"《钦定本圣经》","n":"另一部名译本"}],"more":"1521年沃尔姆斯会议上路德拒绝收回主张；1534年德文《圣经》全译本出版。","exam":[]},{"id":"a10-053","t":"加尔文","cid":"10e","p":2,"kind":"人物","exam":[],"alias":[],"one":"日内瓦宗教改革领袖，“先定论”；加尔文宗包括长老会、清教徒、胡格诺派；韦伯《","ans":"日内瓦宗教改革领袖，“先定论”；加尔文宗包括长老会、清教徒、胡格诺派；韦伯《新教伦理与资本主义精神》论其影响。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-054","t":"新教三大宗派","cid":"10e","p":2,"kind":"合称","exam":[],"alias":[],"one":"路德宗（信义宗）、加尔文宗（归正宗）、英国国教（圣公会，1534年亨利八世《","ans":"路德宗（信义宗）、加尔文宗（归正宗）、英国国教（圣公会，1534年亨利八世《至尊法案》确立）。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-055","t":"古登堡印刷术","cid":"10e","p":2,"kind":"事件","exam":[],"alias":[],"one":"约1450年德国古登堡用金属活字印刷，印行《古登堡圣经》，推动宗教改革和知识","ans":"约1450年德国古登堡用金属活字印刷，印行《古登堡圣经》，推动宗教改革和知识传播。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-056","t":"哥伦布","cid":"10e","p":1,"kind":"人物","alias":["克里斯托弗·哥伦布","哥伦布航行"],"one":"意大利航海家，1492年受西班牙资助到达美洲，误以为是印度。","ans":"哥伦布（1451—1506）是**意大利热那亚人，航海家**。他相信地圆说，向西航行可到东方，获**西班牙伊莎贝拉女王**资助，**1492年8月率船队出发，10月到达美洲巴哈马群岛**，一生先后四次远航。他始终以为到了亚洲，称当地人为**“印第安人”**，所到岛屿被称为“西印度群岛”。哥伦布的航行**开辟了欧洲与美洲的联系**，拉开了殖民扩张的序幕，也使美洲原住民遭受屠杀和奴役，哥伦布交换也由此开始。","pts":["意大利热那亚人，西班牙王室资助","1492年到达美洲，误以为是印度","开辟欧美联系，引发殖民扩张"],"mem":"“1492，哥伦布，西班牙”三个词连成一句。误会链：以为到了印度，所以叫“印第安人”“西印度群岛”。美洲得名并不来自他，而来自亚美利哥·韦斯普奇。","mix":"哥伦布是意大利人，但为西班牙效力；他以为到了印度，所以与达·伽马真正到达印度相区分；美洲命名来自亚美利哥，不来自哥伦布。","mcq":[{"q":"哥伦布1492年的航行得到哪国王室资助","o":["葡萄牙","英国","西班牙","法国"],"a":2,"w":"西班牙的伊莎贝拉女王资助了此次航行。"},{"q":"哥伦布称美洲当地人为“印第安人”，是因为他以为自己到了","o":["印度","中国","非洲","澳大利亚"],"a":0,"w":"他始终认为到达了亚洲的印度一带。"}],"rel":[{"t":"地理大发现","n":"所属事件"},{"t":"达·伽马","n":"真正到达印度"},{"t":"麦哲伦环球航行","n":"后继的航行"},{"t":"美洲三大古文明","n":"受冲击的美洲文明"},{"t":"郑和下西洋","n":"东方的远航对照"}],"more":"1492年10月12日登陆巴哈马群岛的圣萨尔瓦多岛。","exam":[]},{"id":"a10-057","t":"达·伽马","cid":"10e","p":2,"kind":"人物","exam":[],"alias":[],"one":"葡萄牙人，1497至1498年绕过好望角抵达印度卡利卡特，开辟欧洲直达印度的","ans":"葡萄牙人，1497至1498年绕过好望角抵达印度卡利卡特，开辟欧洲直达印度的航路。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-058","t":"麦哲伦环球航行","cid":"10e","p":1,"kind":"事件","alias":["麦哲伦","麦哲伦船队"],"one":"1519至1522年麦哲伦船队完成人类首次环球航行，证明地球是球体。","ans":"麦哲伦环球航行是**1519年至1522年葡萄牙人麦哲伦率领西班牙船队完成的人类首次环球航行**。船队**1519年出发，穿过后来以他命名的麦哲伦海峡，进入并命名太平洋**；**1521年麦哲伦在菲律宾死于与当地人的冲突**，余部在埃尔卡诺率领下继续西行，**1522年返回西班牙**，出发时约二百余人，最终仅十余人生还。此次航行**用事实证明地球是球体**，证实了各大洋相互贯通，推动了世界贸易和殖民扩张。","pts":["1519—1522，麦哲伦船队，西班牙资助","穿过麦哲伦海峡，命名太平洋，死于菲律宾","首次环球，证明地球是球体"],"mem":"“1519出发，1521麦死，1522回港”。画面：船队从大西洋进南美，穿海峡后风平浪静，因此叫“太平洋”，之后在菲律宾失去船长，剩下的人继续向西跑完一圈。","mix":"麦哲伦是葡萄牙人，为西班牙服务，本人没能完成环球，完成者是埃尔卡诺；哥伦布是向西到美洲，达·伽马是向东到印度。","mcq":[{"q":"人类首次环球航行由谁的船队完成","o":["哥伦布","麦哲伦","达·伽马","迪亚士"],"a":1,"w":"麦哲伦船队1519—1522年完成，麦哲伦本人死于菲律宾。"},{"q":"麦哲伦船队穿过海峡后进入并命名的大洋是","o":["大西洋","印度洋","北冰洋","太平洋"],"a":3,"w":"因航行时风平浪静，命名为“太平洋”。"}],"rel":[{"t":"地理大发现","n":"所属事件"},{"t":"哥伦布","n":"向西到美洲"},{"t":"达·伽马","n":"向东到印度"},{"t":"迪亚士","n":"到达好望角"},{"t":"七大洲四大洋","n":"太平洋命名"}],"more":"1520年10月穿过麦哲伦海峡，1521年4月死于菲律宾麦克坦岛。","exam":[]},{"id":"a10-059","t":"迪亚士","cid":"10e","p":3,"kind":"人物","exam":[],"alias":[],"one":"葡萄牙人，1487至1488年到达非洲南端好望角。","ans":"葡萄牙人，1487至1488年到达非洲南端好望角。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-060","t":"三角贸易","cid":"10e","p":2,"kind":"事件","exam":[],"alias":[],"one":"16至19世纪在欧洲、非洲、美洲之间进行：欧洲商品换非洲奴隶，运往美洲换蔗糖","ans":"16至19世纪在欧洲、非洲、美洲之间进行：欧洲商品换非洲奴隶，运往美洲换蔗糖、棉花等运回欧洲。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-061","t":"哥白尼日心说","cid":"10e","p":1,"kind":"事件","alias":["日心说","哥白尼","《天体运行论》","哥白尼式革命"],"one":"波兰哥白尼1543年发表《天体运行论》，提出地球绕太阳转，否定托勒密地心说。","ans":"日心说是**波兰天文学家哥白尼**提出的宇宙学说，主张太阳位于宇宙中心，地球和其他行星绕太阳运行，地球每天自转一周。它出现在**文艺复兴时期、近代科学革命的开端**，直接否定了**托勒密的地心说**。哥白尼的代表作**《天体运行论》**于**1543年**出版。此后布鲁诺因宣传日心说等主张被教会处死，开普勒、伽利略用计算和望远镜观测提供证据，牛顿最终完成经典力学体系。日心说动摇了教会的宇宙观，被恩格斯称为**自然科学向神学宣告独立的标志**，“哥白尼式革命”也成为观念根本转变的常用比喻。","pts":["波兰哥白尼，1543年《天体运行论》","太阳为中心，否定托勒密地心说","布鲁诺、开普勒、伽利略、牛顿接续"],"mem":"年份挂钩：1543年哥白尼发表日心说，同年维萨里出版《人体构造》，科学革命以这一年起步。接力口诀（自编）“哥布开伽牛”：哥白尼、布鲁诺、开普勒、伽利略、牛顿，按时间顺序排好。画面：地球从舞台中心退到观众席，变成绕着太阳跑的演员。","mix":"托勒密地心说是被否定的一方；布鲁诺被教会烧死（1600年），伽利略被宗教裁判所逼迫认错，两人的结局不要互换；哥白尼是波兰人。","mcq":[{"q":"提出日心说，著有《天体运行论》的科学家是","o":["伽利略","哥白尼","牛顿","开普勒"],"a":1,"w":"哥白尼，波兰天文学家，1543年出版《天体运行论》。"},{"q":"《天体运行论》出版于","o":["1453年","1517年","1543年","1687年"],"a":2,"w":"1543年；1453年是君士坦丁堡陷落，1517年是宗教改革，1687年是牛顿《原理》。"}],"rel":[{"t":"伽利略","n":"用望远镜支持日心说"},{"t":"牛顿","n":"科学革命的完成者"},{"t":"文艺复兴","n":"同一时代背景"},{"t":"地理大发现","n":"同期拓展人类视野"}],"more":"1543年：《天体运行论》出版。\n后继：布鲁诺（1600年被处死）、开普勒（行星运动三定律）、伽利略（望远镜观测）、牛顿（万有引力）。\n评价：恩格斯称哥白尼的著作是自然科学的独立宣言。","exam":[]},{"id":"a10-062","t":"伽利略","cid":"10e","p":2,"kind":"人物","exam":[],"alias":[],"one":"意大利，用望远镜观测天体支持日心说，近代实验科学奠基人，1633年受宗教裁判","ans":"意大利，用望远镜观测天体支持日心说，近代实验科学奠基人，1633年受宗教裁判所审判。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-063","t":"布鲁诺","cid":"10e","p":3,"kind":"人物","exam":[],"alias":[],"one":"宣传日心说和宇宙无限论，1600年在罗马鲜花广场被烧死。","ans":"宣传日心说和宇宙无限论，1600年在罗马鲜花广场被烧死。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-064","t":"牛顿","cid":"10e","p":1,"kind":"人物","alias":["艾萨克·牛顿","牛顿爵士"],"one":"英国科学家，1687年《自然哲学的数学原理》提出万有引力与运动三定律。","ans":"艾萨克·牛顿（1643—1727）是**英国物理学家、数学家**，近代科学革命的集大成者。他在**1687年**出版**《自然哲学的数学原理》**，提出**万有引力定律和运动三大定律**，建立起经典力学体系，用同一套规律解释天上的行星和地上的落体。他在数学上与**莱布尼茨各自独立发明微积分**，在光学上通过三棱镜实验研究色散，并制作了反射式望远镜，后来长期担任英国皇家学会会长。牛顿的理论成为**启蒙运动崇尚理性的科学榜样**，使“自然受规律支配”的观念深入人心。","pts":["英国，1687年《自然哲学的数学原理》","万有引力定律与运动三定律","与莱布尼茨各自发明微积分"],"mem":"画面：苹果落地的传说把地上的苹果和天上的月亮连在同一个引力里。时间轴：1543年哥白尼开门，1687年牛顿收官，两本书相隔144年，科学革命就在这中间。","mix":"落体定律、惯性思想和望远镜观测属于伽利略；相对论修正牛顿力学的是爱因斯坦；莱布尼茨是德国人，与牛顿有微积分优先权之争。","mcq":[{"q":"1687年出版《自然哲学的数学原理》的科学家是","o":["伽利略","开普勒","爱因斯坦","牛顿"],"a":3,"w":"牛顿在该书中提出万有引力定律和运动三定律。"},{"q":"与牛顿各自独立发明微积分的是","o":["笛卡尔","莱布尼茨","帕斯卡","培根"],"a":1,"w":"德国数学家莱布尼茨，二人有优先权之争。"}],"rel":[{"t":"哥白尼日心说","n":"科学革命的起点"},{"t":"伽利略","n":"前辈，铺路者"},{"t":"牛顿与经典力学","n":"理论内容展开"},{"t":"启蒙运动","n":"科学为其树立榜样"}],"more":"主要成就：万有引力定律、运动三定律、微积分、光的色散、反射望远镜。\n1687年：《自然哲学的数学原理》出版。","exam":[]},{"id":"a10-065","t":"尼德兰革命","cid":"10e","p":2,"kind":"事件","exam":[],"alias":[],"one":"16世纪后期尼德兰反抗西班牙统治，1581年北方七省宣布独立，建立联省共和国","ans":"16世纪后期尼德兰反抗西班牙统治，1581年北方七省宣布独立，建立联省共和国（荷兰）；17世纪荷兰被称为“海上马车夫”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-066","t":"英国击败西班牙无敌舰队","cid":"10e","p":3,"kind":"事件","exam":[],"alias":[],"one":"1588年，英国开始取代西班牙成为海上强国。","ans":"1588年，英国开始取代西班牙成为海上强国。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-067","t":"三权分立","cid":"10f","p":1,"kind":"制度","alias":["分权制衡","三权分立与制衡"],"one":"立法、行政、司法三权分立并相互制衡，孟德斯鸠《论法的精神》提出。","ans":"三权分立是**把国家权力分为立法、行政、司法三部分，由不同机关行使并相互制衡**的政治原则。**法国启蒙思想家孟德斯鸠**在**《论法的精神》（1748年）**中系统提出，他继承了英国洛克的分权思想。其要义是以权力制约权力，防止专制。**美国1787年宪法**最早全面实践：**国会掌握立法权，总统掌握行政权，联邦法院掌握司法权**，国会又分设参议院和众议院。三权分立成为近代资产阶级国家政体的重要原则。中国不采用这一模式，实行**人民代表大会制度**。","pts":["立法、行政、司法分立制衡","孟德斯鸠《论法的精神》1748","美国1787年宪法最早实践"],"mem":"“立行司”三个字对应美国“国总法”：国会立法，总统行政，法院司法。“孟”对“论法”：孟德斯鸠写《论法的精神》。","mix":"洛克主张立法权与行政权分立，孟德斯鸠才发展为三权；卢梭讲人民主权，不讲分权。美国是总统制，英国是议会内阁制，实践形式各不相同。","mcq":[{"q":"最早系统提出三权分立学说的是","o":["卢梭","孟德斯鸠","洛克","伏尔泰"],"a":1,"w":"孟德斯鸠，《论法的精神》（1748）。"},{"q":"按三权分立原则，美国联邦政府中行使司法权的是","o":["国会","总统","联邦最高法院等联邦法院","参议院"],"a":2,"w":"国会立法，总统行政，法院司法。"}],"rel":[{"t":"孟德斯鸠","n":"学说提出者"},{"t":"1787年美国宪法","n":"最早全面实践"},{"t":"参议院与众议院","n":"美国立法机构"},{"t":"人民代表大会制度","n":"中国的根本政治制度，作对照"}],"more":"孟德斯鸠《论法的精神》（1748）。\n美国：国会（立法）、总统（行政）、联邦法院（司法）。\n交大2017年名解考过参议院与众议院。","exam":[]},{"id":"a10-068","t":"孟德斯鸠","cid":"10f","p":2,"kind":"人物","exam":[],"alias":[],"one":"法国启蒙思想家，《论法的精神》《波斯人信札》；严复译《论法的精神》为《法意》","ans":"法国启蒙思想家，《论法的精神》《波斯人信札》；严复译《论法的精神》为《法意》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-069","t":"社会契约论","cid":"10f","p":1,"kind":"概念","alias":["社会契约","《社会契约论》","人民主权"],"one":"国家源于人们让渡权利订立的契约；卢梭《社会契约论》提出人民主权。","ans":"社会契约论是**主张国家和政府源于人们之间的约定**的政治理论，是启蒙思想的核心概念。**霍布斯**在《利维坦》（1651年）中认为人们为摆脱“人人相互为敌”的自然状态而让渡权利给君主；**洛克**主张政府为保护生命、自由和财产而设，违背民意时人民有权反抗；**卢梭**在**《社会契约论》（1762年）**中提出**人民主权**，开篇写道“人生而自由，却无往不在枷锁之中”。社会契约论否定君权神授，为**美国《独立宣言》和法国《人权宣言》**提供了理论基础。","pts":["国家源于人们订立的契约","霍布斯、洛克、卢梭各有阐述","卢梭1762年提出人民主权"],"mem":"三人三态度：霍布斯要强势君主（《利维坦》），洛克要有限政府（可反抗），卢梭要人民主权（《社会契约论》）。金句分两半记：前半“人生而自由”，后半“无往不在枷锁之中”。","mix":"“人人生而平等”出自《独立宣言》，“人生而自由，权利平等”出自《人权宣言》，“人生而自由，却无往不在枷锁之中”才是卢梭。","mcq":[{"q":"“人生而自由，却无往不在枷锁之中”出自","o":["孟德斯鸠《论法的精神》","洛克《政府论》","霍布斯《利维坦》","卢梭《社会契约论》"],"a":3,"w":"卢梭《社会契约论》（1762）开篇。"},{"q":"主张通过契约建立强大君主权力、结束“自然状态”的思想家是","o":["霍布斯","洛克","卢梭","伏尔泰"],"a":0,"w":"霍布斯，《利维坦》（1651）。"}],"rel":[{"t":"卢梭","n":"《社会契约论》作者"},{"t":"洛克","n":"主张有限政府"},{"t":"霍布斯《利维坦》","n":"契约论的专制版本"},{"t":"天赋人权","n":"同一思想体系"}],"more":"霍布斯《利维坦》（1651）；洛克《政府论》；卢梭《社会契约论》（1762）。\n名句：人生而自由，却无往不在枷锁之中。｜卢梭《社会契约论》","exam":[]},{"id":"a10-070","t":"天赋人权","cid":"10f","p":2,"kind":"概念","exam":[],"alias":[],"one":"洛克提出生命、自由、财产是与生俱来、不可剥夺的权利；写入美国《独立宣言》和法","ans":"洛克提出生命、自由、财产是与生俱来、不可剥夺的权利；写入美国《独立宣言》和法国《人权宣言》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-071","t":"开明专制","cid":"10f","p":3,"kind":"制度","exam":[],"alias":[],"one":"18世纪普鲁士腓特烈二世、俄国叶卡捷琳娜二世、奥地利约瑟夫二世借用启蒙口号加","ans":"18世纪普鲁士腓特烈二世、俄国叶卡捷琳娜二世、奥地利约瑟夫二世借用启蒙口号加强君主统治。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-072","t":"亚当·斯密与《国富论》","cid":"10f","p":1,"kind":"作品","alias":["亚当·斯密","《原富》","看不见的手"],"one":"苏格兰经济学家斯密1776年出版《国富论》，提出分工与“看不见的手”。","ans":"亚当·斯密（1723—1790）是**英国苏格兰经济学家**，**古典政治经济学的奠基人**。他于**1776年3月**出版**《国富论》**（全称《国民财富的性质和原因的研究》），被视为现代经济学的开山之作。书中以制针业为例论述**劳动分工**能大幅提高生产率，提出个人追求私利会像**“看不见的手”**一样促进社会利益，主张**自由放任**、限制政府干预，批判重商主义。他另著有《道德情操论》。**严复**于1902年将《国富论》译为**《原富》**，属“严译名著八种”。该书与《独立宣言》同年出版，2026年迎来250周年。","pts":["苏格兰经济学家，1776年《国富论》","劳动分工、看不见的手、自由放任","严复译为《原富》（1902）"],"mem":"“一七七六，两件大事”：3月《国富论》，7月《独立宣言》。三个关键词“分、手、放”：分工、看不见的手、自由放任。严译八种里，《国富论》对应《原富》，《进化论与伦理学》对应《天演论》。","mix":"凯恩斯主张国家干预，与斯密的自由放任对立；《资本论》是马克思所作；《原富》是严复的译名，不是原著书名。","mcq":[{"q":"亚当·斯密用来说明市场自发调节作用的比喻是","o":["有形之手","守夜人","看不见的手","后发优势"],"a":2,"w":"“看不见的手”出自《国富论》。"},{"q":"严复将《国富论》译为","o":["《天演论》","《原富》","《法意》","《群学肄言》"],"a":1,"w":"《原富》（1902），《天演论》译自赫胥黎，《法意》译自孟德斯鸠。"}],"rel":[{"t":"严译名著八种","n":"《原富》位列其中"},{"t":"凯恩斯主义","n":"主张国家干预，对举"},{"t":"严复","n":"《原富》译者"},{"t":"《独立宣言》","n":"同为1776年大事"}],"more":"1776年3月9日：《国富论》出版。\n1759年：《道德情操论》。\n1902年：严复译《原富》。","exam":[]},{"id":"a10-073","t":"光荣革命","cid":"10f","p":1,"kind":"事件","alias":["1688年革命","不流血革命"],"one":"1688年英国议会迎立威廉与玛丽，赶走詹姆斯二世，未经流血完成政变。","ans":"光荣革命是**1688年英国议会发动的政变**，因未经流血而得名，是**英国资产阶级革命的收官之作**。**国王詹姆斯二世**推行天主教化和专制统治，引起辉格党与托利党共同不满，**议会邀请荷兰执政奥兰治的威廉及其妻玛丽**（詹姆斯二世的女儿）入主英国，詹姆斯二世逃往法国。**1689年议会通过《权利法案》**，确立议会高于王权，**英国由此走上君主立宪道路**。此后国王统而不治逐渐成为英国的政治惯例，为美、法两国的革命提供了先例。","pts":["1688年，议会迎威廉与玛丽","詹姆斯二世逃往法国，不流血","1689《权利法案》，君主立宪"],"mem":"“六八八，不流血”：1688年议会请人换国王。因果链：国王专制，议会请外援，国王逃跑，议会立规矩（1689年《权利法案》）。","mix":"光荣革命是1688年的和平政变；1640—1649年的英国内战、处死查理一世和克伦威尔的共和国属于此前阶段，不要混同。1688年是政变，1689年才是《权利法案》。","mcq":[{"q":"英国光荣革命发生于","o":["1649年","1689年","1688年","1776年"],"a":2,"w":"1688年；1689年是《权利法案》。"},{"q":"光荣革命后被议会迎立为英国君主的是","o":["威廉与玛丽","查理二世","詹姆斯二世","克伦威尔"],"a":0,"w":"荷兰执政威廉与妻子玛丽；詹姆斯二世被赶走。"}],"rel":[{"t":"《权利法案》（英国）","n":"革命的成果文献"},{"t":"君主立宪制","n":"由此确立"},{"t":"克伦威尔","n":"此前的共和国阶段"},{"t":"《大宪章》","n":"限制王权的更早文献"}],"more":"1688年：光荣革命。\n1689年：《权利法案》。\n此前：1649年处死查理一世，克伦威尔护国。","exam":[]},{"id":"a10-074","t":"《权利法案》（英国）","cid":"10f","p":1,"kind":"作品","alias":["英国《权利法案》","1689年权利法案"],"one":"1689年英国议会通过，限制王权、确立议会主权，奠定君主立宪制。","ans":"《权利法案》是**1689年英国议会通过的宪法性文件**，在**光荣革命**后由威廉与玛丽接受而生效。法案规定：国王**未经议会同意不得停止法律、征税和维持常备军**，议会选举自由，议员在议会内享有言论自由，公民有请愿权。它从法律上确立了**议会高于王权**，标志着**英国君主立宪制的确立**，与1215年的《大宪章》一起成为英国不成文宪法的重要组成部分。它对美国1791年增补的《权利法案》也有借鉴。","pts":["1689年英国议会通过","限制王权，征税与军队须经议会同意","奠定君主立宪制"],"mem":"“人换规矩”：1688年光荣革命换了国王，1689年《权利法案》立了规矩。年份对照：英国1689，美国1776，法国1789，英国比法国早整整一百年。","mix":"英国《权利法案》（1689）限制王权；美国《权利法案》（1791）是联邦宪法前十条修正案，保障公民权利；《大宪章》是1215年。","mcq":[{"q":"确立英国君主立宪制的文件是","o":["《大宪章》","《人权宣言》","《独立宣言》","《权利法案》"],"a":3,"w":"1689年《权利法案》确立议会主权。"},{"q":"英国《权利法案》通过于","o":["1215年","1649年","1689年","1776年"],"a":2,"w":"光荣革命次年（1689年）通过。"}],"rel":[{"t":"光荣革命","n":"产生背景"},{"t":"《大宪章》","n":"限制王权的先声"},{"t":"君主立宪制","n":"由其确立"},{"t":"1787年美国宪法","n":"美国的宪政文献，对照"}],"more":"1215年：《大宪章》。\n1689年：英国《权利法案》。\n1791年：美国宪法前十条修正案，亦称《权利法案》。","exam":[]},{"id":"a10-075","t":"君主立宪制","cid":"10f","p":2,"kind":"制度","exam":[],"alias":[],"one":"君主为国家象征，议会掌握立法权，内阁对议会负责；18世纪英国逐渐形成责任内阁","ans":"君主为国家象征，议会掌握立法权，内阁对议会负责；18世纪英国逐渐形成责任内阁制。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-076","t":"《独立宣言》","cid":"10f","p":1,"kind":"作品","one":"1776年7月4日大陆会议通过，杰斐逊起草，宣布北美13个殖民地独立。","ans":"《独立宣言》是**1776年7月4日北美大陆会议通过的政治文件**，由**托马斯·杰斐逊**主要起草，宣布北美**十三个殖民地脱离英国独立**。它受洛克自然权利学说影响，提出**“人人生而平等”**，人们拥有**生命权、自由权和追求幸福的权利**，政府的权力来自被统治者的同意，政府破坏这些权利时人民有权推翻它。宣言还列举了英王乔治三世的种种暴政。马克思称其为**“第一个人权宣言”**。它标志着美国诞生，7月4日成为美国独立日，其思想也影响了法国《人权宣言》。","pts":["1776.7.4大陆会议通过，杰斐逊起草","人人生而平等，生命、自由、追求幸福","马克思称“第一个人权宣言”"],"mem":"三个“一”：一个日子（7月4日），一位执笔人（杰斐逊），一句名言（人人生而平等）。三项权利记“命、自、福”：生命、自由、追求幸福。","mix":"《独立宣言》（1776）宣告独立，1787年宪法才建立政府体制；法国《人权宣言》是1789年。洛克的表述是“生命、自由和财产”，宣言把“财产”换成了“追求幸福”。","mcq":[{"q":"被马克思称为“第一个人权宣言”的文件是","o":["《独立宣言》","《人权宣言》","《权利法案》（英国）","《大宪章》"],"a":0,"w":"指美国1776年《独立宣言》。"},{"q":"《独立宣言》的主要起草人是","o":["华盛顿","富兰克林","汉密尔顿","杰斐逊"],"a":3,"w":"托马斯·杰斐逊，后来成为美国第三任总统。"}],"rel":[{"t":"美国独立战争","n":"宣言发表于战争期间"},{"t":"杰斐逊","n":"主要起草人"},{"t":"《人权宣言》","n":"法国的同类文献"},{"t":"天赋人权","n":"宣言的思想基础"}],"more":"名句：人人生而平等，他们都从造物主那里被赋予了某些不可转让的权利，其中包括生命权、自由权和追求幸福的权利。｜《独立宣言》\n2026年为通过250周年。","exam":[]},{"id":"a10-077","t":"1787年美国宪法","cid":"10f","p":1,"kind":"作品","alias":["美国联邦宪法","费城制宪会议"],"one":"1787年费城制宪会议制定，近代第一部成文宪法，确立联邦制、共和制与三权分立。","ans":"1787年美国宪法是**1787年费城制宪会议制定的联邦宪法**，1789年生效，是**近代世界第一部成文宪法**。会议由华盛顿主持，大州与小州代表在国会两院的构成上达成妥协。宪法确立**联邦制、共和制和三权分立**：**国会行使立法权，总统行使行政权，联邦法院行使司法权**，国会分设参议院和众议院。**1791年增补前十条修正案**，即美国《权利法案》，保障言论、宗教、集会等公民权利。该宪法沿用至今，是现行成文宪法中施行最久的一部。","pts":["1787年费城制宪会议，近代第一部成文宪法","联邦制、共和制、三权分立","1791年前十条修正案即《权利法案》"],"mem":"“八七立宪，国总法”：1787年立宪，国会、总统、法院三权。年份串线：76宣言、83承认、87宪法、91修正案。“十条权利”指1791年增补的前10条修正案。","mix":"《独立宣言》（1776）宣告独立，宪法（1787）建立政府；美国《权利法案》（1791）指宪法前十条修正案，与英国1689年的《权利法案》不是同一份文件。","mcq":[{"q":"被称为近代第一部成文宪法的是","o":["1787年美国宪法","1791年法国宪法","1689年《权利法案》","1215年《大宪章》"],"a":0,"w":"1787年美国宪法，1789年生效。"},{"q":"美国宪法前十条修正案（《权利法案》）增补于","o":["1776年","1783年","1789年","1791年"],"a":3,"w":"1791年。"}],"rel":[{"t":"三权分立","n":"宪法的核心原则"},{"t":"参议院与众议院","n":"宪法设置的两院"},{"t":"华盛顿","n":"主持制宪会议并任首任总统"},{"t":"《权利法案》（英国）","n":"同名而不同的英国文献"}],"more":"1787年：费城制宪会议。\n1789年：宪法生效，华盛顿就任首任总统。\n1791年：前十条修正案。","exam":[]},{"id":"a10-078","t":"华盛顿","cid":"10f","p":2,"kind":"人物","exam":[],"alias":[],"one":"大陆军总司令，美国第一任总统（1789至1797年），连任两届后拒绝第三任。","ans":"大陆军总司令，美国第一任总统（1789至1797年），连任两届后拒绝第三任。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-079","t":"杰斐逊","cid":"10f","p":3,"kind":"人物","exam":[],"alias":[],"one":"美国第三任总统，1803年路易斯安那购地。","ans":"美国第三任总统，1803年路易斯安那购地。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-080","t":"来克星顿枪声与约克镇战役","cid":"10f","p":3,"kind":"事件","exam":[],"alias":[],"one":"1775年4月来克星顿枪声打响独立战争；1781年约克镇战役决定胜局；178","ans":"1775年4月来克星顿枪声打响独立战争；1781年约克镇战役决定胜局；1783年《巴黎和约》英国承认美国独立。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-081","t":"攻占巴士底狱","cid":"10f","p":2,"kind":"事件","exam":[],"alias":[],"one":"1789年7月14日，法国大革命开始的标志，7月14日为法国国庆日。","ans":"1789年7月14日，法国大革命开始的标志，7月14日为法国国庆日。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-082","t":"《人权宣言》","cid":"10f","p":1,"kind":"作品","alias":["《人权和公民权宣言》","法国人权宣言"],"one":"1789年法国制宪议会通过，宣布人生而自由平等、主权在民。","ans":"《人权宣言》全称**《人权和公民权宣言》**，是**1789年8月法国制宪议会通过的纲领性文献**，产生于法国大革命爆发之后。宣言宣布**“在权利方面，人们生来并且始终是自由平等的”**，自由、财产、安全和反抗压迫是**不可剥夺的自然权利**，**主权属于国民**，法律面前人人平等，**财产神圣不可侵犯**。它体现了卢梭、孟德斯鸠等人的启蒙思想，是废除封建等级特权的政治宣言，后来成为1791年宪法的序言。它与英国《权利法案》、美国《独立宣言》并列为英美法三国的革命文献。","pts":["1789年8月制宪议会通过","自由平等、主权在民、财产神圣","英美法三国革命文献之一"],"mem":"三份文献按年代记“689、776、789”：英国《权利法案》1689，美国《独立宣言》1776，法国《人权宣言》1789。法国这份的关键词是自由、平等、主权在民。","mix":"“人人生而平等”是《独立宣言》的话；《人权宣言》说的是“权利方面自由平等”；《拿破仑法典》（1804）是民法典，《人权宣言》是政治宣言。","mcq":[{"q":"1789年法国制宪议会通过的纲领性文献是","o":["《独立宣言》","《拿破仑法典》","《人权宣言》","《权利法案》（英国）"],"a":2,"w":"《人权宣言》，同年8月通过。"},{"q":"下列各项中，《人权宣言》没有宣布的是","o":["主权属于国民","财产神圣不可侵犯","法律面前人人平等","君权神授"],"a":3,"w":"宣言否定君权神授，主张主权在民。"}],"rel":[{"t":"法国大革命","n":"产生背景"},{"t":"《独立宣言》","n":"美国的同类文献"},{"t":"《权利法案》（英国）","n":"英国的同类文献"},{"t":"天赋人权","n":"思想基础"}],"more":"名句：在权利方面，人们生来并且始终是自由平等的。｜《人权宣言》第一条\n1789年8月26日通过；1791年成为宪法序言。","exam":[]},{"id":"a10-083","t":"雅各宾派","cid":"10f","p":3,"kind":"流派","exam":[],"alias":[],"one":"1793至1794年以罗伯斯庇尔为首实行恐怖统治，热月政变后倒台。","ans":"1793至1794年以罗伯斯庇尔为首实行恐怖统治，热月政变后倒台。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-084","t":"拿破仑","cid":"10f","p":1,"kind":"人物","alias":["拿破仑·波拿巴","拿破仑一世","波拿巴"],"one":"法国军事家、政治家，1804年称帝，1815年滑铁卢战败后被流放。","ans":"拿破仑·波拿巴（1769—1821）是**法国军事家、政治家**，出生于科西嘉岛。他在法国大革命中因战功崛起，**1799年发动雾月政变**出任第一执政，**1804年称帝**，建立**法兰西第一帝国**，同年颁布**《拿破仑法典》**。他多次击败反法同盟，1805年在奥斯特里茨大胜俄奥联军，1812年远征俄国失败后帝国衰落。**1815年滑铁卢战役战败**，被流放到**圣赫勒拿岛**，1821年去世。他的战争把大革命的原则传播到欧洲各地，也激发了各国民族意识的觉醒。","pts":["1799雾月政变，1804称帝","颁布《拿破仑法典》","1815滑铁卢战败，流放圣赫勒拿岛"],"mem":"年份口诀（自编）“九九政变，零四称帝，一二败俄，一五滑铁卢”：1799、1804、1812、1815。画面：从科西嘉小岛起家，最后又被送到南大西洋的小岛。","mix":"贝多芬《英雄》原题献给拿破仑，相传他称帝后作者撕去题页；滑铁卢之战的对手是英国威灵顿和普鲁士军队；1814年第一次流放地是厄尔巴岛，最后流放地才是圣赫勒拿岛。","mcq":[{"q":"1804年称帝、建立法兰西第一帝国的是","o":["罗伯斯庇尔","拿破仑","路易十四","查理曼"],"a":1,"w":"拿破仑·波拿巴。"},{"q":"拿破仑最后被流放并去世的地方是","o":["科西嘉岛","厄尔巴岛","西西里岛","圣赫勒拿岛"],"a":3,"w":"1815年滑铁卢战败后被送往圣赫勒拿岛。"}],"rel":[{"t":"法国大革命","n":"他崛起的背景"},{"t":"《拿破仑法典》","n":"最持久的遗产"},{"t":"滑铁卢战役","n":"最后一战"},{"t":"贝多芬","n":"《英雄》原题献给他"}],"more":"1769年：生于科西嘉。\n1799年：雾月政变。\n1804年：称帝。\n1805年：奥斯特里茨战役。\n1812年：远征俄国。\n1815年：滑铁卢战役。\n1821年：逝于圣赫勒拿岛。","exam":[]},{"id":"a10-085","t":"《拿破仑法典》","cid":"10f","p":1,"kind":"作品","alias":["《法国民法典》","拿破仑民法典"],"one":"1804年颁布的《法国民法典》，第一部资本主义国家民法典。","ans":"《拿破仑法典》即**1804年颁布的《法国民法典》**，因拿破仑主持制定，1807年改称此名，是**第一部资本主义国家的民法典**。它以大革命的原则为基础，规定**法律面前人人平等**，**废除封建特权和农奴制**，**保护私有财产**，实行契约自由，并确立了世俗婚姻制度。法典条文简明，分为人、财产和取得财产的方法三编，成为**大陆法系的代表性法典**，被德国、意大利、日本等国的民法借鉴，并传到拉丁美洲。它使大革命的成果以法律形式固定下来，是拿破仑最持久的遗产。","pts":["1804年《法国民法典》，1807年改称","平等、废封建特权、保护私有财产","第一部资本主义民法典，大陆法系代表"],"mem":"“一八〇四，民法立”：拿破仑1804年称帝，同年颁布民法典。三个要点“平等、私产、契约”。法系对照：英美法系以判例法为特色，大陆法系以《拿破仑法典》为代表。","mix":"《拿破仑法典》是民法典，是私法，不是宪法；《人权宣言》是1789年的政治宣言；《十二铜表法》是古罗马成文法，《汉谟拉比法典》是古巴比伦法典，时代不同。","mcq":[{"q":"第一部资本主义国家的民法典是","o":["《汉谟拉比法典》","《拿破仑法典》","《十二铜表法》","《德国民法典》"],"a":1,"w":"1804年《法国民法典》，即《拿破仑法典》。"},{"q":"《拿破仑法典》是下列哪一法系的代表","o":["英美法系","伊斯兰法系","中华法系","大陆法系"],"a":3,"w":"大陆法系（民法法系）。"}],"rel":[{"t":"拿破仑","n":"主持制定者"},{"t":"大陆法系","n":"其代表法典"},{"t":"《十二铜表法》","n":"罗马法源头"},{"t":"《汉谟拉比法典》","n":"古代成文法对照"}],"more":"1804年：颁布。\n1807年：改称《拿破仑法典》。\n基本原则：法律面前人人平等、私有财产不可侵犯、契约自由。","exam":[]},{"id":"a10-086","t":"美国南北战争与林肯","cid":"10f","p":2,"kind":"事件","exam":[],"alias":[],"one":"1861至1865年；林肯1862年发布《解放黑人奴隶宣言》（1863年1月","ans":"1861至1865年；林肯1862年发布《解放黑人奴隶宣言》（1863年1月1日生效）；葛底斯堡演说“民有、民治、民享”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-087","t":"明治维新","cid":"10f","p":2,"kind":"事件","exam":[],"alias":[],"one":"1868年起日本推行“殖产兴业”“文明开化”“富国强兵”，走上资本主义道路。","ans":"1868年起日本推行“殖产兴业”“文明开化”“富国强兵”，走上资本主义道路。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-088","t":"俄国1861年农奴制改革","cid":"10f","p":3,"kind":"事件","exam":[],"alias":[],"one":"亚历山大二世宣布废除农奴制。","ans":"亚历山大二世宣布废除农奴制。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-089","t":"德意志统一与俾斯麦","cid":"10f","p":2,"kind":"事件","exam":[],"alias":[],"one":"普鲁士首相俾斯麦推行“铁血政策”，经三次王朝战争，1871年在凡尔赛宫宣告德","ans":"普鲁士首相俾斯麦推行“铁血政策”，经三次王朝战争，1871年在凡尔赛宫宣告德意志帝国成立。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-090","t":"意大利统一","cid":"10f","p":3,"kind":"事件","exam":[],"alias":[],"one":"加富尔、加里波第推动，1861年意大利王国成立，1870年收复罗马。","ans":"加富尔、加里波第推动，1861年意大利王国成立，1870年收复罗马。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-091","t":"巴黎公社","cid":"10f","p":2,"kind":"事件","exam":[],"alias":[],"one":"1871年3月18日巴黎工人起义建立，存在72天；鲍狄埃在公社失败后写下《国","ans":"1871年3月18日巴黎工人起义建立，存在72天；鲍狄埃在公社失败后写下《国际歌》歌词。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-092","t":"欧洲三大工人运动","cid":"10f","p":2,"kind":"合称","exam":[],"alias":[],"one":"法国里昂工人起义（1831、1834）、英国宪章运动（1836至1848）、","ans":"法国里昂工人起义（1831、1834）、英国宪章运动（1836至1848）、德国西里西亚纺织工人起义（1844）。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-093","t":"拉丁美洲独立运动","cid":"10f","p":3,"kind":"事件","exam":[],"alias":[],"one":"19世纪初，玻利瓦尔（“解放者”）、圣马丁领导。","ans":"19世纪初，玻利瓦尔（“解放者”）、圣马丁领导。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-094","t":"维也纳体系","cid":"10f","p":3,"kind":"制度","exam":[],"alias":[],"one":"1814至1815年维也纳会议重建欧洲秩序。","ans":"1814至1815年维也纳会议重建欧洲秩序。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-095","t":"珍妮纺纱机","cid":"10g","p":2,"kind":"常识","exam":[],"alias":[],"one":"约1765年英国哈格里夫斯发明，常作为英国工业革命开始的标志。","ans":"约1765年英国哈格里夫斯发明，常作为英国工业革命开始的标志。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-096","t":"瓦特改良蒸汽机","cid":"10g","p":1,"kind":"事件","alias":["瓦特","蒸汽机","蒸汽时代"],"one":"1785年改良蒸汽机投入使用，人类进入“蒸汽时代”。","ans":"瓦特改良蒸汽机是**英国工程师詹姆斯·瓦特**对纽科门蒸汽机的重大改进，属**第一次工业革命的核心成就**。他加装**分离冷凝器**，大幅提高热效率，1769年获得专利，又发明联动装置，使活塞的往复运动变为旋转运动。**1785年改良蒸汽机投入使用**，蒸汽机得以广泛用于纺织、冶金、采矿，也为火车和轮船提供动力。人类由此进入**“蒸汽时代”**，工厂不再依赖水力而可以建在任何地方。功率单位**“瓦特”**以他的名字命名。","pts":["瓦特改良纽科门机，加分离冷凝器","1785年投入使用，蒸汽时代","功率单位瓦特以其命名"],"mem":"“珍妮纺纱，瓦特蒸汽”：纺织机器先动起来，蒸汽机再给所有机器供能。年份挂钩：1785年晚于《国富论》（1776）九年，早于法国大革命（1789）四年。","mix":"瓦特是改良者，最早的实用蒸汽机是纽科门机；史蒂芬孙发明的是蒸汽机车，富尔顿造的是汽船。","mcq":[{"q":"第一次工业革命中改良蒸汽机的是","o":["史蒂芬孙","哈格里夫斯","富尔顿","瓦特"],"a":3,"w":"瓦特；史蒂芬孙造机车，哈格里夫斯造珍妮机。"},{"q":"通常把哪一项成就看作“蒸汽时代”的开始","o":["珍妮纺纱机的发明","瓦特改良蒸汽机投入使用","蒸汽机车通车","电灯的发明"],"a":1,"w":"1785年瓦特改良蒸汽机投入使用。"}],"rel":[{"t":"工业革命","n":"所属事件"},{"t":"史蒂芬孙与铁路","n":"蒸汽动力用于交通"},{"t":"第二次工业革命","n":"蒸汽时代之后"},{"t":"亚当·斯密与《国富论》","n":"同时代，前者讲分工"}],"more":"1769年：瓦特获专利。\n1785年：改良蒸汽机投入使用。\n功率单位：瓦特（W）。","exam":[]},{"id":"a10-097","t":"史蒂芬孙与铁路","cid":"10g","p":3,"kind":"人物","exam":[],"alias":[],"one":"1814年制成蒸汽机车，1825年英国斯托克顿至达灵顿铁路通车。","ans":"1814年制成蒸汽机车，1825年英国斯托克顿至达灵顿铁路通车。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-098","t":"第二次工业革命","cid":"10g","p":1,"kind":"事件","alias":["第二次科技革命","电气时代","电力时代"],"one":"19世纪70年代起以电力广泛应用为标志，进入“电气时代”。","ans":"第二次工业革命是**19世纪70年代起以电力的广泛应用为标志的技术革命**，使人类进入**“电气时代”**，**美国和德国**成为领先国家。主要成就有：**发电机和电动机的发明**，贝尔发明电话（1876年），爱迪生发明实用电灯（1879年），**内燃机的发明**和卡尔·本茨制成汽车（1885年前后），**莱特兄弟试飞飞机（1903年）**。电力、钢铁、石油、化学等重工业迅速发展，**垄断组织出现**，世界市场最终形成，也加剧了列强的殖民争夺，成为第一次世界大战的深层背景。","pts":["19世纪70年代，电力应用，电气时代","发电机、电灯、电话、内燃机、飞机","美德领先，垄断组织出现"],"mem":"“电、话、灯、车、机”五字：发电机、贝尔电话（1876）、爱迪生电灯（1879）、本茨汽车（1885）、莱特兄弟飞机（1903），年份依次递增。三次革命标签：蒸汽、电气、信息。","mix":"第一次工业革命在英国，棉纺织业起步；第二次领先者是美、德。莱特兄弟飞机虽在1903年，仍属第二次工业革命的成果。","mcq":[{"q":"第二次工业革命的主要标志是","o":["蒸汽机的广泛使用","电力的广泛应用","电子计算机的发明","原子能的利用"],"a":1,"w":"电力广泛应用，进入电气时代。"},{"q":"下列发明与发明者对应正确的是","o":["瓦特：电灯","爱迪生：飞机","本茨：蒸汽机车","贝尔：电话"],"a":3,"w":"贝尔发明电话；本茨造的是汽油内燃机汽车。"}],"rel":[{"t":"工业革命","n":"前一次，蒸汽时代"},{"t":"第三次科技革命","n":"后一次，信息时代"},{"t":"第一次世界大战","n":"列强争夺的深层背景"},{"t":"第四次工业革命","n":"当前讨论的新一轮"}],"more":"1876年：贝尔发明电话。\n1879年：爱迪生发明实用电灯。\n1885年前后：本茨制成汽车。\n1903年：莱特兄弟试飞飞机。","exam":[]},{"id":"a10-099","t":"第三次科技革命","cid":"10g","p":1,"kind":"事件","alias":["第三次工业革命","信息革命","信息时代"],"one":"20世纪四五十年代起，以原子能、计算机、空间技术为标志，进入信息时代。","ans":"第三次科技革命是**20世纪四五十年代起，以原子能、电子计算机、空间技术和生物工程为标志的科技革命**，使人类进入**“信息时代”**。主要成就有：1945年美国制成原子弹，1946年第一台电子计算机ENIAC诞生，1953年发现DNA双螺旋结构，1957年苏联发射第一颗人造地球卫星，1969年美国阿波罗11号载人登月，以及后来的克隆技术。这次革命使科学技术在生产中的作用空前提高，推动产业结构升级和经济全球化，同时也带来核威胁等新问题。","pts":["20世纪四五十年代起，信息时代","原子能、电子计算机、空间技术、生物工程","推动产业升级与全球化"],"mem":"“原、算、空、生”四字：原子能、计算机、空间技术、生物工程。年份挂钩：1946计算机，1957卫星，1969登月，三个数字递增。三次革命标签：蒸汽、电气、信息。","mix":"有的教材称“第三次工业革命”，有的称“第三次科技革命”，指同一事物；当前所说的第四次工业革命指人工智能、大数据等，不属于第三次。","mcq":[{"q":"下列各项中，不属于第三次科技革命标志的是","o":["电子计算机","空间技术","原子能","蒸汽机"],"a":3,"w":"蒸汽机属于第一次工业革命。"},{"q":"1957年发射世界第一颗人造地球卫星的国家是","o":["美国","英国","中国","苏联"],"a":3,"w":"苏联发射“斯普特尼克1号”。"}],"rel":[{"t":"第二次工业革命","n":"前一次，电气时代"},{"t":"第四次工业革命","n":"后续的新一轮"},{"t":"图灵与图灵测试","n":"计算机与人工智能源头"},{"t":"冷战","n":"太空竞赛的背景"}],"more":"1945年：原子弹。\n1946年：ENIAC。\n1953年：DNA双螺旋结构。\n1957年：人造卫星。\n1969年：阿波罗11号登月。","exam":[]},{"id":"a10-100","t":"第四次工业革命","cid":"10g","p":3,"kind":"概念","exam":[],"alias":[],"one":"2016年世界经济论坛创始人施瓦布系统阐述，以人工智能、物联网、生物技术等融","ans":"2016年世界经济论坛创始人施瓦布系统阐述，以人工智能、物联网、生物技术等融合为特征；德国2013年提出“工业4.0”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-101","t":"三国同盟与三国协约","cid":"10g","p":2,"kind":"合称","exam":[],"alias":[],"one":"三国同盟（1882）：德国、奥匈帝国、意大利；三国协约（1907）：英国、法","ans":"三国同盟（1882）：德国、奥匈帝国、意大利；三国协约（1907）：英国、法国、俄国；一战中意大利倒向协约国。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-102","t":"萨拉热窝事件","cid":"10g","p":2,"kind":"事件","exam":[],"alias":[],"one":"1914年6月28日奥匈帝国皇储斐迪南夫妇在萨拉热窝被塞尔维亚青年刺杀，一战","ans":"1914年6月28日奥匈帝国皇储斐迪南夫妇在萨拉热窝被塞尔维亚青年刺杀，一战导火线。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-103","t":"第一次世界大战","cid":"10g","p":1,"kind":"事件","alias":["一战","欧战"],"one":"1914至1918年同盟国与协约国之间的世界大战，1918年11月11日德国投降。","ans":"第一次世界大战是**1914—1918年以德国、奥匈帝国为首的同盟国与以英、法、俄为首的协约国之间的战争**，起因是列强争夺殖民地和世界霸权，1914年**萨拉热窝事件**成为导火线。战争中有**凡尔登战役、索姆河战役**，**索姆河战役首次使用坦克**。**1917年美国参战，俄国因十月革命退出**。**1918年11月11日德国投降**，协约国获胜，战后召开巴黎和会，签订《凡尔赛条约》，形成**凡尔赛—华盛顿体系**。战争造成上千万军人死亡，德、奥匈、俄、奥斯曼四大帝国相继崩溃。","pts":["1914—1918，同盟国对协约国","萨拉热窝导火线，索姆河首用坦克","1918.11.11德国投降，凡尔赛体系"],"mem":"“一四到一八”记年份。“萨、凡、索”三地：萨拉热窝点火，凡尔登消耗，索姆河首用坦克。停战记“三个十一”：1918年11月11日11时。","mix":"一战的同盟国是德、奥匈等，协约国是英、法、俄等；二战中的“同盟国”指反法西斯一方，所指相反。意大利1915年加入协约国，俄国1917年退出。","mcq":[{"q":"第一次世界大战的导火线是","o":["凡尔登战役","萨拉热窝事件","俄国十月革命","美国参战"],"a":1,"w":"1914年6月奥匈皇储在萨拉热窝遇刺。"},{"q":"第一次世界大战中首次使用坦克的战役是","o":["凡尔登战役","马恩河战役","索姆河战役","日德兰海战"],"a":2,"w":"1916年索姆河战役。"}],"rel":[{"t":"三国同盟与三国协约","n":"战前两大军事集团"},{"t":"凡尔赛-华盛顿体系","n":"战后秩序"},{"t":"十月革命","n":"战争期间爆发"},{"t":"第二次世界大战","n":"二十年后再起"}],"more":"1914年6月：萨拉热窝事件。\n1916年：凡尔登战役、索姆河战役。\n1917年：美国参战，俄国退出。\n1918年11月11日：德国投降。\n1919年：巴黎和会、《凡尔赛条约》。","exam":[]},{"id":"a10-104","t":"十月革命","cid":"10g","p":1,"kind":"事件","alias":["俄国十月革命","十一月革命"],"one":"1917年列宁领导布尔什维克起义，建立第一个社会主义国家。","ans":"十月革命是**1917年11月7日（俄历10月25日）列宁领导布尔什维克在彼得格勒发动的武装起义**，推翻**临时政府**，建立了**世界上第一个社会主义国家**苏维埃俄国。起义以**阿芙乐尔号巡洋舰的炮声**为信号，攻占冬宫。革命后通过《和平法令》和《土地法令》，宣布退出一战、废除地主土地所有制。此前**1917年二月革命**已推翻沙皇统治。十月革命开辟了社会主义国家的新纪元，毛泽东说：**“十月革命一声炮响，给我们送来了马克思列宁主义。”**它对中国共产党的诞生有重要影响。","pts":["1917.11.7（俄历10.25），列宁领导","推翻临时政府，第一个社会主义国家","毛泽东：一声炮响送来马列主义"],"mem":"“十月革命十一月打”：俄历10月25日对应公历11月7日。顺序：二月革命推翻沙皇，十月革命推翻临时政府。","mix":"二月革命（1917年3月，公历）推翻沙皇，十月革命夺取临时政府权力；叫“十月”是因为用的是俄历。毛泽东这句话出自1949年《论人民民主专政》。","mcq":[{"q":"十月革命的领导人是","o":["列宁","斯大林","克伦斯基","彼得大帝"],"a":0,"w":"列宁领导布尔什维克。"},{"q":"十月革命推翻的政权是","o":["沙皇尼古拉二世政权","苏维埃政权","俄国临时政府","白军政权"],"a":2,"w":"沙皇已于二月革命被推翻，十月革命推翻的是资产阶级临时政府。"}],"rel":[{"t":"第一次世界大战","n":"革命发生的战争背景"},{"t":"中国共产党第一次全国代表大会","n":"影响中国建党"},{"t":"东欧剧变与苏联解体","n":"社会主义阵营后续"},{"t":"冷战","n":"此后两大阵营对峙"}],"more":"1917年3月：二月革命。\n1917年11月7日：十月革命。\n名言：十月革命一声炮响，给我们送来了马克思列宁主义。｜毛泽东《论人民民主专政》","exam":[]},{"id":"a10-105","t":"凡尔赛-华盛顿体系","cid":"10g","p":2,"kind":"制度","exam":[],"alias":[],"one":"1919年巴黎和会签订《凡尔赛和约》，和会把德国在山东的权益转给日本，引发五","ans":"1919年巴黎和会签订《凡尔赛和约》，和会把德国在山东的权益转给日本，引发五四运动；1921至1922年华盛顿会议签订《九国公约》等。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-106","t":"国际联盟","cid":"10g","p":3,"kind":"制度","exam":[],"alias":[],"one":"1920年成立，总部日内瓦，美国未加入，未能阻止二战，1946年解散。","ans":"1920年成立，总部日内瓦，美国未加入，未能阻止二战，1946年解散。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-107","t":"1929至1933年经济大危机","cid":"10g","p":2,"kind":"事件","exam":[],"alias":[],"one":"1929年10月纽约股市崩盘，引发资本主义世界最严重的经济危机。","ans":"1929年10月纽约股市崩盘，引发资本主义世界最严重的经济危机。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-108","t":"罗斯福新政","cid":"10g","p":2,"kind":"事件","exam":[],"alias":[],"one":"1933年起以国家干预经济应对危机，核心是《全国工业复兴法》，兴办公共工程“","ans":"1933年起以国家干预经济应对危机，核心是《全国工业复兴法》，兴办公共工程“以工代赈”，建立社会保障制度。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-109","t":"绥靖政策与慕尼黑协定","cid":"10g","p":2,"kind":"事件","exam":[],"alias":[],"one":"1938年英、法、德、意签订《慕尼黑协定》，把捷克斯洛伐克苏台德区割给德国，","ans":"1938年英、法、德、意签订《慕尼黑协定》，把捷克斯洛伐克苏台德区割给德国，是绥靖政策的顶点。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-110","t":"第二次世界大战","cid":"10g","p":1,"kind":"事件","alias":["二战"],"one":"1939至1945年反法西斯同盟与德意日轴心国的战争，中国是东方主战场。","ans":"第二次世界大战是**1939—1945年以苏、美、英、中等为主的反法西斯同盟国与德、意、日轴心国之间的世界规模战争**。**1939年9月1日德国入侵波兰**，欧洲战争爆发；**中国抗战1931年局部开始、1937年全面爆发**，是**东方主战场**。1941年6月苏德战争爆发，12月太平洋战争爆发，1944年盟军开辟诺曼底第二战场。**1945年5月德国投降，9月2日日本签署投降书**，战争结束。战后形成雅尔塔体系，成立联合国，并开启美苏冷战。2025年是世界反法西斯战争暨中国抗战胜利80周年。","pts":["1939.9.1德国入侵波兰，反法西斯同盟对轴心国","中国是东方主战场，1931起、1937全面","1945.9.2日本投降，战后联合国与雅尔塔体系"],"mem":"“三九到四五”：1939—1945。三个“一”：9月1日波兰开战，12月珍珠港扩大，9月2日日本签字收尾。中国抗战的“十四年”从1931年算起。","mix":"二战的“同盟国”指反法西斯一方，与一战的同盟国（德、奥匈）所指相反；日本宣布投降在8月15日，签署投降书在9月2日；中国抗战从九一八事变（1931）算起共14年。","mcq":[{"q":"欧洲战场第二次世界大战的爆发以哪一事件为标志","o":["德国入侵苏联","德国入侵波兰","日本偷袭珍珠港","慕尼黑会议"],"a":1,"w":"1939年9月1日德国入侵波兰。"},{"q":"日本正式签署投降书、二战结束的日期是","o":["1945年8月6日","1945年8月15日","1945年5月8日","1945年9月2日"],"a":3,"w":"8月15日是日本宣布投降，9月2日在“密苏里”号上签署投降书。"}],"rel":[{"t":"第一次世界大战","n":"二十年前的前一次大战"},{"t":"联合国","n":"战后建立的国际组织"},{"t":"雅尔塔体系","n":"战后国际秩序"},{"t":"2025年九三阅兵","n":"抗战胜利80周年纪念"}],"more":"1939年9月1日：入侵波兰。\n1941年：苏德战争、太平洋战争。\n1944年：诺曼底登陆。\n1945年：德国、日本相继投降，联合国成立。","exam":[]},{"id":"a10-111","t":"珍珠港事件","cid":"10g","p":2,"kind":"事件","exam":[],"alias":[],"one":"1941年12月7日日本偷袭美国太平洋舰队基地珍珠港，太平洋战争爆发，美国参","ans":"1941年12月7日日本偷袭美国太平洋舰队基地珍珠港，太平洋战争爆发，美国参战。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-112","t":"《联合国家宣言》","cid":"10g","p":2,"kind":"作品","exam":[],"alias":[],"one":"1942年1月1日26国在华盛顿签署，世界反法西斯同盟正式形成，美、英、苏、","ans":"1942年1月1日26国在华盛顿签署，世界反法西斯同盟正式形成，美、英、苏、中四国领衔签字。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-113","t":"斯大林格勒战役与诺曼底登陆","cid":"10g","p":2,"kind":"事件","exam":[],"alias":[],"one":"斯大林格勒战役（1942至1943）是二战转折点；1944年6月6日盟军在法","ans":"斯大林格勒战役（1942至1943）是二战转折点；1944年6月6日盟军在法国诺曼底登陆，开辟欧洲第二战场。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-114","t":"《开罗宣言》与《波茨坦公告》","cid":"10g","p":2,"kind":"作品","exam":[],"alias":[],"one":"1943年中美英开罗会议发表《开罗宣言》，规定日本归还窃取的东北、台湾、澎湖","ans":"1943年中美英开罗会议发表《开罗宣言》，规定日本归还窃取的东北、台湾、澎湖列岛；1945年7月《波茨坦公告》重申并敦促日本无条件投降。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-115","t":"雅尔塔体系","cid":"10g","p":2,"kind":"制度","exam":[],"alias":[],"one":"1945年2月美英苏雅尔塔会议，商定战后处置德日、建立联合国等，形成美苏两极","ans":"1945年2月美英苏雅尔塔会议，商定战后处置德日、建立联合国等，形成美苏两极格局。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-116","t":"联合国","cid":"10g","p":1,"kind":"制度","alias":["UN","联合国组织"],"one":"1945年成立的最大政府间国际组织，总部纽约，安理会五常有否决权。","ans":"联合国是**1945年10月24日正式成立的政府间国际组织**，以**维护国际和平与安全、促进国际合作**为宗旨，是二战后国际秩序的核心。总部设在**纽约**，设有**大会、安全理事会、经济及社会理事会、托管理事会、国际法院、秘书处**六大主要机构。安理会有**五个常任理事国（中、法、俄、英、美）**，对实质性事项拥有**否决权**。**1971年联大通过第2758号决议，恢复中华人民共和国的合法席位**。联合国在维和、发展、人权等领域发挥重要作用，其工作语言为六种正式语言。","pts":["1945.10.24成立，总部纽约","六大机构；安理会五常有否决权","1971年第2758号决议恢复中国席位"],"mem":"“大安经托法秘”六大机构首字（自编）。五常记“中法俄英美”。三个数字：1945年成立、10月24日（联合国日）、1971年中国恢复席位。","mix":"国际联盟（1920）是一战后的前身，联合国是二战后；联合国总部在纽约，国际法院在海牙；第2758号决议解决的是中国代表权，与台湾问题的法律地位无关。","mcq":[{"q":"联合国安理会常任理事国不包括","o":["中国","法国","德国","俄罗斯"],"a":2,"w":"五常是中、法、俄、英、美。"},{"q":"恢复中华人民共和国在联合国合法席位的决议是","o":["第1514号决议","第2758号决议","第242号决议","第678号决议"],"a":1,"w":"1971年联大第2758号决议。"}],"rel":[{"t":"联合国安理会与五个常任理事国","n":"最重要机构"},{"t":"联合国六大主要机关","n":"机构组成"},{"t":"联合国第2758号决议","n":"中国席位"},{"t":"国际联盟","n":"一战后前身，对照"}],"more":"1945年4—6月：旧金山会议制定《联合国宪章》。\n1945年10月24日：宪章生效，联合国成立。\n1971年10月25日：联大通过第2758号决议。","exam":[]},{"id":"a10-117","t":"纽伦堡审判","cid":"10g","p":3,"kind":"事件","exam":[],"alias":[],"one":"1945至1946年在德国纽伦堡审判纳粹首要战犯。","ans":"1945至1946年在德国纽伦堡审判纳粹首要战犯。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-118","t":"杜鲁门主义","cid":"10g","p":2,"kind":"事件","exam":[],"alias":[],"one":"1947年3月提出，以“遏制共产主义”为目标；马歇尔计划为经济手段，北约（1","ans":"1947年3月提出，以“遏制共产主义”为目标；马歇尔计划为经济手段，北约（1949）为军事手段。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-119","t":"柏林墙","cid":"10g","p":2,"kind":"常识","exam":[],"alias":[],"one":"1961年东德修建，1989年11月9日开放，1990年10月3日两德统一。","ans":"1961年东德修建，1989年11月9日开放，1990年10月3日两德统一。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-120","t":"华沙条约组织","cid":"10g","p":3,"kind":"制度","exam":[],"alias":[],"one":"1955年成立，1991年解散。","ans":"1955年成立，1991年解散。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-121","t":"古巴导弹危机","cid":"10g","p":3,"kind":"事件","exam":[],"alias":[],"one":"1962年，冷战中美苏最接近核战争的一次危机。","ans":"1962年，冷战中美苏最接近核战争的一次危机。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-122","t":"不结盟运动","cid":"10g","p":3,"kind":"事件","exam":[],"alias":[],"one":"1961年在贝尔格莱德召开首次首脑会议，铁托、纳赛尔、尼赫鲁等倡导。","ans":"1961年在贝尔格莱德召开首次首脑会议，铁托、纳赛尔、尼赫鲁等倡导。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-123","t":"东欧剧变与苏联解体","cid":"10g","p":2,"kind":"事件","exam":[],"alias":[],"one":"1989年东欧剧变；1991年12月25日戈尔巴乔夫辞职，苏联解体，冷战结束","ans":"1989年东欧剧变；1991年12月25日戈尔巴乔夫辞职，苏联解体，冷战结束。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-124","t":"布雷顿森林体系","cid":"10g","p":3,"kind":"制度","exam":[],"alias":[],"one":"1944年确立美元与黄金挂钩、各国货币与美元挂钩的国际货币体系，设立国际货币","ans":"1944年确立美元与黄金挂钩、各国货币与美元挂钩的国际货币体系，设立国际货币基金组织和世界银行；1971至1973年瓦解。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-125","t":"古希腊雕塑名作","cid":"10h","p":3,"kind":"作品","exam":[],"alias":[],"one":"米隆《掷铁饼者》，《米洛的维纳斯》（断臂维纳斯，藏卢浮宫），《拉奥孔》群像，","ans":"米隆《掷铁饼者》，《米洛的维纳斯》（断臂维纳斯，藏卢浮宫），《拉奥孔》群像，《萨莫色雷斯的胜利女神》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-126","t":"罗马式建筑","cid":"10h","p":3,"kind":"流派","exam":[],"alias":[],"one":"10至12世纪流行，厚墙、半圆拱、小窗，代表比萨大教堂。","ans":"10至12世纪流行，厚墙、半圆拱、小窗，代表比萨大教堂。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-127","t":"哥特式建筑","cid":"10h","p":1,"kind":"流派","alias":["哥特式","哥特建筑"],"one":"12至16世纪欧洲教堂建筑风格，尖拱、肋架拱顶、飞扶壁、彩色玻璃花窗。","ans":"哥特式建筑是**12至16世纪流行于西欧的教堂建筑风格**，起源于法国，继罗马式建筑而兴，属**中世纪晚期天主教建筑**。其特征是**尖拱、肋架拱顶、飞扶壁**，使墙体减轻、内部高耸，并开大面积**彩色玻璃花窗**，营造向天升腾的神圣感。代表建筑有**巴黎圣母院、科隆大教堂、米兰大教堂**。“哥特”原是文艺复兴时人对中世纪风格的贬称，意为野蛮。哥特式在**建筑结构上的创新**影响深远，雨果小说《巴黎圣母院》使该教堂举世闻名。","pts":["12—16世纪，尖拱、肋架拱顶、飞扶壁、花窗","巴黎圣母院、科隆大教堂、米兰大教堂","“哥特”原为文艺复兴时的贬称"],"mem":"“尖、肋、飞、窗”四字：尖拱、肋架拱顶、飞扶壁、彩色玻璃花窗。画面：教堂像一支向天伸的尖笔。对比：罗马式厚墙圆拱，哥特式尖拱高窗。","mix":"哥特式（中世纪）在文艺复兴之前，文艺复兴建筑转向古典柱式与圆拱穹顶；古希腊三大柱式（多立克、爱奥尼、科林斯）属古典建筑，与哥特式无关；哥特式与“哥特人”并无直接关系。","mcq":[{"q":"下列属于哥特式建筑特征的是","o":["尖拱与飞扶壁","多立克柱式","圆形穹顶","斗拱"],"a":0,"w":"尖拱、肋架拱顶、飞扶壁、彩色玻璃花窗。"},{"q":"下列建筑中，属于哥特式的是","o":["万神庙","巴黎圣母院","圣索菲亚大教堂","帕提农神庙"],"a":1,"w":"万神庙属古罗马，帕提农是古希腊，圣索菲亚是拜占庭。"}],"rel":[{"t":"《巴黎圣母院》","n":"雨果与哥特教堂"},{"t":"欧洲中世纪","n":"所属时代"},{"t":"古希腊三大柱式","n":"古典建筑对照"},{"t":"文艺复兴","n":"“哥特”称呼的由来"}],"more":"代表建筑：巴黎圣母院（12世纪始建）、科隆大教堂（1248年始建，1880年完工）、米兰大教堂。\n巴黎圣母院2019年4月遭大火。","exam":[]},{"id":"a10-128","t":"拜占庭建筑与圣索菲亚大教堂","cid":"10h","p":3,"kind":"流派","exam":[],"alias":[],"one":"以圆穹顶和马赛克镶嵌为特色；伊斯坦布尔圣索菲亚大教堂537年建成，1453年","ans":"以圆穹顶和马赛克镶嵌为特色；伊斯坦布尔圣索菲亚大教堂537年建成，1453年后改为清真寺。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-129","t":"达·芬奇","cid":"10h","p":1,"kind":"人物","alias":["列奥纳多·达·芬奇","列奥纳多"],"one":"意大利文艺复兴全才，画《蒙娜丽莎》《最后的晚餐》，手稿涉及解剖与机械。","ans":"列奥纳多·达·芬奇（1452—1519）是**意大利文艺复兴盛期的画家、科学家和工程师**，“美术三杰”之一。他的代表作是**《蒙娜丽莎》**（藏卢浮宫）和**《最后的晚餐》**（绘于米兰修道院餐厅墙上），善用**明暗渐变和空气透视**表现立体感。他的大量手稿涉及**解剖学、机械、飞行器、水利**，被视为**文艺复兴“全才”**的典范。晚年应法国国王弗朗索瓦一世之邀赴法，卒于法国。他的作品体现**人文主义的写实精神**，对后世绘画与科学观察方法影响深远。","pts":["意大利，美术三杰之一，全才","《蒙娜丽莎》《最后的晚餐》","手稿涉及解剖、机械、飞行器"],"mem":"“一笑一餐”：笑（蒙娜丽莎的微笑）、餐（最后的晚餐）。三杰顺序“达米拉”，达·芬奇年龄最大。画面：左手写镜像字的发明家。","mix":"《最后的晚餐》（达·芬奇）与《雅典学院》（拉斐尔）、《创世纪》天顶画（米开朗基罗）常被混；蒙娜丽莎藏于法国卢浮宫，不在意大利。","mcq":[{"q":"《最后的晚餐》的作者是","o":["拉斐尔","米开朗基罗","提香","达·芬奇"],"a":3,"w":"达·芬奇，绘于米兰。"},{"q":"下列作品中，出自达·芬奇之手的是","o":["《蒙娜丽莎》","《大卫》","《雅典学院》","《创世纪》"],"a":0,"w":"《大卫》《创世纪》是米开朗基罗，《雅典学院》是拉斐尔。"}],"rel":[{"t":"美术三杰","n":"所属合称"},{"t":"《蒙娜丽莎》","n":"代表作"},{"t":"《最后的晚餐》","n":"代表作"},{"t":"文艺复兴","n":"所处时代"}],"more":"代表作：《蒙娜丽莎》《最后的晚餐》《岩间圣母》《维特鲁威人》。\n1519年：卒于法国昂布瓦斯。","exam":[]},{"id":"a10-130","t":"米开朗基罗","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"雕塑《大卫》《摩西》，西斯廷礼拜堂天顶画《创世记》与壁画《最后的审判》，设计","ans":"雕塑《大卫》《摩西》，西斯廷礼拜堂天顶画《创世记》与壁画《最后的审判》，设计圣彼得大教堂穹顶。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-131","t":"拉斐尔","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"以圣母像著称，《西斯廷圣母》；壁画《雅典学院》中央为柏拉图与亚里士多德。","ans":"以圣母像著称，《西斯廷圣母》；壁画《雅典学院》中央为柏拉图与亚里士多德。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-132","t":"《蒙娜丽莎》","cid":"10h","p":2,"kind":"作品","exam":[],"alias":[],"one":"达·芬奇作，藏卢浮宫，运用晕涂法，以“神秘的微笑”闻名。","ans":"达·芬奇作，藏卢浮宫，运用晕涂法，以“神秘的微笑”闻名。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-133","t":"《最后的晚餐》","cid":"10h","p":3,"kind":"作品","exam":[],"alias":[],"one":"达·芬奇为米兰圣玛利亚感恩教堂食堂所作壁画，表现耶稣说出“你们中有一个人要出","ans":"达·芬奇为米兰圣玛利亚感恩教堂食堂所作壁画，表现耶稣说出“你们中有一个人要出卖我”的瞬间。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-134","t":"波提切利《维纳斯的诞生》","cid":"10h","p":3,"kind":"作品","exam":[],"alias":[],"one":"佛罗伦萨画派，藏乌菲齐美术馆。","ans":"佛罗伦萨画派，藏乌菲齐美术馆。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-135","t":"巴洛克艺术","cid":"10h","p":2,"kind":"流派","exam":[],"alias":[],"one":"17世纪，动感、华丽、明暗对比强烈；美术有鲁本斯、贝尼尼，音乐有巴赫、亨德尔","ans":"17世纪，动感、华丽、明暗对比强烈；美术有鲁本斯、贝尼尼，音乐有巴赫、亨德尔。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-136","t":"洛可可艺术","cid":"10h","p":3,"kind":"流派","exam":[],"alias":[],"one":"18世纪法国，纤巧繁复，华托、布歇。","ans":"18世纪法国，纤巧繁复，华托、布歇。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-137","t":"伦勃朗","cid":"10h","p":3,"kind":"人物","exam":[],"alias":[],"one":"荷兰“黄金时代”画家，《夜巡》，以光影处理著称。","ans":"荷兰“黄金时代”画家，《夜巡》，以光影处理著称。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-138","t":"新古典主义美术","cid":"10h","p":3,"kind":"流派","exam":[],"alias":[],"one":"18世纪末至19世纪初，达维特《马拉之死》，安格尔《泉》。","ans":"18世纪末至19世纪初，达维特《马拉之死》，安格尔《泉》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-139","t":"浪漫主义美术","cid":"10h","p":2,"kind":"流派","exam":[],"alias":[],"one":"德拉克洛瓦《自由引导人民》（取材1830年七月革命），籍里柯《梅杜萨之筏》。","ans":"德拉克洛瓦《自由引导人民》（取材1830年七月革命），籍里柯《梅杜萨之筏》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-140","t":"现实主义美术","cid":"10h","p":3,"kind":"流派","exam":[],"alias":[],"one":"库尔贝《奥尔南的葬礼》，米勒《拾穗者》《晚钟》。","ans":"库尔贝《奥尔南的葬礼》，米勒《拾穗者》《晚钟》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-141","t":"印象派","cid":"10h","p":1,"kind":"流派","alias":["印象主义","印象画派"],"one":"19世纪下半叶法国画派，户外写生，捕捉光与色，名称来自莫奈《日出·印象》。","ans":"印象派是**19世纪下半叶兴起于法国的绘画流派**，主张走出画室**户外写生**，捕捉光与色在瞬间的变化，用鲜明的色彩和短促的笔触作画。名称来自**莫奈的《日出·印象》**（1872年作，1874年首次画展展出）。代表画家有**莫奈、雷诺阿、德加、毕沙罗**，**马奈**是其先驱。莫奈有《睡莲》《干草垛》等系列，雷诺阿作《游船上的午餐》。印象派**突破了学院派的传统画法**，开启了西方现代绘画，后来发展出以塞尚、梵高、高更为代表的**后印象派**。2026年12月5日是莫奈逝世100周年。","pts":["19世纪下半叶法国，户外写生，光与色","名称来自莫奈《日出·印象》","莫奈、雷诺阿、德加；马奈先驱"],"mem":"“印象”一词来自一幅画名：《日出·印象》。人物记“莫雷德”：莫奈、雷诺阿、德加。画面：光的变化比轮廓更重要，所以笔触短而碎。时间线：印象派（1874首展）在前，后印象派三大家（塞尚、梵高、高更）在后。","mix":"后印象派（塞尚、梵高、高更）是在印象派之后、反思其不足；马奈被视为先驱，常被误当作成员；浪漫主义（德拉克洛瓦）、现实主义（库尔贝）早于印象派。","mcq":[{"q":"“印象派”名称来源于哪幅作品","o":["《睡莲》","《草地上的午餐》","《日出·印象》","《干草垛》"],"a":2,"w":"莫奈《日出·印象》。"},{"q":"下列画家中，不属于印象派的是","o":["莫奈","雷诺阿","德加","梵高"],"a":3,"w":"梵高属于后印象派。"}],"rel":[{"t":"莫奈","n":"代表画家"},{"t":"后印象派三大家","n":"其后的发展"},{"t":"浪漫主义美术","n":"此前的流派"},{"t":"巴洛克艺术","n":"更早的艺术风格，对照"}],"more":"1872年：莫奈作《日出·印象》。\n1874年：第一届印象派画展。\n莫奈1926年12月5日逝世。","exam":[]},{"id":"a10-142","t":"莫奈","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"《日出·印象》《睡莲》系列、《干草堆》系列，印象派领袖。","ans":"《日出·印象》《睡莲》系列、《干草堆》系列，印象派领袖。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-143","t":"后印象派三大家","cid":"10h","p":2,"kind":"合称","exam":[],"alias":[],"one":"塞尚（被称为“现代绘画之父”）、梵高（《向日葵》《星月夜》）、高更（《我们从","ans":"塞尚（被称为“现代绘画之父”）、梵高（《向日葵》《星月夜》）、高更（《我们从哪里来？我们是谁？我们到哪里去？》）。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-144","t":"梵高","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"荷兰，《向日葵》《星月夜》《麦田群鸦》，生前作品几乎卖不出去。","ans":"荷兰，《向日葵》《星月夜》《麦田群鸦》，生前作品几乎卖不出去。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-145","t":"野兽派","cid":"10h","p":3,"kind":"流派","exam":[],"alias":[],"one":"马蒂斯为代表，使用强烈纯色。","ans":"马蒂斯为代表，使用强烈纯色。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-146","t":"立体主义与毕加索","cid":"10h","p":2,"kind":"流派","exam":[],"alias":[],"one":"毕加索、布拉克创立；《亚威农少女》（1907）为开端；《格尔尼卡》（1937","ans":"毕加索、布拉克创立；《亚威农少女》（1907）为开端；《格尔尼卡》（1937）控诉德军轰炸西班牙小镇格尔尼卡；毕加索另画有和平鸽。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-147","t":"超现实主义","cid":"10h","p":3,"kind":"流派","exam":[],"alias":[],"one":"1924年布勒东发表宣言；达利《记忆的永恒》（软钟），马格利特。","ans":"1924年布勒东发表宣言；达利《记忆的永恒》（软钟），马格利特。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-148","t":"抽象艺术","cid":"10h","p":3,"kind":"流派","exam":[],"alias":[],"one":"康定斯基、蒙德里安。","ans":"康定斯基、蒙德里安。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-149","t":"罗丹","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"法国雕塑家，《思想者》原为《地狱之门》（取材《神曲》）的一部分，另有《巴尔扎","ans":"法国雕塑家，《思想者》原为《地狱之门》（取材《神曲》）的一部分，另有《巴尔扎克像》《加莱义民》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-150","t":"世界四大博物馆","cid":"10h","p":3,"kind":"合称","exam":[],"alias":[],"one":"一般指法国卢浮宫、英国大英博物馆、美国大都会艺术博物馆、俄罗斯艾尔米塔什博物","ans":"一般指法国卢浮宫、英国大英博物馆、美国大都会艺术博物馆、俄罗斯艾尔米塔什博物馆（冬宫），也有把北京故宫列入的说法。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-151","t":"巴赫","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"德国巴洛克作曲家，《平均律钢琴曲集》《勃兰登堡协奏曲》《马太受难曲》。","ans":"德国巴洛克作曲家，《平均律钢琴曲集》《勃兰登堡协奏曲》《马太受难曲》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-152","t":"亨德尔","cid":"10h","p":3,"kind":"人物","exam":[],"alias":[],"one":"《弥赛亚》（含《哈利路亚》合唱），《水上音乐》。","ans":"《弥赛亚》（含《哈利路亚》合唱），《水上音乐》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-153","t":"维也纳古典乐派","cid":"10h","p":1,"kind":"合称","alias":["维也纳三杰","古典乐派"],"one":"18世纪后期至19世纪初以维也纳为中心，海顿、莫扎特、贝多芬。","ans":"维也纳古典乐派是**18世纪后期至19世纪初以奥地利首都维也纳为中心的音乐流派**，代表人物是**海顿、莫扎特、贝多芬**，称“维也纳三杰”。他们确立了**交响曲、奏鸣曲、弦乐四重奏、协奏曲**等古典音乐体裁，使**奏鸣曲式**趋于成熟。海顿被称为“交响乐之父”，莫扎特作有歌剧《费加罗的婚礼》《魔笛》，贝多芬把古典主义推向顶峰并开启浪漫主义。该乐派之前是巴洛克的巴赫、亨德尔，之后是舒伯特、肖邦等浪漫派。","pts":["18世纪后期至19世纪初，维也纳","海顿、莫扎特、贝多芬","确立交响曲、奏鸣曲等体裁"],"members":[["海顿","“交响乐之父”，《创世纪》《惊愕交响曲》"],["莫扎特","《费加罗的婚礼》《魔笛》《安魂曲》"],["贝多芬","九部交响曲，“乐圣”"]],"mem":"“海莫贝”三字：海顿、莫扎特、贝多芬，年龄从长到幼（1732、1756、1770）。三人关系：海顿教过贝多芬，莫扎特与海顿是好友。","mix":"巴赫、亨德尔是巴洛克，在古典乐派之前；舒伯特、肖邦、柴可夫斯基是浪漫乐派，在其后；“乐圣”是贝多芬，“音乐神童”常指莫扎特。","mcq":[{"q":"下列作曲家中，不属于维也纳古典乐派的是","o":["海顿","莫扎特","贝多芬","巴赫"],"a":3,"w":"巴赫属于巴洛克时期。"},{"q":"被称为“交响乐之父”的是","o":["莫扎特","贝多芬","舒伯特","海顿"],"a":3,"w":"海顿创作百余部交响曲。"}],"rel":[{"t":"海顿","n":"交响乐之父"},{"t":"莫扎特","n":"神童作曲家"},{"t":"贝多芬","n":"乐圣"},{"t":"巴赫","n":"此前的巴洛克大师"}],"more":"海顿（1732—1809）、莫扎特（1756—1791）、贝多芬（1770—1827）。","exam":[]},{"id":"a10-154","t":"海顿","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"奥地利，交响曲百余部，《惊愕》《告别》；《皇帝颂》旋律后为德国国歌所用。","ans":"奥地利，交响曲百余部，《惊愕》《告别》；《皇帝颂》旋律后为德国国歌所用。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-155","t":"莫扎特","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"奥地利“音乐神童”，歌剧《费加罗的婚礼》《魔笛》《唐璜》，35岁去世。","ans":"奥地利“音乐神童”，歌剧《费加罗的婚礼》《魔笛》《唐璜》，35岁去世。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-156","t":"贝多芬","cid":"10h","p":1,"kind":"人物","alias":["路德维希·凡·贝多芬","乐圣"],"one":"德国“乐圣”，耳聋后创作《英雄》《命运》《合唱》等交响曲。","ans":"路德维希·凡·贝多芬（1770—1827）是**德国作曲家**，生于波恩，后定居维也纳，**维也纳古典乐派的集大成者**，被称为“乐圣”。他26岁前后听力渐衰，晚年**完全失聪**仍坚持创作。代表作有**《英雄》（第三交响曲）、《命运》（第五）、《田园》（第六）、《合唱》（第九）**，其中**《英雄》原题献拿破仑**，**《合唱》末乐章采用席勒《欢乐颂》**，今成为欧盟盟歌的乐曲。另有《月光》《悲怆》《热情》钢琴奏鸣曲。他把古典主义推向顶点并开启浪漫主义，法国作家罗曼·罗兰著有《贝多芬传》，由傅雷译成中文。","pts":["德国乐圣，耳聋后创作，古典乐派集大成","《英雄》《命运》《田园》《合唱》","《合唱》用席勒《欢乐颂》，欧盟盟歌"],"mem":"交响曲编号“三英雄、五命运、六田园、九合唱”。画面：失聪的人用“命运”敲门声敲开人类的大门。联想：席勒写词，贝多芬谱曲，傅雷译传。","mix":"莫扎特是奥地利人，贝多芬是德国人（生于波恩）；《英雄》原题献给拿破仑，其称帝后改题；《欢乐颂》歌词是席勒的诗，贝多芬谱曲；罗曼·罗兰的《贝多芬传》收入《名人传》。","mcq":[{"q":"贝多芬《合唱》交响曲末乐章采用的诗是","o":["歌德《浮士德》","海涅《乘着歌声的翅膀》","席勒《欢乐颂》","拜伦《唐璜》"],"a":2,"w":"席勒《欢乐颂》。"},{"q":"被称为“命运交响曲”的是贝多芬的第几交响曲","o":["第三","第五","第六","第九"],"a":1,"w":"第五交响曲《命运》；第三《英雄》，第六《田园》，第九《合唱》。"}],"rel":[{"t":"维也纳古典乐派","n":"所属乐派"},{"t":"席勒","n":"《欢乐颂》作者"},{"t":"罗曼·罗兰","n":"《贝多芬传》作者"},{"t":"傅雷","n":"《贝多芬传》中译者"},{"t":"拿破仑","n":"《英雄》原题献对象"}],"more":"1802年：写下海利根施塔特遗书。\n1824年：《第九交响曲》首演。\n1827年：逝世于维也纳。","exam":[]},{"id":"a10-157","t":"舒伯特","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"奥地利，《魔王》《鳟鱼》《冬之旅》《未完成交响曲》。","ans":"奥地利，《魔王》《鳟鱼》《冬之旅》《未完成交响曲》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-158","t":"肖邦","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"波兰，夜曲、《革命练习曲》；舒曼称其音乐是“藏在花丛中的大炮”。","ans":"波兰，夜曲、《革命练习曲》；舒曼称其音乐是“藏在花丛中的大炮”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-159","t":"李斯特","cid":"10h","p":3,"kind":"人物","exam":[],"alias":[],"one":"匈牙利，交响诗体裁的创立者。","ans":"匈牙利，交响诗体裁的创立者。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-160","t":"约翰·施特劳斯","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"奥地利（小施特劳斯），《蓝色多瑙河》，维也纳新年音乐会常演曲目。","ans":"奥地利（小施特劳斯），《蓝色多瑙河》，维也纳新年音乐会常演曲目。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-161","t":"柴可夫斯基","cid":"10h","p":2,"kind":"人物","exam":[],"alias":[],"one":"俄国，芭蕾舞剧《天鹅湖》《睡美人》《胡桃夹子》，《悲怆交响曲》，《第一钢琴协","ans":"俄国，芭蕾舞剧《天鹅湖》《睡美人》《胡桃夹子》，《悲怆交响曲》，《第一钢琴协奏曲》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-162","t":"瓦格纳","cid":"10h","p":3,"kind":"人物","exam":[],"alias":[],"one":"德国，提出“乐剧”，《尼伯龙根的指环》。","ans":"德国，提出“乐剧”，《尼伯龙根的指环》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-163","t":"威尔第","cid":"10h","p":3,"kind":"人物","exam":[],"alias":[],"one":"意大利歌剧作曲家，《茶花女》《阿依达》《弄臣》。","ans":"意大利歌剧作曲家，《茶花女》《阿依达》《弄臣》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-164","t":"普契尼《图兰朵》","cid":"10h","p":2,"kind":"作品","exam":[],"alias":[],"one":"意大利普契尼遗作，故事发生在中国，用民歌《茉莉花》旋律；另有《蝴蝶夫人》《艺","ans":"意大利普契尼遗作，故事发生在中国，用民歌《茉莉花》旋律；另有《蝴蝶夫人》《艺术家的生涯》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-165","t":"德彪西","cid":"10h","p":3,"kind":"人物","exam":[],"alias":[],"one":"法国，《牧神午后前奏曲》《月光》。","ans":"法国，《牧神午后前奏曲》《月光》。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-166","t":"七大洲四大洋","cid":"10i","p":2,"kind":"合称","exam":[],"alias":[],"one":"亚洲（面积最大）、非洲、北美洲、南美洲、南极洲、欧洲、大洋洲（面积最小）；太","ans":"亚洲（面积最大）、非洲、北美洲、南美洲、南极洲、欧洲、大洋洲（面积最小）；太平洋、大西洋、印度洋、北冰洋（最小最浅）；2000年国际水文地理组织另划南大洋，故也有五大洋之说。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-167","t":"大洲分界线","cid":"10i","p":2,"kind":"地理","exam":[],"alias":[],"one":"亚欧：乌拉尔山脉、乌拉尔河、里海、大高加索山脉、黑海、土耳其海峡；亚非：苏伊","ans":"亚欧：乌拉尔山脉、乌拉尔河、里海、大高加索山脉、黑海、土耳其海峡；亚非：苏伊士运河；亚洲与北美洲：白令海峡；南北美洲：巴拿马运河；欧非：直布罗陀海峡。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-168","t":"世界河流之最","cid":"10i","p":1,"kind":"常识","alias":["世界最长河流","世界之最河流"],"one":"最长尼罗河，流量与流域面积最大亚马孙河，欧洲最长伏尔加河。","ans":"世界河流之最包括：**最长的河流是非洲的尼罗河**，全长约6670千米，由南向北注入地中海；**流量和流域面积最大的河流是南美洲的亚马孙河**；**长江居世界第三、是亚洲第一长河**；**伏尔加河是欧洲最长河，也是世界最长的内流河**，注入里海；**多瑙河流经国家最多**，约十个。这些河流孕育了古埃及等大河文明或沿岸经济带。名解常把“文明、河流、地理”放在同一材料里考查，需把河流与洲、入海口对应记牢。","pts":["最长：尼罗河（约6670千米）","亚马孙河：流量、流域面积最大","长江亚洲最长；伏尔加河欧洲最长、最长内流河"],"mem":"“长尼、量亚、洲长江、欧伏、国多瑙”（自编）：最长尼罗河，量与面积亚马孙，亚洲最长长江，欧洲最长伏尔加，流经国最多多瑙河。顺序记“长江第三”。","mix":"最长（尼罗河）与流量最大（亚马孙河）不同；世界第二长河一般说亚马孙河或密西西比河系，因测量口径而异，不必死记；伏尔加河是内流河，不入海。","mcq":[{"q":"世界上流量最大、流域面积最广的河流是","o":["尼罗河","长江","亚马孙河","密西西比河"],"a":2,"w":"南美洲亚马孙河。"},{"q":"欧洲最长河流、世界最长的内流河是","o":["多瑙河","莱茵河","伏尔加河","塞纳河"],"a":2,"w":"伏尔加河注入里海。"}],"rel":[{"t":"尼罗河","n":"世界最长河流"},{"t":"长江","n":"亚洲最长河流"},{"t":"古埃及文明","n":"尼罗河孕育"},{"t":"世界地理之最","n":"同类汇总"}],"more":"尼罗河约6670千米；长江约6300千米，居世界第三；伏尔加河约3530千米。","exam":[]},{"id":"a10-169","t":"世界湖泊之最","cid":"10i","p":2,"kind":"常识","exam":[],"alias":[],"one":"最大湖泊、最大咸水湖里海；最大淡水湖苏必利尔湖；最深湖贝加尔湖；湖面海拔最低","ans":"最大湖泊、最大咸水湖里海；最大淡水湖苏必利尔湖；最深湖贝加尔湖；湖面海拔最低死海（约海平面以下430米）；北美五大湖是最大淡水湖群。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-170","t":"世界山地、高原、平原、盆地之最","cid":"10i","p":2,"kind":"常识","exam":[],"alias":[],"one":"最高峰珠穆朗玛峰（8848.86米）；最长山脉安第斯山脉；最高高原青藏高原，","ans":"最高峰珠穆朗玛峰（8848.86米）；最长山脉安第斯山脉；最高高原青藏高原，面积最大高原巴西高原；最大平原亚马孙平原；最大盆地刚果盆地。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-171","t":"世界沙漠、岛屿、半岛之最","cid":"10i","p":2,"kind":"常识","exam":[],"alias":[],"one":"最大沙漠撒哈拉沙漠（不计极地）；最大岛屿格陵兰岛；最大群岛马来群岛；最大半岛","ans":"最大沙漠撒哈拉沙漠（不计极地）；最大岛屿格陵兰岛；最大群岛马来群岛；最大半岛阿拉伯半岛。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-172","t":"世界海洋之最","cid":"10i","p":2,"kind":"常识","exam":[],"alias":[],"one":"太平洋面积最大、平均最深；马里亚纳海沟最深（约1.1万米）；最大的海珊瑚海；","ans":"太平洋面积最大、平均最深；马里亚纳海沟最深（约1.1万米）；最大的海珊瑚海；最大海湾孟加拉湾；最长海峡莫桑比克海峡；最宽最深海峡德雷克海峡；英吉利海峡是通航最繁忙的海峡之一。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-173","t":"国家之最","cid":"10i","p":2,"kind":"常识","exam":[],"alias":[],"one":"面积最大俄罗斯，最小梵蒂冈；人口最多印度（2023年超过中国）；陆上邻国最多","ans":"面积最大俄罗斯，最小梵蒂冈；人口最多印度（2023年超过中国）；陆上邻国最多的是中国和俄罗斯（各14个）。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-174","t":"苏伊士运河","cid":"10i","p":1,"kind":"地理","alias":["苏伊士"],"one":"埃及，1869年通航，沟通地中海与红海，亚非分界，无船闸。","ans":"苏伊士运河位于**埃及**，**1869年通航**，由法国人雷塞布主持开凿，**沟通地中海与红海**，是亚洲与非洲的分界线之一。运河连通欧亚，使船舶**从欧洲到印度洋无需绕行非洲好望角**，大幅缩短航程。因两端水位相近，它是**不设船闸的海平面运河**，与设船闸的巴拿马运河不同。1956年埃及总统纳赛尔宣布运河国有化，引发苏伊士运河危机；2021年曾因“长赐号”货轮搁浅而堵塞。它是世界海运的咽喉要道。","pts":["埃及，1869年通航","沟通地中海与红海，亚非分界","无船闸，免绕好望角"],"mem":"“苏红地”：苏伊士沟通红海与地中海。对比口诀：苏平巴闸：苏伊士平（无闸），巴拿马闸。年份“六九”：1869通苏伊士，1914通巴拿马，相差45年。","mix":"苏伊士运河（1869，海平面）与巴拿马运河（1914，船闸）通航机制不同；苏伊士分亚、非，巴拿马分南、北美；红海与亚丁湾之间是曼德海峡。","mcq":[{"q":"苏伊士运河沟通的两片海域是","o":["地中海与红海","红海与波斯湾","大西洋与太平洋","黑海与地中海"],"a":0,"w":"地中海与红海。"},{"q":"关于苏伊士运河，下列说法正确的是","o":["1914年通航","设有多道船闸","位于巴拿马","位于埃及，无船闸"],"a":3,"w":"1869年通航，无船闸。"}],"rel":[{"t":"巴拿马运河","n":"通航机制对比"},{"t":"地中海","n":"北端连接"},{"t":"大洲分界线","n":"亚非分界"},{"t":"好望角","n":"运河开通前的绕行航线"}],"more":"1869年：通航。\n1956年：国有化，引发苏伊士运河危机。\n2021年3月：“长赐号”搁浅。","exam":[]},{"id":"a10-175","t":"巴拿马运河","cid":"10i","p":1,"kind":"地理","alias":["巴拿马"],"one":"巴拿马，1914年通航，沟通太平洋与大西洋，南北美分界，船闸式。","ans":"巴拿马运河位于**中美洲的巴拿马**，**1914年通航**，由美国建成，**沟通太平洋与大西洋**，是南北美洲的分界线。它是**船闸式运河**，船只需通过船闸抬升以翻越地峡，与无船闸的苏伊士运河不同。运河使船舶从美国东岸到西岸**免绕南美洲南端的合恩角**，大幅缩短航程。1999年底美国将运河主权交还巴拿马，2016年新船闸启用，可通行更大的船舶。它与苏伊士运河并为世界两大海运要道。","pts":["巴拿马，1914年通航","沟通太平洋与大西洋，南北美分界","船闸式运河，1999年归还巴拿马"],"mem":"“巴拿闸、苏伊平”：巴拿马要用船闸，苏伊士是平的。画面：船在地峡上一级一级被水抬上去再放下来。","mix":"巴拿马运河（船闸式，南北美分界）与苏伊士运河（海平面式，亚非分界）常被混；“太平洋到大西洋”在巴拿马，“地中海到红海”在苏伊士。","mcq":[{"q":"沟通太平洋与大西洋的运河是","o":["苏伊士运河","基尔运河","京杭大运河","巴拿马运河"],"a":3,"w":"巴拿马运河，1914年通航。"},{"q":"关于巴拿马运河，下列说法正确的是","o":["设有船闸","无船闸","位于埃及","1869年通航"],"a":0,"w":"船闸式运河，位于巴拿马，1914年通航。"}],"rel":[{"t":"苏伊士运河","n":"通航机制对比"},{"t":"大洲分界线","n":"南北美分界"},{"t":"基尔运河","n":"另一条重要运河"},{"t":"七大洲四大洋","n":"沟通大洋"}],"more":"1914年：通航。\n1999年：美国移交主权。\n2016年：新船闸启用。","exam":[]},{"id":"a10-176","t":"马六甲海峡","cid":"10i","p":1,"kind":"地理","alias":["马六甲"],"one":"位于马来半岛与苏门答腊岛之间，沟通太平洋与印度洋的要道。","ans":"马六甲海峡位于**马来半岛与苏门答腊岛之间**，北通安达曼海，南接南海，**沟通太平洋与印度洋**，是亚欧、中东与东亚间的海上要道。沿岸有马来西亚、印度尼西亚和新加坡。海峡**长约1000千米**，是世界最繁忙的海峡之一，中国进口的大量原油经此运输，因此有“马六甲困局”的说法。它是**海上丝绸之路的重要节点**，明代郑和下西洋曾在此设立据点，海峡因马六甲古城而得名。","pts":["马来半岛与苏门答腊岛之间","沟通太平洋与印度洋","海上丝路要道，中国能源通道"],"mem":"“马苏夹印太”：马来半岛、苏门答腊夹出海峡，连印度洋与太平洋。画面：东亚的货船都要从这条细长水道穿过。","mix":"马六甲海峡（太平洋—印度洋）、直布罗陀海峡（地中海—大西洋）、霍尔木兹海峡（波斯湾—阿曼湾）、博斯普鲁斯海峡（黑海—马尔马拉海）易混；苏门答腊岛属印度尼西亚。","mcq":[{"q":"沟通太平洋与印度洋的重要海峡是","o":["直布罗陀海峡","霍尔木兹海峡","马六甲海峡","博斯普鲁斯海峡"],"a":2,"w":"马六甲海峡。"},{"q":"马六甲海峡位于下列哪两地之间","o":["马来半岛与苏门答腊岛","朝鲜半岛与日本","印度半岛与斯里兰卡","中南半岛与海南岛"],"a":0,"w":"马来半岛与苏门答腊岛之间。"}],"rel":[{"t":"丝绸之路","n":"海上丝路要道"},{"t":"直布罗陀海峡","n":"同为要道海峡"},{"t":"霍尔木兹海峡","n":"同为能源通道"},{"t":"七大洲四大洋","n":"沟通两大洋"}],"more":"2010年选择题涉及苏门答腊岛与马六甲海峡的位置关系。","exam":[]},{"id":"a10-177","t":"直布罗陀海峡","cid":"10i","p":2,"kind":"地理","exam":[],"alias":[],"one":"西班牙与摩洛哥之间，地中海通往大西洋的门户，古称“赫拉克勒斯之柱”。","ans":"西班牙与摩洛哥之间，地中海通往大西洋的门户，古称“赫拉克勒斯之柱”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-178","t":"土耳其海峡（博斯普鲁斯与达达尼尔）","cid":"10i","p":2,"kind":"地理","exam":[],"alias":[],"one":"博斯普鲁斯海峡沟通黑海与马尔马拉海，达达尼尔海峡沟通马尔马拉海与爱琴海，合称","ans":"博斯普鲁斯海峡沟通黑海与马尔马拉海，达达尼尔海峡沟通马尔马拉海与爱琴海，合称土耳其海峡，亚欧分界；伊斯坦布尔跨两洲。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-179","t":"霍尔木兹海峡","cid":"10i","p":2,"kind":"地理","exam":[],"alias":[],"one":"伊朗与阿曼之间，连接波斯湾与阿曼湾，被称为“世界石油咽喉”。","ans":"伊朗与阿曼之间，连接波斯湾与阿曼湾，被称为“世界石油咽喉”。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-180","t":"白令海峡","cid":"10i","p":2,"kind":"地理","exam":[],"alias":[],"one":"亚洲与北美洲、太平洋与北冰洋的分界，国际日期变更线经过此处。","ans":"亚洲与北美洲、太平洋与北冰洋的分界，国际日期变更线经过此处。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-181","t":"英吉利海峡与英法海底隧道","cid":"10i","p":3,"kind":"地理","exam":[],"alias":[],"one":"多佛尔海峡最窄处约33千米；1994年英法海底隧道通车。","ans":"多佛尔海峡最窄处约33千米；1994年英法海底隧道通车。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-182","t":"曼德海峡","cid":"10i","p":3,"kind":"地理","exam":[],"alias":[],"one":"连接红海与亚丁湾，与苏伊士运河构成欧亚最短航线。","ans":"连接红海与亚丁湾，与苏伊士运河构成欧亚最短航线。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-183","t":"基尔运河","cid":"10i","p":3,"kind":"地理","exam":[],"alias":[],"one":"德国，连接北海与波罗的海。","ans":"德国，连接北海与波罗的海。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-184","t":"易错首都","cid":"10i","p":2,"kind":"常识","exam":[],"alias":[],"one":"澳大利亚堪培拉（非悉尼），加拿大渥太华，巴西巴西利亚，土耳其安卡拉（非伊斯坦","ans":"澳大利亚堪培拉（非悉尼），加拿大渥太华，巴西巴西利亚，土耳其安卡拉（非伊斯坦布尔），新西兰惠灵顿，瑞士伯尔尼，缅甸内比都，哈萨克斯坦阿斯塔纳，尼日利亚阿布贾，巴基斯坦伊斯兰堡；南非行政首都比勒陀利亚、立法首都开普敦、司法首都布隆方丹；印尼计划迁都东加里曼丹努桑塔拉（进展需核实）。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-185","t":"国家别称","cid":"10i","p":2,"kind":"常识","exam":[],"alias":[],"one":"千岛之国印度尼西亚，千湖之国芬兰，风车之国荷兰，枫叶之国加拿大，骑在羊背上的","ans":"千岛之国印度尼西亚，千湖之国芬兰，风车之国荷兰，枫叶之国加拿大，骑在羊背上的国家澳大利亚，樱花之国日本，白象之国泰国，冰与火之国冰岛。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-186","t":"东非大裂谷","cid":"10i","p":3,"kind":"地理","exam":[],"alias":[],"one":"板块张裂形成，人类起源的重要地区。","ans":"板块张裂形成，人类起源的重要地区。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-187","t":"环太平洋火山地震带","cid":"10i","p":3,"kind":"地理","exam":[],"alias":[],"one":"全球地震和火山最集中的地带，日本、智利、印度尼西亚等位于其上。","ans":"全球地震和火山最集中的地带，日本、智利、印度尼西亚等位于其上。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a10-188","t":"拉丁美洲","cid":"10i","p":3,"kind":"地理","exam":[],"alias":[],"one":"美国以南的美洲地区，因通行西班牙语、葡萄牙语等拉丁语族语言得名；巴西讲葡萄牙","ans":"美国以南的美洲地区，因通行西班牙语、葡萄牙语等拉丁语族语言得名；巴西讲葡萄牙语。","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1}],"tables":[{"name":"大河文明速查","note":"“两河流域是哪两条河”是2010选择原题；美索不达米亚是希腊语“两河之间的地方”。四大文明古国通常指古巴比伦、古埃及、古印度、中国。","rows":[["文明","河流","今地","文字与标志成就"],["两河流域（美索不达米亚）","幼发拉底河、底格里斯河","伊拉克一带","楔形文字（泥板）、《汉谟拉比法典》、《吉尔伽美什》、六十进制"],["古埃及","尼罗河","埃及","象形文字（纸莎草）、金字塔、狮身人面像、太阳历、木乃伊"],["古印度（印度河文明）","印度河","主要在巴基斯坦","哈拉帕、摩亨佐-达罗城市规划，印章文字至今未释读"],["古代中国","黄河、长江","中国","甲骨文、青铜器、二里头与殷墟"]]},{"name":"西域古国与今地","note":"","rows":[["古国","今地","考点"],["大宛","中亚费尔干纳盆地（今乌兹别克斯坦等国交界）","产汗血马，汉武帝遣李广利伐大宛得马，号“天马”"],["大月氏","阿姆河流域","张骞第一次出使的目的地"],["乌孙","伊犁河流域","张骞第二次出使的目的地，细君公主、解忧公主和亲"],["安息","伊朗高原（帕提亚帝国）","2011选择原题"],["身毒","印度","2011选择原题"],["大夏","阿富汗北部（巴克特里亚）","张骞在此见到邛竹杖、蜀布"],["大秦","罗马帝国","东汉甘英出使大秦，到达波斯湾而还"]]},{"name":"世界地理易考对应","note":"苏伊士运河与巴拿马运河的通航机制对比是每日练错题（●）：前者两端水位相近，不设船闸；后者需用船闸抬升船只翻越地峡。","rows":[["名称","位置","考点"],["帕米尔高原","中国新疆西南，邻塔吉克斯坦、阿富汗、巴基斯坦","古称葱岭，丝路必经之地（2010选择）"],["塔克拉玛干沙漠","新疆塔里木盆地中部","中国最大沙漠，世界第二大流动沙漠（2010选择）"],["苏门答腊岛","印度尼西亚西部","隔马六甲海峡与马来半岛相望（2010选择）"],["伊朗高原","西亚，包括伊朗大部和阿富汗、巴基斯坦西部","波斯帝国的发源地（2017名解）"],["尼罗河","东北非，北注地中海","全长约6670千米，世界最长河流之一"],["苏伊士运河","埃及","1869年通航，沟通地中海与红海，无船闸的海平面运河"],["巴拿马运河","巴拿马","1914年通航，沟通太平洋与大西洋，船闸式运河"],["马六甲海峡","马来半岛与苏门答腊岛之间","沟通太平洋与印度洋的要道"],["直布罗陀海峡","西班牙与摩洛哥之间","地中海通往大西洋的门户"],["博斯普鲁斯海峡","土耳其伊斯坦布尔","沟通黑海与马尔马拉海，亚欧分界"]]}]});